(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.1"]={"from":24,"a":[["\u0003חדא הוא\u0004 \u0005[\u0006קושיה \u0005אחת היא]\u0006 בעצם, \u0003דחד טעם\u0004 \u0005[שטעם אחד]\u0006 \u0003הוא\u0004 שהביא את רבי אלעזר לומר כן, ש\u0003משום דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רבי אלעזר\u0004 שה\u0003מחלוקת\u0004 היא \u0003בשאין חייב מודה\u0004 — \u0003הוא מתרץ הכי\u0004 \u0005[\u0006היה \u0005מיישב,\u0006 מסביר \u0005כך]\u0006 את דברי רבי מאיר והכמים, ונדחו דבריו בנקודה זו.","וכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ל\u0003שמואל בתרתי\u0004 \u0005[בשתי\u0006 נקודות\u0005]:\u0006 \u0003חדא\u0004 \u0005[\u0006קושיה \u0005אחת]\u0006 כפולה \u0003כר' אלעזר, דהא מוקי מתניתין\u0004 \u0005[שהרי\u0006 הוא \u0005מעמיד,\u0006 מסביר, את \u0005משנתנו]\u0006 \u0003בשאין\u0004 ה\u0003חייב מודה\u0004 וראינו שאינו כן.","\u0003וחדא\u0004 \u0005[ו\u0006קושיה \u0005אחת]\u0006 נוספת, ש\u0003אמר שמואל: מצא שטר הקנאה בשוק,\u0004 שמפורש בו שהלווה מקנה את נכסיו למלוה משעת החתימה — \u0003יחזיר\u0004 אותו \u0003לבעלים, ולא חיישינן\u0004 \u0005[ואין אנו חוששים]\u0006 \u0003לפרעון,\u0004 ואם כן הרי זו","\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדבריו אלה. \u0003דקתני הכא\u0004 \u0005[ששנינו כאן]:\u0006 \u0003אף על פי ששניהם מודים\u0004 — \u0003לא יחזיר לא לזה ולא לזה, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לפרעון, וכל שכן הכא\u0004 \u0005[כאן],\u0006 בשטר הקנאה ש\u0003לא מודה\u0004 ה\u0003לוה\u0004 שהוא חייב, שבודאי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לפרעון\u0004 השטר.","\u0003אמר שמואל: מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 האומרים שגובה מנכסים משועבדים אף כשאין בשטר אחריות מפורשת? — \u0003סברי\u0004 \u0005[סבורים\u0006 הם\u0005]\u0006 ש\u0003אחריות טעות סופר הוא.\u0004 כלומר, שטר הלואה שלא נכתב בו בטחון זה של אחריות נכסים, מן הסתם היתה זו רק טעותו של הסופר שהשמיט את הדבר שבודאי אין אדם מלוה כסף בלא לקבל בטחונות להחזרת החוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר איתי לרב אידי בר אבין: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005כך]\u0006 שאחריות טעות סופר? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: שבח, שפר ושעבוד\u0004 — \u0003צריך לימלך!\u0004 שכאשר כותב סופר שטר על מכירת שדה צריך הוא לשאול את המוכר האם לכתוב במפורש שאם יתברר ששדה זה היה משועבד כבר וילקח מן הקונה, שישלם את כל השבח שישביח הקונה בשדה, ותשלום זה ישלם לו מן השפר (המובחר, עידית) שבנכסיו, וכן שהוא משעבד את כל נכסיו להיות אחראים למכירה זו.","הרי ששמואל עצמו סבור שאחריות אינה נכתבת בכל שטר, ואם כן \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003לא אמר הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 ושמא מחלוקת היא בין מוסרי שמועותיו של שמואל?","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שאמר שמואל \"אחריות טעות סופר\" הוא \u0003בשטר הלואה, דלא יהיב אינש זוזי בכדי\u0004 \u0005[שאין אדם נותן כסף חינם]\u0006 וכשמלוה, רוצה הוא שיובטח לו הפרעון. ואילו \u0003כאן\u0004 שאמר שאחריות היא דבר שצריך הסופר לשאול אם בכלל לכתוב הוא \u0003במקח וממכר\u0004 וקניית קרקעות, \u0003דעביד אינש דזבין ארעא ליומיה\u0004 \u0005[שעשוי אדם לקנות קרקע ליומו,\u0006 ליום אחד\u0005],\u0006 שייתכן שהקונה מוכן לקבל על עצמו את הסיכון שהקרקע הזו משועבדת כבר, אלא שהוא חושב כי יוכל להרויח מן השדה עד שיתברר הדבר.","וראיה לתירוץ זה, \u0003כי ההיא\u0004 \u0005[כמו אותו מעשה]\u0006 \u0003דאבוה בר איהי זבין עליתא מאחתיה\u0004 \u0005[קנה עליית־גג מאחותו],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003בעל חוב\u0004 של אחותו \u0003טרפא מיניה\u0004 \u0005[\u0006ו\u0005לקחה ממנו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003מר שמואל\u0004 לתבוע מאחותו. \u0003אמר ליה\u0004 שמואל: האם \u0003כתבה לך אחריות\u0004 על מכירה זו? \u0003אמר ליה: לא. אמר ליה\u0004 \u0005[אמר לו]\u0006 שמואל לאבוה בר איהי: \u0003אם כן, זיל לשלמא\u0004 \u0005[לך לשלום]\u0006 שאין לעשות דבר בענין זה. \u0003אמר ליה\u0004 אבוה בר איהי לשמואל: \u0003והא מר הוא דאמר\u0004 \u0005[והרי אדוני הוא שאמר]\u0006 \u0003אחריות טעות סופר הוא,\u0004 ואף כאן נאמר, שהאחריות הריהי כאילו כתובה בשטר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 שאמרתי\u0005]\u0006 הם \u0003בשטרי הלואה, אבל בשטרי מקח וממכר\u0004 — \u0003לא\u0004 אמרתי, \u0003דעביד אינש דזבין ארעא ליומיה\u0004 \u0005[שעשוי אדם שיקנה קרקע ליומו].\u0006","\u0003אמר אביי: ראובן שמכר שדה לשמעון באחריות, ובא בעל חוב\u0004 של \u0003ראובן וקא טריף ליה מיניה\u0004 \u0005[ורוצה לטרוף\u0006 את השדה \u0005ממנו,\u0006 משמעון\u0005]\u0006 מפני שיש לו עליו שעבוד קודם, \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דאזיל\u0004 \u0005[שהולך],\u0006 יכול ללכת \u0003ראובן ומשתעי דינא בהדיה\u0004 \u0005[ולדבר עמו בדין]\u0006 ולהתווכח עם בעל החוב ביחס לזכותו על הנכס, \u0003ולא מצי אמר ליה\u0004 \u0005[ואינו יכול\u0006 בעל החוב \u0005לומר\u0006 לראובן\u0005]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בעל דברים דידי את\u0004 \u0005[שלי אתה],\u0006 שהרי את הנכס כבר מכרת לשמעון, ולי אין עכשיו כל משא ומתן אתך, אלא עם המחזיק בנכס שהוא שמעון, ושמעון מצדו יכול לתבוע אותך לדין. ומדוע? \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 ראובן לבעל חובו: \u0003דמפקת מיניה, עלי דידי הדר\u0004 \u0005[\u0006מה \u0005שאתה מזציא ממנו\u0006 הלא \u0005יחזור אלי]\u0006 כיון שמכרתי את השדה באחריות, ואין אתה יכול לומר שאין אני נוגע בדבר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאמר אביי: \u0003אפילו\u0004 מכר ראובן לשמעון \u0003שלא באחריות נמי\u0004 \u0005[גם כן]\u0006 יכול ראובן לומר שהוא צד, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 ראובן לבעל החוב: \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דליהוי\u0004 \u0005[שתהיה]\u0006 \u0003לשמעון תרעומת עלי\u0004 שמכרתי לו דבר שאין הוא יכול להחזיק בו.","\u0003ו\u0004עוד \u0003אמר אביי\u0004 בדינים דומים: \u0003ראובן שמכר שדה לשמעון שלא באחריות, ויצאו עליה עסיקין,\u0004 כלומר, התחילו לבוא עוררים הטוענים לבעלותם על שדה זה, \u0003עד שלא החזיק בה\u0004 שמעון בשדה על ידי פעולה הקובעת את התחלת קניינו בשדה,"],["\u0003יכול\u0004 שמעון \u0003לחזור בו, משהחזיק בה\u0004 — \u0003אינו יכול לחזור בו. דאמר לו\u0004 \u0005[שאומר לו]\u0006 ראובן המוכר: \u0003חייתא דקטרי סברת וקבלת\u0004 \u0005[חבילה של קשרים סברת וקבלת],\u0006 שהרי קנית שלא באחריות, והיית צריך להביא בחשבון שאתה מסתכן בבעלי דינים. ושואלים: \u0003מאימתי הויא\u0004 \u0005[הרי היא]\u0006 בענין זה \u0003חזקה?\u0004 — \u0003מכי דייש אמצרי\u0004 \u0005[מזמן ש\u0006הוא \u0005מתקן\u0006 את \u0005גבולות\u0006 השדה\u0005].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003אפילו\u0004 אם קונה \u0003באחריות נמי\u0004 \u0005[גם כן]\u0006 אינו יכול לחזור בו, ולבטל את המכירה אם נעשתה כדינה, אף שאחר כך יוכל לתבוע את המוכר, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003אחוי טרפך\u0004 \u0005[הראה\u0006 לי את \u0005שטר הטריפה]\u0006 \u0003ו\u0004אז \u0003אשלם לך,\u0004 כלומר, אינני רוצה לבטל את המכירה, אלא כשייגמר הדבר ולכשיתברר שנלקח ממך השדה תוכל לבוא אלי ואז אפצה אותך.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003המוכר שדה לחבירו ונמצאת שאינה שלו\u0004 של המוכר, ולקחו בעלי השדה את השדה מיד הקונה, ומעתה הוא תובע את כספו מיד המוכר. \u0003רב אמר: יש לו\u0004 לקונה \u0003מעות,\u0004 כלומר, הוא מקבל בחזרה את הכסף ששילם \u0003ויש לו שבח\u0004 ומקבל גם את התשלום על שהשביח את השדה במשך הזמן שטיפל בו. \u0003ושמואל אמר: מעות\u0004 — \u0003יש לו, שבח\u0004 — \u0003אין לו.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב הונא:\u0004 \u0003פירש לו את השבח מהו?\u0004 כלומר, מה הדין אם בשטר המכירה כתב המוכר לקונה שכל שבח שישביח הקונה את השדה כל זמן שמחזיק בו יקבל תמורתו מידי המוכר אם ילקח השדה מן הקונה, מה יהיה אז הדין? ונברר: האם \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003שמואל\u0004 הוא \u0003משום\u0004 ש\u0003לא פירש שבחא\u0004 \u0005[את השבח]\u0006 בשטר, \u0003והכא הא פירש לה\u0004 \u0005[וכאן הרי פירש אותו],\u0006 \u0003או דלמא טעמיה\u0004 \u0005[שמא טעמו]\u0006 של \u0003שמואל\u0004 אחר: \u0003כיון דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003קרקע\u0004 למוכר, ונמצא שהלוקח מקבל בחזרה ממוכר זה את כספו, ואם כן \u0003מחזי\u0004 \u0005[נראה]\u0006 \u0003כריבית,\u0004 שאם הוא משלם עבור השבח נמצא כאילו שילם לו ריבית על משך הזמן שהיה כסף השדה בידי המוכר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין ולאו, ורפיא בידיה\u0004 \u0005[כן ולא, ורופף\u0006 היה הדבר \u0005בידו],\u0006 כלומר אמר מתחילה כן, ואחר כך לא ולא יכול רב הונא להחליט מה הדין.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בדבר, \u0003אמר רב נחמן אמר שמואל: מעות\u0004 — \u0003יש לו, שבח\u0004 — \u0003אין לו, אף על פי שפירש לו השבח. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון\u0004 ש\u0003קרקע אין לו\u0004 ואם כן נמצא ש\u0003שכר מעותיו עומד ונוטל\u0004 והרי זה כריבית.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן:\u0004 שנינו ש\u0003אין מוציאין לאכילת פירות, ולשבח קרקעות, ולמזון האשה והבנות\u0004 שהתחייב אדם לפרנסן בשטר הכתובה שנתן לאשתו \u0003מנכסים משועבדים\u0004 למרות שהתחייבויות אלה היו קודמות, ועשו זאת \u0003מפני תיקון העולם\u0004 שלא ייגרמו נזקים ללקוחות, שהרי כל אדם יש לו התחייבויות כעין אלה, ונמצא כל מקח עלול להתבטל בגללן.","ונדייק: \u0003ממשעבדי\u0004 \u0005[מ\u0006נכסים \u0005משועבדים]\u0006 \u0003הוא דלא מפקינן\u0004 \u0005[הוא שאין אנו מוציאים],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם היו אלה נכסים \u0003בני חורין\u0004 — \u0003מפקינן\u0004 \u0005[מוציאים אנו],\u0006 \u0003וקתני מיהא\u0004 \u0005[ולמדנו על כל פנים]\u0006 כי מוציאים \u0003לשבח קרקעות, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003בלוקח\u0004 (קונה) שדה \u0003מגזלן\u0004 שהתברר שהשדה אינו שלו, שצריך הגזלן להחזיר גם את השבח!","ודוחים: \u0003לא.\u0004 כאן מדובר \u0003בבעל חוב\u0004 שמכר שדה משלו, אלא שלאחר מכן טרפו אותו מיד הקונה בשל חובותיו המוקדמים של המוכר.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בבעל חוב, אימא רישא\u0004 \u0005[אמור את ראשה\u0006 של משנה זו\u0005]:\u0006 \u0003אין מוציאין לאכילת פירות,\u0004 ואנו מבינים כי הכוונה היא שלקחו מן המחזיק בשדה את שדהו כשהוא מלא פירות שלא נקטפו עדיין, ועתה הוא מנסה לקבל תמורתם מן המוכר, \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בבעל חוב, בעל חוב מי אית ליה פירי\u0004 \u0005[האם יש לו פירות]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: בעל חוב גובה את השבח.\u0004 ונדייק: \u0003שבח\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל פירות\u0004 — \u0003לא!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכאן מדובר \u0003בגוזל ונגזל\u0004. \u0003ומדרישא\u0004 \u0005[ומכיון שבראש\u0006 המשנה\u0005]\u0006 מדובר \u0003בגוזל ונגזל, סיפא נמי\u0004 \u0005[\u0006ב\u0005סופה גם כן]\u0006 מדובר \u0003בגוזל ונגזל.\u0004 וחוזרת איפוא הקושיה על שמואל!","ודוחים: \u0003מידי אריא\u0004 \u0005[וכי שייכים\u0006 הם זה לזה\u0005]?!\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כפי שהיא וזו כפי שהיא],\u0006 שכל חלק מן המשנה עומד בפני עצמו, ומאחר ומדובר בענין לעצמו אין איפוא להוכיח משם דבר.","ומקשים עוד: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא תני הכי\u0004 \u0005[שנינו כך],\u0006 שכן שנינו: \u0003לשבח קרקעות כיצד?\u0004 — \u0003הרי שגזל שדה מחבירו והרי היא יוצאה\u0004 (יוצאת) \u0003מתחת ידו\u0004 על ידי בית דין, \u0003כשהוא גובה\u0004 — \u0003גובה את הקרן מנכסים משועבדים, ו\u0004את ה\u0003שבח\u0004 — \u0003גובה מנכסים בני חורין.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא כדקתני\u0004 \u0005[אם נאמר\u0006 בדיוק \u0005כפי ששנינו\u0006 שם\u0005],\u0006 שנושא המשפט הוא אותו אדם, הגזלן עצמו, \u0003גזלן ממאן גבי\u0004 \u0005[ממי\u0006 הוא \u0005גובה],\u0006 כלומר, מה יש לו לגבות? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שם במקרה כעין זה: \u0003כגון שגזל שדה מחבירו, ומכרה לאחר, והשביחה\u0004 הקונה, וכשלוקחים בית הדין את השדה הגזול מידו הריהו גובה את השבח מנכסים בני חורין של הגזלן־המוכר!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 שמואל: \u0003לאו תרוצי קא מתרצת\u0004 \u0005[וכי אין אתה מיישב]\u0006 את המשנה ומוסיף בה דברים? \u0003תריץ נמי\u0004 \u0005[תרץ גם כן]\u0006 שמדובר פה לא בגזלן אלא \u0003בבעל חוב,\u0004 ובמקום \"שגזל\" גרוס: \"שמכר\", ואם כן אין מכאן ראיה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003לאכילת פירות כיצד?\u0004 \u0003הרי שגזל שדה מחבירו והרי היא יוצאה\u0004 (יוצאת) \u0003מתחת ידו, כשהוא גובה\u0004 — \u0003גובה את הקרן מנכסים משועבדים, ופירות גובה מנכסים בני חורין.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 \u0003אילימא כדקתני\u0004 \u0005[אם תאמר\u0006 בדיוק \u0005כפי ששנינו]\u0006 \u0003גזלן ממאן גבי\u0004 \u0005[ממי\u0006 הוא \u0005גובה]?\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 זו היא הכוונה: \u0003כגון שגזל שדה מחבירו ומכרה לאחר ו\u0004אותו קונה \u0003השביחה\u0004 וקשה לשמואל!","\u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שגזל שדה מחבירו\u0004 והיתה השדה \u0003מלאה פירות, ואכל את הפירות, וחפר בה\u0004 בשדה \u0003בורות, שיחין ומערות\u0004 וקלקל את השדה, ומעתה, אם \u0003בא\u0004 ה\u0003נגזל לגבות\u0004 את ה\u0003קרן,\u0004 כלומר, דמי השדה עצמו שקלקל — \u0003גובה מנכסים משועבדים,\u0004 ואם \u0003בא\u0004 ה\u0003נגזל לגבות\u0004 את ה\u0003פירות\u0004 מן הגזלן — \u0003גובה מנכסים בני חורין.\u0004","ואילו \u0003רבה בר רב הונא אמר: כגון\u0004"],["\u0003שנטלוה מסיקין\u0004 (גויים), שלקחו בכוח את השדה מחמת עסקיהם הקודמים עם הגזלן, ובכגון זה אם \u0003בא\u0004 ה\u0003נגזל לגבות\u0004 את ה\u0003קרן\u0004 — הריהו \u0003גובה מנכסים משועבדים,\u0004 ואם \u0003בא\u0004 ה\u0003נגזל לגבות\u0004 את ה\u0003פירות\u0004 — הריהו \u0003גובה מנכסים בני חורין.\u0004","ומסבירים: \u0003רבא לא אמר\u0004 ותירץ \u0003כרבה בר רב הונא,\u0004 משום שהלשון \u0003\"הרי היא יוצאה\u0004 (יוצאת) \u0003מתחת ידו\", בדינא\u0004 \u0005[בדין]\u0006 \u0003משמע,\u0004 ולא על ידי גזלנים. \u0003ו\u0004אילו \u0003רבה בר רב הונא לא אמר כרבא\u0004 כי הלשון \u0003\"הרי היא יוצאה מתחת ידו\"\u0004 — \u0003בעינא\u0004 \u0005[בעין]\u0006 \u0003משמע\u0004 ולא שהיא מקולקלת.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003לצדדין קתני,\u0004 כלומר, אין ההלכות עוסקות באותו נושא, אלא בשני נושאים שונים: \u0003כגון שגזל שדה מחבירו\u0004 כשהיא \u0003מלאה פירות, ואכל את הפירות ומכר את השדה,\u0004 ואם \u0003בא\u0004 ה\u0003לוקח לגבות\u0004 את ה\u0003קרן\u0004 — הריהו \u0003גובה מנכסים משועבדים\u0004 של הגזלן. ואם \u0003בא\u0004 ה\u0003נגזל לגבות\u0004 את ה\u0003פירות\u0004 מן הגזלן — הריהו \u0003גובה מנכסים בני חורין.\u0004","ושואלים: \u0003בין לרבא בין לרבה בר רב הונא\u0004 הלא \u0003מלוה על פה הוא,\u0004 שכל מה שלוקח הנגזל מן הגזלן הרי איננו כהחזרת חוב בשטר, אלא כמלוה על פה, \u0003ו\u0004הרי \u0003מלוה על פה אינו גובה מנכסים משועבדים!\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003כשעמד\u0004 הגזלן \u0003בדין\u0004 על שגזל קרקע, וכבר התפרסם הדבר שלקח קרקע בגזלנות ובכל זאת \u0003הדר זבין\u0004 \u0005[חזר ומכר]\u0006 את הקרקע.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ב\u0003פירות נמי\u0004 \u0005[גם כן]\u0006 יגבה ממשועבדים! ומסבירים: \u0003כשעמד בדין על הקרן, ולא עמד בדין על הפירות.\u0004 ושואלים: \u0003ומאי פסקא\u0004 \u0005[ומה הפסק],\u0006 כלומר, מדוע מפרש אתה את הדבר ומחלק דווקא כך, על מה עמד ועל מה לא עמד בדין? ומסבירים: \u0003סתמא דמילתא כי תבע איניש\u0004 \u0005[סתמו של דבר, כאשר תובע אדם]\u0006 — \u0003קרנא תבע ברישא\u0004 \u0005[\u0006את \u0005הקרן,\u0006 גוף התביעה הוא \u0005תובע בראש]\u0006 ורק אחר כך תובע הוא את שאר הדברים, כגון פירות.","ושואלים לגופו של ענין: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003שמואל\u0004 כי ה\u0003לוקח\u0004 (קונה) \u0003מגזלן לית ליה שבחא\u0004 \u0005[אין לו שבח]?\u0006","\u0003והא\u0004 \u0005[והרי]\u0006 מסופר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל לרב חיננא בר שילת\u0004 שהיה סופר: \u0003אמליך\u0004 \u0005[הימלך,\u0006 שקול את הצדדים\u0005],\u0006 \u0003וכתוב\u0004 אם הסכימו לכך בעלי הדבר \u0003\"שופרא, שבחא ופירי\",\u0004 שזהו נוסח מקובל בשטרות מכירה.","ונברר: \u0003במאי\u0004 \u0005[במה\u0006 מדובר כאן\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בבעל חוב\u0004 — \u0003מי אית ליה פירי\u0004 \u0005[האם יש לו,\u0006 לבעל חוב \u0005פירות]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: בעל חוב גובה את השבח,\u0004 ונדייק: \u0003שבח\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 אבל \u0003פירות\u0004 — \u0003לא. אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003בלוקח מגזלן,\u0004 ובניגוד לאמור קודם!","\u0003אמר רב יוסף: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שיש לו\u0004 לגזלן \u0003קרקע,\u0004 שיכול להחזיר ללוקח ממנה לא כסף אלא קרקע אחרת ונמצא שאין כאן צד של ריבית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וכי מותר ללות סאה בסאה במקום שיש לו\u0004 ללוה \u0003קרקע?\u0004 הלא יש בכך צד ריבית שמא התייקרה בינתיים התבואה ונמצא מחזיר יותר משלקח. והרי גם המקרה כאן הוא כעין תשלום ריבית שאתה מתירו מפני שיש לגזלן קרקע!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש להבדיל; \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003הלואה\u0004 ואכן אסור ללוות סאה בסאה, ואילו \u0003הכא זביני\u0004 \u0005[כאן\u0006 מדובר ב\u0005מכר]\u0006 וכיון שיש כאן מתחילה מכר, אין אנו חוששים, שכן גם אם יגרום הדבר לתוספת רווח לקונה הרי אין זו ריבית ממש.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, שכך \u0003אמר רב יוסף: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שקנו מידו,\u0004 שבשעת המכירה עשו הסכם וקנין מיוחד שיהא השבח לקונה בכל מקרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וכי מותר ללות סאה בסאה במקום שקנו מידו,\u0004 והלא יש כאן חשש ריבית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003התם\u0004 \u0005[שם],\u0006 כשאסרו, היה זה ב\u0003הלואה,\u0004 שיש בכך חשש ריבית, \u0003והכא זביני\u0004 \u0005[וכאן\u0006 ב\u0005מכר],\u0006 שהקונה מחבירו בזול וחוזר ומוכר ביוקר אין בכך משום ריבית.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהזכרנו \u0003אמר שמואל: בעל חוב גובה את השבח. אמר רבא: תדע\u0004 שכן הוא — לפי \u0003שכך\u0004 הוא הנוסח ש\u0003כותב לו\u0004 ה\u0003מוכר ללוקח\u0004 בשטר: \u0003\"אנא איקום ואשפי ואדכי ואמריק זביני אילין\u0004 \u0005[אני אעמוד ואשפה ואנקה ואמרק את הממכר הזה],\u0006 כלומר, ידאג לסלק את כל הבעיות העשויות להיות קשורות בנכס הנמכר, \u0003אינון ועמליהון ושבחיהון, ואיקום קדמך\u0004 \u0005[הם ועמלם ושבחם ואעמיד לפניך],\u0006 \u0003וצבי זבינא דנן וקביל עלוהי\u0004 \u0005[ורצה המוכר הזה וקבל על עצמו]\u0006 את ההתחייבות שבשטר","\u0003\".\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חייא בר אבין לרבא: אלא מעתה מתנה\u0004 ש\u0003לא כתיב ליה הכי\u0004 \u0005[כותב בו כך]\u0006 בשטר המתנה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שבעל חוב \u0003לא טריף שבחא\u0004 \u0005[יטרוף\u0006 את \u0005השבח]\u0006 ממקבל המתנה?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","אמר לו: אם כן, האם תאמר כי \u0003יפה כח מתנה ממכר?\u0004 שהרי הלוקח משלם את השבח! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003יפה ויפה.\u0004 שכיון שאין מקבל המתנה מקבל את דמי השבח מן הנותן, אין עליו חובה לתת לבעל החוב את השבח, שסוף סוף לא הפסיד בכך דבר.","\u0003אמר רב נחמן: הא מתניתא מסייע ליה\u0004 \u0005[ברייתא זו מסייעת]\u0006 \u0003ל\u0004שיטת \u0003מר שמואל, והונא חברין\u0004 \u0005[חברינו],\u0006 רב הונא, \u0003מוקים לה במילי אחריני\u0004 \u0005[מעמיד,\u0006 מסביר \u0005אותה בדבר אחר]\u0006 ולדעתו אין מכאן סיוע לדברי שמואל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא]: \u0003המוכר שדה לחבירו, והרי היא,\u0004 השדה \u0003יוצאה\u0004 (יוצאת) \u0003מתחת ידו\u0004 של הקונה, משום שהיה השדה משועבד כבר לבעל חוב, \u0003כשהוא גובה\u0004 מן המוכר — הריהו \u0003גובה את הקרן מנכסים משועבדים, ו\u0004את ה\u0003שבח גובה מנכסים בני חורין.\u0004 ואם כן מוכח שבעל החוב לוקח מקודם את השבח מן הקונה.","\u0003ו\u0004אולם \u0003הונא חברין\u0004 \u0005[חברינו]\u0006 \u0003מוקים לה במילי אחריני\u0004 \u0005[מעמיד,\u0006 מסביר, \u0005אותה בדברים אחרים],\u0006 שברייתא זו עוסקת \u0003בלוקח מגזלן,\u0004 שאז ודאי מגיע השבח לנגזל.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003המוכר שדה לחבירו והשביחה\u0004 הקונה, \u0003ובא בעל החוב וטרפה, כשהוא,\u0004 הקונה, \u0003גובה\u0004 מן המוכר, \u0003אם\u0004 היה \u0003השבח,\u0004 כלומר, עליית הערך של השדה \u0003יותר על היציאה\u0004 (ההוצאות) שהוציא הקונה — הריהו \u0003נוטל את השבח,\u0004 את ערך ההשבחה היתירה \u0003מבעל הקרקע, והיציאה,\u0004 יתר ההוצאות שהוציא בהשבחה זו — \u0003מבעל החוב. ואם היציאה יתירה על השבח\u0004 — \u0003אין לו אלא\u0004 תשלום הוצאה כדי \u0003שיעור\u0004 ה\u0003שבח\u0004 ולא יותר, שהוא מקבל \u0003מבעל חוב.\u0004","ונברר: \u0003והא\u0004 \u0005[ו\u0006ברייתא \u0005זו]\u0006 \u0003שמואל במאי מוקים לה\u0004 \u0005[במה\u0006 הוא \u0005מעמיד,\u0006 מסביר, \u0005אותה]?\u0006 \u0003אי\u0004 מדובר \u0003בלוקח מגזלן\u0004 — אם כן \u0003קשיא רישא\u0004 \u0005[קשה מתחילתה],\u0006 שהרי \u0003אמר שמואל: לוקח\u0004 (קונה) \u0003מגזלן לית ליה שבחא\u0004 \u0005[אין לו שבח]\u0006 וכאן נאמר שנוטל שבח. \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא מסביר זאת \u0003בבעל חוב\u0004 — אם כן \u0003קשיא רישא וסיפא\u0004 \u0005[קשה בראשה ו\u0006גם \u0005בסופה],\u0006 ש\u0003אמר שמואל: בעל חוב גובה את השבח\u0004 ולא עוד!","ומסבירים: יכול שמואל לתרץ בשני אופנים; \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר כאן \u0003בלוקח מגזלן,\u0004 וכאן מדובר \u0003כגון שיש לו\u0004 לגזלן \u0003קרקע\u0004 ויכול לחזור ולגבות אותה ממנו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בשקנו מידו,\u0004 שעשו קנין על כל השאר.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר כאן \u0003בבעל חוב. ולא קשיא\u0004 \u0005[ואין זה קשה];\u0006 \u0003כאן\u0004 מדובר \u0003בשבח\u0004"],["\u0003המגיע לכתפים,\u0004 כלומר, שבח שכבר הגיע לשלב כזה שאפשר עוד מעט למסור אותו לסבלים שיקחוהו, ושבח כזה דינו כפירות, ואינו נמסר לבעל חוב. ו\u0003כאן\u0004 מדובר \u0003בשבח שאינו מגיע לכתפים,\u0004 שאז הריהו כגוף הקרקע וניתן לבעל חוב.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מעשים\u0004 אירעו \u0003בכל יום,\u0004 \u0003וקא מגבי\u0004 \u0005[והיה מגבה]\u0006 \u0003שמואל\u0004 לבעלי החוב \u0003אפילו בשבח המגיע לכתפים!\u0004","ומסבירים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דמסיק ביה\u0004 \u0005[ש\u0006הוא \u0005תובע ממנו],\u0006 שהוא היה חייב לו \u0003כשיעור ארעא ושבחא\u0004 \u0005[הקרקע והשבח],\u0006 ובכגון זה היה מגבה שמואל גם את השבח. \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 — \u0003דלא מסיק ביה\u0004 \u0005[שאינו תובע ממנו],\u0006 שאינו חייב לו \u0003אלא כשיעור ארעא\u0004 \u0005[הקרקע]\u0006 בלבד \u0003דיהיב ליה שבחיה ומסליק ליה\u0004 \u0005[שנותן לו\u0006 את \u0005שבחו ומסלק אותו],\u0006 שאז נותן בעל החוב ללוקח את כל דמי השבח, כדי שלא יהיו לו טענות בעלות על השדה.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אי אית ליה זוזי\u0004 \u0005[אם יש לו זוזים,\u0006 כסף\u0005]\u0006 \u0003ללוקח לא מצי מסליק ליה\u0004 \u0005[אינו יכול לסלק אותו],\u0006 את \u0003בעל\u0004 ה\u0003חוב,\u0004 ובעל החוב יכול לדרוש ולקבל את השדה עצמו, אם כן \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003כי אית ליה זוזי\u0004 \u0005[כאשר יש לו זוזים,\u0006 כסף\u0005]\u0006 \u0003ללוקח מצי מסליק ליה\u0004 \u0005[יכול\u0006 הוא \u0005לסלק אותו],\u0006 את \u0003בעל\u0004 ה\u0003חוב\u0004 שיקבל את הכסף המגיע לו, ואחר כך גובה הלוקח את הסכום הזה מן המוכר, \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 הלוקח לבעל החוב הטורף ממנו: \u0003אילו הוה\u0004 \u0005[היה]\u0006 \u0003לי זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 \u0003הוה מסלקינך מכולה ארעא\u0004 \u0005[הייתי מסלק אותך מכל הקרקע],\u0006 \u0003השתא דלית\u0004 \u0005[עכשיו שאין]\u0006 \u0003לי זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 ואיני יכול לסלקך מן השדה לגמרי, \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי גרבא דארעא בארעא\u0004 \u0005[חלק מן הקרקע בקרקע]\u0006 \u0003שיעור שבחאי\u0004 \u0005[השבח\u0006 שהשבחתי\u0005],\u0006 שהרי אתה חייב לי כסף!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שעשאו\u0004 המוכר (הלווה) לאותו שדה \u0003אפותיקי,\u0004 כלומר, שהשדה הזה היה ממושכן באופן מיוחד להלוואה זו. \u0003דאמר ליה\u0004 \u0005[שאמר לו]:\u0006 \u0003לא יהא לך פרעון\u0004 לחובך \u0003אלא מ\u0004קרקע \u0003זו.\u0004 וכיוון שכך, אין הלוקח יכול לסלק את בעל החוב מן השדה הזה, ולכן אינו יכול לטעון לזכות אף בחלק מן השדה.","\u0003הכיר בה\u0004 הקונה בשדה \u0003שאינה שלו,\u0004 של המוכר, שידע שהשדה גזול בידו \u0003ו\u0004בכל זאת \u0003לקחה,\u0004 \u0003אמר רב: מעות\u0004 שנתן — \u0003יש לו,\u0004 הריהו מקבלם בחזרה, ואולם \u0003שבח\u0004 שהשביח — \u0003אין לו,\u0004 שהרי ידע שקונה שדה שאינו שייך למוכר. \u0003ושמואל אמר: אפילו מעות אין לו,\u0004 שמראש ידע שקונה דבר שאיננו שייך למוכר.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, הם \u0005חולקים]?\u0006 ומשיבים: \u0003רב סבר\u0004 \u0005[סבור]:\u0006 \u0003אדם יודע ש\u0004את ה\u0003קרקע אין לו, וגמר\u0004 איפוא בלבו \u0003ונתן\u0004 את הכסף \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003פקדון.\u0004 ושואלים: אם כך \u0003ונימא ליה\u0004 \u0005[ושיאמר לו\u0006 במפורש\u0005]\u0006 שהוא נותן לו \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003פקדון!\u0004 ומשיבים: \u0003סבר\u0004 הנותן כי \u0003לא מקבל,\u0004 שלא ירצה לקבל פקדון זה, ולכן עשה בצורה כזו שישמור את הכסף בינתיים.","\u0003ושמואל סבר\u0004 \u0005[סבור]:\u0006 \u0003אדם יודע שקרקע אין לו, וגמר\u0004 בלבו \u0003ונתן\u0004 למוכר \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003מתנה.\u0004 ושואלים אף לשמואל: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 שנותן לו את הכסף \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003מתנה!\u0004 ומשיבים: \u0003כסיפא ליה מילתא\u0004 \u0005[מבייש אותו, הדבר]\u0006 לקבל כסף במתנה, ולכן הלה מערים ונותן בצורה זו.","ושואלים: \u0003והא פליגי ביה חדא זימנא\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו\u0006 בעקרון \u0005זה פעם אחת],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: אדם \u0003המקדש את אחותו, רב אמר:\u0004 ה\u0003מעות חוזרין,\u0004 שכסף הקידושין שנתן שייך עדיין לאח, והוא יכול לתבוע אותו. \u0003ושמואל אמר:\u0004 ה\u0003מעות מתנה.\u0004 והסבר המחלוקת, \u0003רב אמר: מעות חוזרין,\u0004 וטעמו: כל \u0003אדם יודע שאין קידושין תופסין באחותו, ו\u0004לפיכך \u0003גמר\u0004 בלבו \u0003ונתן\u0004 לאחותו את הכסף \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003פקדון.\u0004 ושאלנו שם: \u0003ונימא לה\u0004 \u0005[ושיאמר לה]\u0006 במפורש שנותן לה כסף זה \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003פקדון!\u0004 ומשיבים: \u0003סבר\u0004 ש\u0003לא מקבלה מיניה\u0004 \u0005[תקבל ממנו].\u0006","\u0003ושמואל אמר:\u0004 ה\u0003מעות מתנה\u0004 הן, ומדוע? — \u0003אדם יודע שאין קידושין תופסין באחותו, וגמר\u0004 בלבו \u0003ונתן לשום\u0004 \u0005[לשם]\u0006 \u0003מתנה.\u0004 ושואלים: \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 \u0003לה\u0004 במפורש שנותן לה \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003מתנה!\u0004 ומשיבים: \u0003כסיפא לה מילתא\u0004 \u0005[מבייש אותה,\u0006 בעיניה \u0005הדבר]\u0006 לקבל מתנה, ולכן עושה בצורה זו.","ומסבירים: \u0003צריכא\u0004 \u0005[צריך]\u0006 לפרש את מחלוקתם בשני המקרים, מפני שאינם נלמדים זה מזה. \u0003דאי איתמר בהא\u0004 \u0005[שאם\u0006 היה \u0005נאמר בזה]\u0006 הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[בזה אמר]\u0006 \u0003רב\u0004 שהכסף חוזר, משום \u0003דלא עבדי אינשי דיהבי\u0004 \u0005[שאין עשויים אנשים לתת]\u0006 \u0003מתנות לנוכראה\u0004 \u0005[ל\u0006איש \u0005זר],\u0006 וודאי התכוון לשם פקדון. \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003אחותו אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל\u0004 שהתכוון לתת לה מתנה, על כן היה צריך לגלות את דעתו בשני המקרים.","ולהיפך \u0003אי איתמר בהך\u0004 \u0005[אילו\u0006 היה \u0005נאמר בההיא],\u0006 בקדושין בלבד, הייתי אומר כי רק \u0003בהך\u0004 \u0005[בההיא]\u0006 \u0003אמר שמואל\u0004 שהמעות מתנה \u0003אבל בהא\u0004 \u0005[בזה],\u0006 בקונה שהוא אדם זר \u0003אימא\u0004 \u0005[אמור]\u0006 שאולי \u0003מודה\u0004 הוא \u0003לרב\u0004 שהמעות פקדון, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לפרש את המחלוקת בשני המקרים.","ושואלים: \u0003בין לרב\u0004 ש\u0003אמר\u0004 שהמעות \u0003פקדון, בין לשמואל\u0004 ש\u0003אמר\u0004 שהמעות \u0003מתנה, האי\u0004 \u0005[זה]\u0006 שידע שהשדה איננו של המוכר כאשר ירד \u0003לארעא\u0004 \u0005[לשדה]\u0006 לטפל בו \u0003במאי קא נחית\u0004 \u0005[במה ירד],\u0006 כלומר, באיזו זכות עשה זאת, \u0003ו\u0004ה\u0003פירות\u0004 שאכל \u0003היכי אכיל\u0004 \u0005[איך אכל]?\u0006","ומסבירים: \u0003סבר\u0004 הלוקח: \u0003אנא איחות לארעא ואיעביד ואיכול בגויה כי היכי דהוה קא עביד איהו\u0004 \u0005[אני ארד לקרקע ואעבוד\u0006 בה \u0005ואוכל בתוכה\u0006 את פירותיה \u0005כמו שהיה עושה הוא,\u0006 המוכר\u0005]\u0006 ו\u0003לכי אתי מריה דארעא זוזאי נהוו\u0004 \u0005[כאשר יבוא בעל הקרקע, הכספים שלי יהיו]\u0006 אם לדעת \u0003רב\u0004 ש\u0003אמר\u0004 שהמעות \u0003פקדון\u0004 — יהיו המעות \u0003פקדון,\u0004 אם \u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר\u0004 שהמעות \u0003מתנה\u0004 — יהיו המעות \u0003מתנה.\u0004","בסוגיות אלה נתפרשו כמה מחלוקות, ולמעשה \u0003אמר,\u0004 סיכם, \u0003רבא: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003יש לו מעות ויש לו שבח, ואף על פי שלא פירש לו את השבח.\u0004 ואולם אם הקונה \u0003הכיר בה,\u0004 בשדה, \u0003שאינה שלו,\u0004 של המוכר \u0003ולקחה,\u0004 ה\u0003מעות\u0004 שנתן — \u0003יש לו, שבח\u0004 — \u0003אין לו.\u0004","ועוד: העדר \u0003אחריות\u0004 מפורשת בשטר ההלוואה, \u0003טעות סופר הוא,\u0004 וכאילו היתה כתובה שם, אלא אם כן פורש בשטר להיפך, \u0003בין בשטרי הלואה, בין בשטרי מקח וממכר.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003שמואל\u0004 את \u0003רב:\u0004 אם לאחר שמכר את השדה שגזל \u0003חזר ולקחה\u0004 (קנאה) \u0003מבעלים ראשונים, מהו\u0004 הדין בכגון זה? האם יכול עכשיו הגזלן לבוא בכוח השטר שבידו וליטול את השדה ממי שקנה אותה ממנו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: לא, כי \u0003מה מכר לו ראשון לשני\u0004 הגזלן לקונה או בכל ממכר — \u0003כל זכות שתבא לידו,\u0004 וכיון שזכות זו על השדה בתוך זכויותיו היא, הרי היא ממילא חלק מן המכר הראשון.","ושואלים: אם כן שאין הגזלן מקבל דבר, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 קנה את השדה? \u0003מר זוטרא אמר: ניחא ליה\u0004 \u0005[נוח לו]\u0006 ש\u0003לא נקרייה גזלנא\u0004 \u0005[יקראנו\u0006 הלוקח \u0005גזלן].\u0006 \u0003רב אשי אמר: ניחא ליה דליקו בהמנותיה\u0004 \u0005[נוח לו שיעמוד במיהמנותו]\u0006 ולא יצא שם עליו שמוכר דברים שאינם שלו.","ושואלים \u0003מאי בינייהו\u0004 \u0005[מה\u0006 הבדל המעשי \u0005ביניהם]?\u0006 ומסבירים: \u0003איכא בינייהו דמית\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה \u0005באופן\u0006 \u0005שמת]\u0006 ה\u0003לוקח; מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 ש\u0003לא לקרייה גזלנא\u0004 \u0005[יקראנו\u0006 הלוקח \u0005גזלן]\u0006 אחר שנטל ממנו את השדה אחר שלקחה ממנו כדין —"],["\u0003הא מית ליה\u0004 \u0005[הרי מת לו]\u0006 כבר הלוקח, ואין הגזלן חושש עוד מן העלבון, ולא לשם כך חזר וקנה את השדה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהטעם הוא משום ש\u0003ניחא ליה דליקום בהמנותיה\u0004 \u0005[נוח לו שיעמוד בנאמנותו]\u0006 \u0003בהדי בני נמי ניחא ליה דליקום בהמנותיה\u0004 \u0005[עם הבנים גם כן נוח לו שיעמוד בנאמנותו].\u0006","ומקשים: הבדל זה אין לו ממשות, שכן \u0003סוף סוף קרו ליה\u0004 \u0005[יקראו לו]\u0006 גם \u0003בני\u0004 ה\u0003לוקח\u0004 \u0003\"גזלנא\"\u0004 \u0005[\"גזלן\"]\u0006 אם ילקח מהם השדה, ואם כן מות הלוקח אינו עושה הבדל!","\u0003אלא,\u0004 יש לומר בדרך אחרת: \u0003איכא בינייהו דמית\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה באופן \u0005שמת]\u0006 ה\u0003גזלן\u0004 עצמו. \u0003מאן דאמר ניחא ליה לאיניש\u0004 \u0005[מי שאומר\u0006 ש\u0005נוח לו לאדם]\u0006 ש\u0003לא לקריוהו\u0004 \u0005[יקראו אותו]\u0006 \u0003\"גזלן\", הא מית ליה\u0004 \u0005[הרי מת לו\u0006 כבר\u0005]\u0006 ובניו יכולים לקחת את השדה לעצמם. ואולם \u0003למאן דאמר ניחא ליה דליקום בהמנותיה\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005נוח לו\u0006 לאדם \u0005שיעמוד בנאמנותו]\u0006 \u0003הכי נמי\u0004 \u0005[זה גם כן]\u0006 \u0003אף על גב דמית, ניחא ליה דליקום בהמנותיה\u0004 \u0005[אף על פי שמת, נוח לו\u0006 עוד בחייו \u0005שיעמוד בנאמנותו]\u0006 אף לאחר מותו!","ודוחים: \u0003סוף סוף קרו לבניה\u0004 \u0005[יקראו לבניו]:\u0006 \u0003\"בני גזלנא\"\u0004 \u0005[גזלן]\u0006 גם לאחר מותו, ואם חושש לכך — גם אחר מיתה הוא חושש.","\u0003אלא איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 באופן \u0003דיהבה\u0004 \u0005[כשנתנה]\u0006 הגזלן \u0003במתנה\u0004 מתחילה ולא מכרה כלל. \u0003מאן דאמר ניחא ליה דליקום בהמנותיה\u0004 \u0005[מי שאומר\u0006 ש\u0005נוח לו שיעמוד בנאמנותו]\u0006 \u0003מתנה נמי\u0004 \u0005[גם כן]\u0006 \u0003ניחא ליה דליקום בהמנותיה\u0004 \u0005[נוח לו שיעמוד בנאמנותו].\u0006 \u0003מאן דאמר ניחא ליה\u0004 \u0005[מי שאומר\u0006 ש\u0005נוח לו]\u0006 ש\u0003לא נקריוהו \"גזלנא\"\u0004 \u0005[יקראוהו \"גזלן\"]\u0006 — \u0003אמר ליה\u0004 \u0005[\u0006יכול הוא \u0005לומר לו]:\u0006 \u0003מאי גזלינא מינך\u0004 \u0005[מה גזלתי ממך]?\u0006 שאם נתתי לך מתנה ומתברר שאיננה שלי ונלקחה ממך — הרי מכל מקום אתה לא הפסדת דבר.","בהרחבת הבעיה שהעלינו באדם שגזל שדה ומכרו, ואחר כך חזר ולקח את השדה מבעליו החוקיים, אומרים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 כי אם \u0003זבנה\u0004 \u0005[מכרה]\u0006 הגזלן בינתיים לאדם אחר בנוסף לראשון שכבר מכר לו, או \u0003אורתה\u0004 \u0005[הורישה],\u0006 או \u0003יהבה\u0004 \u0005[נתנה],\u0006 את השדה, \u0003במתנה\u0004 לאחר, ברור ש\u0003לאו לאוקמה קמי\u0004 \u0005[להעמידה לפני]\u0006 ה\u0003לוקח\u0004 הראשון \u0003קא בעי\u0004 \u0005[רצה],\u0006 שהרי במכירה השניה הוכיח שאין דעתו להשאיר את השדה בידו, אלא מאחר ויש ללוקח הראשון תביעה — יתבע מן הגזלן, אבל השדה ישאר ביד הלוקח השני או מקבל המתנה.","וכן ברור לנו, שאם גזל את השדה מיד אחד ממורישיו ולאחר מכן מת הנגזל ו\u0003נפלה ליה\u0004 \u0005[לו]\u0006 השדה לגזלן \u0003בירושה,\u0004 כיון ש\u0003ירושה ממילא\u0004 \u0005[מעצמה]\u0006 \u0003היא,\u0004 \u0003ולאו איהו קא טרח אבתרה\u0004 \u0005[ולא הוא,\u0006 הגזלן, \u0005שטורח אחריה],\u0006 שאילו היה טורח ומחזר אחריה יש לומר שרצונו להעמידה ביד הלוקח, וכיון שנפלה לו בירושה בלא שיביע דעתו שרצונו בה טירחה והבעת רצון ממנו, ממילא אם ילקח השדה מן הקונה — אין לו כל טענה, אלא שיכול הוא עדיין לתבוע מן הגזלן.","אם היה בעל השדה חייב ממון לאותו גזלן ואחר שגזל ממנו את השדה \u0003גבי איהו\u0004 \u0005[גבה הוא,\u0006 הגזלן\u0005]\u0006 את השדה הזה \u0003בחובו\u0004 מבעליו, אז \u0003חזינא\u0004 \u0005[רואים אנו],\u0006 \u0003אי אית ליה ארעא אחריתי\u0004 \u0005[אם יש לו,\u0006 לבעל השדה שמכר לגזלן \u0005קרקע אחרת]\u0006 \u0003ואמר\u0004 הגזלן: \u0003האי בעינא\u0004 \u0005[\u0006ב\u0005קרקע\u0006 \u0005זו\u0006 במיוחד \u0005אני רוצה],\u0006 נראה מכאן כי \u0003לאוקמה קמיה\u0004 \u0005[להעמידה לפני]\u0006 ה\u0003לוקח קא בעי\u0004 \u0005[הוא רוצה],\u0006 ולכן הוא מחזר במיוחד אחרי זכות בשדה זה.","\u0003ואי לא\u0004 \u0005[ואם אין]\u0006 לו קרקע אחרת, בודאי \u0003זוזי\u0004 \u0005[זוזים ,\u0006 כסף\u0005]\u0006 \u0003הוא דבעי אפרועי\u0004 \u0005[שרוצה להפרע ממנו]\u0006 ואין לו כל כוונה להסדיר את קניינו של הלוקח.","אם \u0003יהבה נהליה\u0004 \u0005[נתנה לו]\u0006 בעל הקרקע הראשון את הקרקע \u0003במתנה\u0004 לגזלן אחר שגזלה ממנו, \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מתנה\u0004 דינה \u0003כירושה, דהא ממילא\u0004 \u0005[שהרי מעצמה]\u0006 היא באה לו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מתנה\u0004 דינה \u0003כמכר.\u0004 ומדוע — \u0003דאי לאו דטרח וארצי קמיה\u0004 \u0005שאילו לא היה טורח ומתרצה לפניו]\u0006 \u0003לא הוי יהיב ליה\u0004 \u0005[היה נותן לו]\u0006 אותה ב\u0003מתנה, להכי טרח וארצי קמיה כי היכי דליקום בהמנותיה\u0004 \u0005[לכך טרח והתרצה לפניו כדי שיעמוד בנאמנותו],\u0006 שיקבל את השדה, ויכול להשאר נאמן כלפי הלוקח ממנו.","ושואלים: \u0003ועד אימת ניחא ליה דליקום בהמנותיה\u0004 \u0005[מתי נוח לו שיעמוד בנאמנותו]\u0006 שאנו מניחים שלצורך זה עשה את הדבר? \u0003אמר רב הונא:\u0004 \u0003עד שעת העמדה בדין,\u0004 עד שעה שנלקח השדה מן הלוקח, ובא הלוקח ותבעו לגזלן בדין. שלאחר שהעמידו בדין מן הסתם אין הגזלן דואג עוד לשמו הטוב, שהרי הראה הלוקח שאין המוכר־הגזלן נאמן בעיניו.","\u0003חייא בר רב אמר: עד דמטא אדרכתא לידיה\u0004 \u0005[שבא שטר רדיפה\u0006 מבית הדין לידו\u0005],\u0006 שעמד הגזלן בדין והפסיד ולא שילם מיד, והוציא בית הדין שטר המרשה ללוקח ליטול מנכסיו של הגזלן בכל מקום שימצאם. \u0003רב פפא אמר: עד דמתחלן יומי אכרזתא\u0004 \u0005[שמתחילים ימי ההכרזה],\u0006 שבאים ומוכרים את קרקעותיו במכירה פומבית.","כל הסוגיה הזו היתה מבוססת על דברי רב שהגזלן עשוי לנסות לפצות את הלוקח ולהעמיד את הקרקע ברשותו. ואולם על העיקרון המרכזי הזה \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רמי בר חמא: מכדי האי\u0004 \u0005[הרי זה]\u0006 ה\u0003לוקח במאי קני להאי ארעא\u0004 \u0005[במה קנה את הקרקע הזו]\u0006 — \u0003בהאי שטרא\u0004 \u0005[בשטר זה],\u0006 שטר המכירה שנתן לו הגזלן, ואולם \u0003האי שטרא חספא בעלמא\u0004 \u0005[שטר זה חרס בלבד]\u0006 \u0003הוא,\u0004 שאין לו כל ערך ותוקף חוקי, שהרי אין אדם יכול למכור דבר שאינו שלו, ואם כן לא היתה כאן בעצם כל מכירה ואין ללוקח בשדה כל זכויות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: תהא במאמינו,\u0004 כלומר, נסביר את שיטת רב שמדובר כשאמר הקונה למוכר: הרי אני מאמין לך שאתה תסדר את הענין כראוי, \u0003בההוא\u0004 \u0005[באותה]\u0006 \u0003הנאה\u0004 ש\u0003לא קאמר ליה מידי\u0004 \u0005[אמר לו דבר],\u0006 לחקור לזכותו על הקרקע \u0003וקא סמיך עליה\u0004 \u0005[וסמך עליו]\u0006 בגלל זה \u0003טרח ומייתי ליה\u0004 \u0005[והביא לו],\u0006 ו\u0003גמר\u0004 בלבו \u0003ומקני ליה\u0004 \u0005[והקנה לו],\u0006 ומשום כך נעשה הממכר גמור לאחר זמן, כאשר הגזלן אכן מקבל זכות לקרקע זו.","\u0003מתיב\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת\u0004 ממה ששנינו: אם אמר אדם לחבירו: \u0003מה שאירש מאבא\u0004 הרי הוא \u0003מכור לך\",\u0004 או שאמר לו \u0003\"מה שתעלה מצודתי מכור לך\"\u0004 — \u0003לא אמר כלום\u0004 לפי שאין אדם יכול להקנות לחבירו דבר שעדיין לא בא לעולם. ואולם אם אמר \u0003\"מה שאירש מן אבא היום מכור לך\",\u0004 או שאמר \u0003\"מה שתעלה מצודתי היום מכור לך\"\u0004 — \u0003דבריו קיימין.\u0004 ואם כן, מובן מכאן כי אין תוקף מעכשיו לקניין הנעשה לאחר זמן, וכן הוא גם בנכס הגזול שגם אם קנאו, כיון שהיה הדבר לאחר זמן אין בכך כדי לקיים את המכירה!","\u0003אמר רמי בר חמא: הא גברא והא תיובתא\u0004 \u0005[הרי האיש והרי קושייתו]!\u0006 כלומר, הרי זו הוכחה נצחת, וקושיה חמורה לשיטת רב.","\u0003אמר רבא: גברא קא חזינא, ותיובתא לא קא חזינא\u0004 \u0005[\u0006את \u0005האיש אני רואה,\u0006 ואולם את \u0005ה\u0006\u0005קושיה אינני רואה],\u0006 כלומר, אינני סבור שהקושיה חמורה כל כך. ומדוע? — שיש לחלק כך: \u0003הכא סמכא דעתיה, והכא לא סמכא דעתיה\u0004 \u0005[כאן\u0006 במכר \u0005סומכת דעתו\u0006 עליו \u0005וכאן\u0006 בירושה \u0005אין סומכת דעתו\u0006 עליו\u0005],\u0006 ומדוע? — \u0003הכא\u0004 \u0005[כאן]\u0006 באומר מה שתעלה מצודתי היום מכור לך \u0003סמכא דעתיה\u0004 \u0005[כאן סומכת דעתו]\u0006 של הקונה עליו \u0003דאזיל טרח ומייתי ליה כי היכי\u0004 \u0005שיילך ויטרח ויביא לו כדי]\u0006 ש\u0003לא נקרייה \"גזלנא\"\u0004 \u0005[יקרא אותו \"גזלן\"],\u0006 \u0003הכא לא סמכא דעתיה\u0004 \u0005[כאן\u0006 בירושה \u0005אין דעתו סומכת]\u0006 ואין נעשה קנין.","ומספרים: \u0003שלחוה,\u0004 את הקושיה הזו \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רבי אבא בר זבדא\u0004 כדי שיביע דעתו אם קושיה היא. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זו אינה צריכה לפנים,\u0004 כלומר, קושיה זו איננה צריכה תיקון שיביאוה לדיון לפנים בית המדרש, אלא היא הוכחה ניצחת כשלעצמה. בניגוד לכך \u0003אמר רבא\u0004 לשיטתו: זו \u0003צריכה לפנים ולפני לפנים,\u0004 כלומר, הריהי צריכה תיקון הרבה, כי כאמור אין הדברים דומים, שכן \u0003הכא סמכא דעתיה, והכא לא סמכא דעתיה\u0004 \u0005[כאן סומכת דעתו וכאן אין סומכת דעתו].\u0006","ומספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כגון זה שדנו דין כרב \u0003בפומבדיתא ואותביה\u0004 \u0005[והקשו את\u0006 הקושיה \u0005הזו].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב יוסף: זו אינה צריכה לפנים\u0004 שקושיה חזקה היא. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 \u0003צריכה לפנים ולפני לפנים,\u0004 שכן \u0003הכא סמכא דעתיה, הכא לא סמכא דעתיה\u0004 \u0005[כאן סומך\u0006 את \u0005דעתו, כאן אינו סומך\u0006 את \u0005דעתו].\u0006","כיון שהבאנו את הברייתא בענין הקנאת דבר שלא בא לעולם, שואלים: \u0003ומאי שנא רישא ומאי שנא סיפא\u0004 \u0005[במה שונה ההתחלה ובמה שונה הסוף],\u0006 שבדבר שעתיד לבוא היום נקנה לו, ובדברים שעתידים לבוא לאחר זמן בלתי מוגדר איננו נקנה לו, הרי לכאורה אותו קושי עקרוני קיים בשני המקרים בשווה! ומשיבים: \u0003אמר ר' יוחנן: סיפא\u0004 \u0005[הסוף]\u0006 שנאמר בו \u0003\"מה שאירש מאבא היום\"\u0004 כוונתו \u0003משום כבוד אביו,\u0004 שכיוון שהוא סבור שאביו ימות היום הריהו רוצה ללוות כסף כדי להכין את הדברים הצריכים להלווייתו, ובוודאי נעשה הקניין בלב שלם. וכן \u0003\"מה שתעלה מצודתי היום\"\u0004"],["\u0003משום כדי חייו\u0004 ופרנסתו המיידית. שלא יימצא חסר לחם ממש באותו היום.","ובאותו נושא של הקניית זכות שתבוא בעתיד \u0003אמר רב הונא אמר רב: האומר לחברו שדה שאני לוקח,\u0004 כלומר, שאני עומד לקנות, \u0003לכשאקחנה,\u0004 כאשר אקנה את השדה, הרי השדה תהא \u0003קנויה לך\u0004 כבר \u0003מעכשיו\u0004 — הרי זה \u0003קנה\u0004 בכח הבטחה זו.","\u0003אמר רבא: מסתברא מלתא\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003רב\u0004 שיפה כוחה של מתנה כזו כאשר אמר לו \u0003\"שדה\" סתם\u0004 ולא פירש דבריו לגבי שדה מסויים. \u0003אבל\u0004 אם אמר \u0003\"שדה זו\"\u0004 — \u0003לא.\u0004 ומדוע? שכן \u0003מי יימר דמזבין לה ניהליה\u0004 \u0005[מי יאמר שימכור לו אותו],\u0006 וכיוון שאין בטחון שימכור לו בעל השדה, לכן אינו יכול להקנות דבר שלא בא לעולם.","ומעירים בלשון שבועה: \u0003והאלהים!\u0004 \u0003אמר רב אפילו ב\u0004שאמר לו \u0003\"שדה זו\". מכדי\u0004 \u0005[הרי]\u0006 \u0003רב\u0004 \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[\u0006את \u0005הלכתו זו]\u0006 — \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 בכלל: \u0003אדם מקנה דבר שלא בא לעולם.\u0004","\u0003דתניא\u0004 \u0005ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין זה: \u0003האומר לאשה \"התקדשי לי לאחר שאתגייר\", או\u0004 \u0003\"לאחר שתתגיירי\",\u0004 או \u0003\"לאחר שאשתחרר\u0004 מעבדותי \u0003\",\u0004 או \u0003\"לאחר שתשתחררי\u0004 את \u0003\",\u0004 או \u0003\"לאחר שימות בעליך\",\u0004 או \u0003\"לאחר שיחלוץ לך יבמיך\",\u0004 או \u0003\"לאחר שתמות אחותיך\u0004 שהיא נשואה לי, ואז אוכל לשאתך לאשה \u0003\",\u0004 בכל המקרים הללו, כיוון שאין הקידושין יכולים לחול עכשיו — \u0003אינה מקודשת\u0004 גם לאחר שהתקיימו הדברים.","\u0003ר' מאיר אומר: מקודשת,\u0004 שלדעתו אפשר להקנות דבר שעדיין לא בא לעולם, וכאשר יבוא — תתממש ההבטחה ויתקיים הקנין.","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אשה כ\"שדה זו\" דמיא\u0004 \u0005[דומה]\u0006 שהרי מדובר באשה מסויימת, \u0003ו\u0004בכל זאת \u0003אמר ר' מאיר\u0004 שהיא \u0003מקודשת,\u0004 הרי שלדעת ר' מאיר, שרב פסק כמותו, אדם מקנה דבר שלא בא לעולם, ואפילו הוא דבר מסויים.","\u0003אמר שמואל: המוצא שטר הקנאה בשוק\u0004 — \u0003יחזירו לבעלים. דאי\u0004 \u0005[שאם]\u0006 חוששים \u0003משום\u0004 ש\u0003כתב ללות ולא לוה\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שעבד\u0004 הלווה \u0003נפשיה\u0004 \u0005[\u0006את \u0005עצמו]\u0006 בשטר זה שהוא שטר הקנאה משעת כתיבתו. \u0003ואי\u0004 \u0005[ואם]\u0006 חוששים \u0003משום פרעון,\u0004 שמא כבר נפרע שטר זה — \u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לפרעון,\u0004 שכן \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר \u0003דפרעיה\u0004 \u0005[שפרעו]\u0006 ודאי \u0003מקרע הוה קרע ליה\u0004 \u0005[היה קורע אותו]\u0006 הלווה, ואם לא נקרע, מן הסתם לא נפרע.","\u0003אמר רב נחמן: אבא מן ספרי דייני\u0004 \u0005[אבי מסופרי הדיינים]\u0006 של \u0003מר שמואל הוה\u0004 \u0005[היה]\u0006 \u0003והוינא כבר שיתא כבר\u0004 \u0005[והייתי\u0006 אז \u0005כבן שש, כבן]\u0006 \u0003שבע, ודכרנא דהוו מכרזי ואמרי\u0004 \u0005[ואני זוכר שהיו מכריזים ואומרים]\u0006 \u0003הני שטרי אקנייתא\u0004 \u0005[הקנאה]\u0006 \u0003דמשתכחי בשוקא\u0004 \u0005[שנמצאים בשוק]\u0006 \u0003נהדרינהו למרייהו\u0004 \u0005[נחזיר אותם לבעליהם],\u0006 וכדברי שמואל.","\u0003אמר רב עמרם: אף אנן תנינא\u0004 \u0005[אנו גם כן שנינו\u0006 מעין זה\u0005].\u0006 ששנינו: \u0003כל מעשה בית דין\u0004 — \u0003הרי זה יחזיר, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לפרעון. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא:\u0004 משם אין הוכחה, כי \u0003מתניתין בשטרי חלטאתא ואדרכתא, דלאו\u0004 \u0005[שלא]\u0006 \u0003בני פרעון נינהו\u0004 \u0005[הם],\u0006 שטר \"חלטאתא\" הוא שטר שנותנים בית דין לאדם ששדה מסויים שייך לו על פי מכירת בית דין, ו\"אדרכתא\" הוא שטר שנותנים לו לאדם זכות לגבות את חובו מכל נכס של החייב.","\u0003אמר\u0004 לו \u0003רבא: ו\u0004כי \u0003הני לאו\u0004 \u0005[\u0006שטרות \u0005אלה לא]\u0006 \u0003בני פרעון נינהו\u0004 \u0005[הם]?\u0006 \u0003והא אמרי נהרדעי\u0004 \u0005[והרי אומרים חכמי נהרדעא]:\u0006 \u0003שומא\u0004 ששמו את נכסיו של אדם ומכריחים אותו למכור כדי לשלם חובותיו הרי היא \u0003הדר\u0004 \u0005[חוזרת]\u0006 \u0003עד תריסר ירחי שתא\u0004 \u0005[שנים עשר חדשי שנה]\u0006 ויכול החייב לשלם ולא למכור. \u0003ואמר אמימר: אנא\u0004 \u0005[אני]\u0006 \u0003מנהרדעא אנא\u0004 \u0005[אני]\u0006 \u0003ו\u0004בכל זאת \u0003סבירא לי\u0004 \u0005[סבור אני]\u0006 ש\u0003שומא הדר\u0004 \u0005[חוזרת]\u0006 \u0003לעולם,\u0004 ואם כן אף שטרות אלה יתכן שעבר זמנם.","\u0003אלא אמר רבא: התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 — \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא,\u0006 המחזיק והלווה וכיוצא בו, \u0005הוא שהפסיד לעצמו],\u0006 \u0003דבעידנא דפרעיה אבעי ליה למקרעיה לשטריה\u0004 \u0005[שבזמן שפרעו היה צריך לקרוע את שטרו],\u0006 \u0003אי נמי למכתב שטרא אחרינא עילויה\u0004 \u0005[או גם כן\u0006 אם רצה בכך \u0005היה צריך לכתוב שטר אחר עליו]\u0006 שיקנה לו שוב זכות על נכסיו.","והטעם שצריך לכתוב — \u0003דמדינא ארעא\u0004 \u0005[שמן הדין\u0006 את ה\u0005קרקע]\u0006 \u0003לא בעיא למיהדר\u0004 \u0005[היה צריך להחזיר],\u0006 \u0003ו\u0004אולם \u0003משום \"ועשית הישר והטוב בעיני ה'\"\u0004 (דברים ו, יח) \u0003הוא דאמור רבנן תהדר\u0004 \u0005[שאמרו חכמים שתחזור].\u0006 \u0003הלכך\u0004 הרי הוא כמי ש\u0003מרישא\u0004 \u0005[מתחילה]\u0006 \u0003הוא דקא זבין\u0004 \u0005[שקונה דבר],\u0006 \u0003איבעי ליה למכתב\u0004 \u0005[היה צריך לכתוב לו]\u0006 \u0003שטר זביני\u0004 \u0005[מכירה]\u0006 עבור הקרקע שקבל בחזרה.","ושואלים: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שטר חוב מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שכן \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר \u0003דפרעיה\u0004 \u0005[שפרעו],\u0006 \u0003אבעי ליה למקרעיה לשטריה\u0004 \u0005[היה צריך לקרוע את שטרו].\u0006 ודוחים: \u0003אימור אשתמוטי קא משתמיט ליה\u0004 \u0005[אמור ש\u0006המלוה \u0005משטמט\u0006 באותו זמן \u0005ממנו],\u0006 \u0003דאמר ליה\u0004 \u0005[\u0006ו\u0005אומר\u0006 הוא \u0005לו]:\u0006 \u0003למחר יהבנא\u0004 \u0005[אתן]\u0006 \u0003לך\u0004 את השטר \u0003דהשתא ליתיה גבאי\u0004 \u0005[שעכשיו איננו אצלי],\u0006 \u0003אי נמי אפשיטי דספרא זייר ליה\u0004 \u0005[או גם כן בגלל פרוטות,\u0006 של שכר כתיבת השטר הוא \u0005עוצר,\u0006 מעכב \u0005אותו]\u0006 את השטר בידו עד שיקבל מן הלווה את שכר הסופר, ואם כן יתכן שימצא שטר פרוע, ולא באשמתו של הלווה.","\u0003אמר ר' אבהו אמר ר' יוחנן: המוצא שטר חוב בשוק, אף על פי שכתוב בו הנפק\u0004 — \u0003לא יחזירו לבעלים.\u0004","ומסבירים: \u0003לא מיבעיא היכא\u0004 \u0005[נצרכה במקום]\u0006 ש\u0003לא כתוב בו הנפק,\u0004 \u0003דאיכא למימר\u0004 \u0005[שאפשר לומר]\u0006 כי \u0003כתב ללות ולא לוה\u0004 ואינו שייך כלל למלוה. \u0003אלא אפילו כתוב בו הנפק, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 פירושו של הנפק — שהשטר \u0003מקוים\u0004 בבית דין — גם בכגון זה \u0003לא יחזיר.\u0004 ומדוע? — \u0003דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 \u0003לפרעון.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' ירמיה לר' אבהו\u0004 על כך: הרי שנינו ש\u0003כל מעשה בית דין הרי זה יחזיר!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ירמיה ברי\u0004 \u0005[בני]\u0006 \u0003לא כל מעשה בית דין שוים,\u0004 ולא אמרו שיחזיר \u0003אלא כגון שהוחזק\u0004 אותו אדם הלווה בשטר \u0003כפרן\u0004 ואינו נאמן לומר \"פרעתי\", ורק במקרה כזה יחזיר לבעל השטר.","\u0003אמר רבא: ומשום\u0004 ש\u0003הוחזק כפרן חדא\u0004 \u0005[\u0006פעם \u0005אחת]\u0006 \u0003תו\u0004 \u0005[שוב]\u0006 \u0003לא פרע\u0004 \u0005[אינו פורע]\u0006 \u0003כלל\u0004 והוא חשוד לגבי כל חוב אחר?! \u0003אלא אמר רבא: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003בשטר חלטאתא ואדרכתא ו\u0004כדברי \u0003ר' זירא\u0004 ששטרות אלה אין בהם חשש פרעון.","והעיר: \u0003ו\u0004דין זה של \u0003כפרן, הואיל ואתא לידן נימא ביה מלתא\u0004 \u0005[ובא לידינו\u0006 לדון בו, \u0005אומר בו דבר].\u0006 ש\u0003אמר רב יוסף בר מניומי אמר רב נחמן: אמרו לו\u0004 בבית דין לאדם שיצא חייב בדינו, פסק הלכה גמור: \u0003\"צא תן לו\u0004 מה שאתה חייב לו \u0003\"\u0004"],["\u0003ואמר\u0004 לאחר זמן \u0003\"פרעתי\u0004 כפי שציוו עלי בבית הדין \u0003\"\u0004— הרי זה \u0003נאמן\u0004 בטענתו ויישבע ששילם וייפטר. ואם \u0003בא\u0004 ה\u0003מלוה\u0004 לפנינו \u0003לכתוב\u0004 עליו אדרכתא — \u0003אין כותבין ונותנין לו.\u0004","ואולם אם אמרו \u0003\"חייב אתה ליתן לו\"\u0004 ולא סיימו לומר \"צא תן לו\" \u0003ו\u0004אחר כך \u0003אמר \"פרעתי\"\u0004 — \u0003אינו נאמן,\u0004 שמן הסתם לא שילם מיד, וכיון שחשוד לשקר אינו נאמן גם בשבועה, אלא יישבע התובע ויטול. ואם \u0003בא\u0004 ה\u0003מלוה\u0004 \u0003לכתוב\u0004 עליו אדרכתא — \u0003כותבין ונותנין לו.\u0004","\u0003רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן אמר: בין\u0004 אם אמרו לו בית הדין \u0003\"צא תן לו\", בין\u0004 אם אמרו לו בית הדין \u0003\"חייב אתה ליתן לו\" ואמר \"פרעתי\"\u0004 — \u0003נאמן.\u0004 ואם \u0003בא\u0004 ה\u0003מלוה לכתוב\u0004 — \u0003אין כותבין ונותנין לו.\u0004","\u0003אלא אי איכא לפלוגי\u0004 \u0005[אם יש\u0006 מקום \u0005לחלק]\u0006 בין מקרים שונים — \u0003הכי\u0004 \u0005[כך]\u0006 \u0003הוא דאיכא לפלוגי\u0004 \u0005[שיש לחלק]:\u0006 אם \u0003אמרו לו \"צא תן לו\" ואמר\u0004 החייב \u0003\"פרעתי\" והעדים מעידין אותו שלא פרעו וחזר ואמר \"פרעתי\"\u0004 לאחר מכן — הרי \u0003הוחזק כפרן לאותו ממון\u0004 ואינו נאמן עוד להישבע ולהיפטר עד שיפרע לו בעדים.","ואולם אם אמרו לו \u0003\"חייב אתה ליתן לו\" ואמר \"פרעתי\" והעדים מעידין אותו שלא פרע וחזר ואמר \"פרעתי\"\u0004 — \u0003לא הוחזק כפרן לאותו ממון,\u0004 ועדיין נאמן בשבועה.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינו מוחזק כפרן? — שכן \u0003אשתמוטי הוא קא משתמיט מיניה\u0004 \u0005[משתמט הוא ממנו],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ואומר לעצמו: אעשה כן \u0003עד דמעיינו\u0004 \u0005[שיעיינו]\u0006 \u0003בי רבנן\u0004 \u0005[חכמים]\u0006 \u0003בדיני\u0004 שנית ויבררו את הענין.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 אמר לחבירו \u0003\"מנה לי בידך,\u0004 שלווית ממני \u0003\" והלה,\u0004 הנתבע \u0003אומר: \"אין לך בידי כלום\", והעדים מעידים אותו שיש לו,\u0004 כלומר, שאכן לווה ממנו, \u0003וחזר\u0004 הלווה \u0003ואמר \"פרעתי\"\u0004 — \u0003הוחזק כפרן לאותו ממון,\u0004 ואינו יכול להישבע עליו.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003שבתאי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' מרינוס כתב לה לכלתיה\u0004 \u0005[לכלתו]\u0006 \u0003איצטלא דמילתא\u0004 \u0005[גלימה של צמר מובחר]\u0006 \u0003בכתובתה, וקבלה עליה\u0004 \u0005[וקיבל על עצמו]\u0006 להיות ערב לכתובתה עבור בנו. \u0003אירכס\u0004 \u0005[אבדה]\u0006 \u0003כתובתה\u0004 של הכלה והיו חילוקי דעות בין הצדדים לענין מה שהיה כתוב בה. \u0003אמר לה: \"לא היו דברים מעולם\",\u0004 מעולם לא הבטחתי לך גלימה זו. \u0003אתו סהדי ואמרי\u0004 \u0005[באו עדים ואמרו]:\u0006 \u0003אין\u0004 \u0005כן]\u0006 אכן \u0003כתב לה\u0004 כפי שטוענת. \u0003לסוף אמר להו\u0004 \u0005[להם]:\u0006 אכן כתבתי אלא שלאחר מכן \u0003\"פרעתיה\",\u0004 שכבר נתתי לה גלימה זו. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003ר' חייא, אמר ליה\u0004 \u0005[לו,\u0006 לשבתאי\u0005]:\u0006 \u0003הוחזקת כפרן לאותה איצטלא,\u0004 ואין אתה נאמן בענין זה אף בשבועה.","\u0003אמר ר' אבין אמר ר' אלעא אמר ר' יוחנן: היה חייב לחבירו שבועה, ואמר \"נשבעתי\" והעדים מעידין אותו שלא נשבע, וחזר ואמר נשבעתי\u0004 לאחר מכן — \u0003הוחזק כפרן לאותה שבועה\u0004 ואין מאמינים לו שנשבע, אלא יישבע הצד השני ויטול.","מסופר כי \u0003אמרוה\u0004 להלכה זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו, אמר להו\u0004 \u0005[להם]:\u0006 \u0003מסתברא מלתא\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003ר' אבין\u0004 כאשר \u0003נתחייב שבועה בבית דין,\u0004 שלאחר הדיון בבית הדין נתחייב בשבועה, \u0003אבל\u0004 אם \u0003חייב\u0004 את \u0003עצמו\u0004 ב\u0003שבועה,\u0004 שהוא הציע לצד שכנגד להישבע — הריהו \u0003נאמן,\u0004 כלומר, לא הפסיד על ידי כך את חזקתו כנאמן, למרות ההכחשה. ומדוע? — \u0003עביד איניש דמקרי ואמר\u0004 \u0005[עשוי אדם שיזדמן ויאמר],\u0006 שאף שהוא חייב את עצמו בכך, כיון שלא הוכרח לעשות זאת על ידי בית הדין, עשוי הוא להתחרט ולחזור בו ואין זו הוכחה שהוא שקרן מועד. \u0003אהדרוה\u0004 \u0005[החזירוה],\u0006 את ההערה הזו של ר' אבהו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבין. אמר להו\u0004 \u0005[להם]\u0006 למביאי השמועה: \u0003אנא נמי\u0004 \u0005[אני גם כן]\u0006 לחיוב שבועה שנתקבלה לגביו החלטה \u0003בבית דין אמרי\u0004 \u0005[אמרתי],\u0006 שלכך התכוונתי מתחילה ואין בינינו איפוא כל חילוקי דעות.","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כגון זה: \u0003אמר ר' אבין אמר ר' אלעא אמר ר' יוחנן: היה חייב לחבירו שבועה בבית דין ואמר \"נשבעתי\" והעדים מעידים אותו שלא נשבע, וחזר ואמר נשבעתי\u0004 לאחר מכן — \u0003הוחזק כפרן לאותה שבועה,\u0004 הרי שאמר במפורש את ההלכה כפי תיקונו של ר' אבהו.","\u0003אמר ר' אסי אמר ר' יוחנן:\u0004 \u0003המוצא שטר חוב בשוק וכתוב בו הנפק\u0004 (קיום), \u0003וכתוב בו זמנו\u0004 (זמן כתיבתו) של השטר, והוא \u0003בו ביום\u0004 שמצאו — \u0003יחזירו לבעלים.\u0004 ומדוע?","— \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום\u0004 החשש שמא \u0003כתב\u0004 הלווה \u0003ללות ולא לוה\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כתוב\u0004 בו \u0003הנפק\u0004 ורק המלוה הוא שמביא את שטרו לבית דין לקיימו. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 לחשוש \u0003משום פרעון\u0004 — \u0003לפריעה בת יומא\u0004 \u0005[\u0006אותו \u0005יום]\u0006 עצמו \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שמן הסתם אין אדם לווה כדי לפרוע באותו יום עצמו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003הא את\u0004 \u0005[הרי אתה]\u0006 \u0003הוא\u0004 ש\u0003אמרת משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: שטר שלוה בו\u0004 אדם \u0003ופרעו\u0004 — \u0003אינו חוזר ולוה בו\u0004 באותו שטר, כיון \u0003שכבר נמחל שיעבודו\u0004 של השטר הזה ובטל תוקפו. שהרי שטר אינו אלא רישום של קבלת התחייבות, וכיוון שנפרע השטר, בטלה התחייבות. ואף אם מציג אותו שטר לאחר זמן — הרי לשטר זה אין עוד תוקף, לפי שלא היתה התחייבות חדשה לקיים אותו.","ונברר: \u0003אימת\u0004 \u0005[אימתי]\u0006 היה השטר כתוב? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שאף שנכתב התאריך שבשטר להיום ואילו ההלוואה היתה בעצם רק \u0003למחר וליומא חרא\u0004 \u0005[\u0006או \u0005ליום אחר],\u0006 \u0003מאי אריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003שכבר נמחל שעבודו? תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד \u0005לו]\u0006 שהוא פסול משום \u0003דהוה ליה\u0004 \u0005[ש\u0006שטר \u0005זה]\u0006 הוא שטר \u0003מוקדם, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003שטרי חוב המוקדמין,\u0004 שהקדים בהם תאריך ההלוואה לעצם ההלוואה — הרי הם \u0003פסולין.\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שנכתב השטר \u0003ביומיה\u0004 \u0005[ב\u0006אותו \u0005יום\u0006 עצמו\u0005]\u0006 וכבר נפרע בו ביום, ורוצה ללוות בו שנית. \u0003אלמא, פרעי אינשי ביומיה\u0004 \u0005[מכאן\u0006 ש\u0005פורעים אנשים ביומם]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי: \u0003מי קא אמינא\u0004 \u0003דלא פרעי\u0004 \u0005[האם אומר אני שאין\u0006 אנשים \u0005פורעים]\u0006 \u0003כלל,\u0004 דבר זה יכול להיות, ואולם \u0003דלא שכיחי אינשי דפרעי ביומיה קא אמינא\u0004 \u0005[שאין זה מצוי שאנשים יפרעו ביומם אמרתי]\u0006 ואם מצא אדם שטר כזה, אין לתלות ולחשוש מדבר שאיננו מצוי, אף על פי שהוא עשוי לקרות.","\u0003רב כהנא אמר:\u0004 כאן שאמר ר' יוחנן שיחזיר שטר לבעלים מדובר \u0003כש\u0004ה\u0003חייב מודה.\u0004 ושואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 יש \u0005לומר]?\u0006 שאם החייב מודה מדוע לא יחזירו למלוה?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 \u0003האי מפרע פרעיה\u0004 \u0005[אותו\u0006 לווה כבר \u0005פרעו]\u0006 \u0003והאי דקא\u0004 \u0005[וזה שהוא]\u0006 \u0003אמר לא פרעתיה,\u0004 הרי זה \u0003משום דקבעי מהדר למזפא ביה זמנא אחריתי, ולפשיטי דספרא חייש\u0004 \u0005[שרוצה לחזור ללוות בו פעם אחרת וחושב עבור\u0006 אותן \u0005פרוטות\u0006 המגיעות \u0005לסופר]\u0006 בשכר עבודתו, שאיננו רוצה לשלם עבור שטר חדש, ומשום כך רוצה שיוחזר השטר כדי שיוכל להשתמש בו, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003אם כן\u0004 ה\u0003מלוה גופיה לא שבק\u0004 \u0005[עצמו איננו מניח]\u0006 שיעשו כן. שכן \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003שמעי\u0004 \u0005[שמעו]\u0006 \u0003בי רבנן\u0004 \u0005[חכמים]\u0006 שהשתמשתי בשטר ישן \u0003ומפסדי\u0004 \u0005[ויפסידו]\u0006 \u0003לי\u0004 את כל השעבודים הכתובים בו.","ושואלים: \u0003מאי שנא מהא דתנן\u0004 \u0005[במה שונה\u0006 הדבר \u0005מזה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא שטרי חוב, אם יש בהם אחריות נכסים\u0004 — \u0003לא יחזיר,\u0004","\u0003ואוקימנא\u0004 \u0005[והעמדנו]\u0006 זאת, הסברנו \u0003כשחייב מודה.\u0004 ואמרנו: \u0003ומשום שמא כתב ללות ב\u0004חודש \u0003ניסן,\u0004 \u0003ו\u0004אולם \u0003לא לוה\u0004 בפועל עד חודש \u0003תשרי, ואתי למטרף\u0004 \u0005[ויבוא לטרוף]\u0006 \u0003לקוחות\u0004 שקנו \u0003מניסן ועד תשרי שלא כדין,\u0004 שהרי ההלוואה עצמה ושעבוד הנכסים הכרוך בה לא היתה אלא מאוחר יותר.","\u0003ולא אמרינן\u0004 \u0005[אמרנו]\u0006 ש\u0003אם כן\u0004 ה\u0003מלוה גופיה\u0004 \u0005[עצמו]\u0006 \u0003לא שביק\u0004 \u0005[מניח]\u0006 שיהא שטר כזה בידו. \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 ללווה: \u0003כתוב שטרא אחרינא\u0004 \u0005[שטר אחר]\u0006 \u0003ב\u0004תאריך של \u0003תשרי,\u0004 בזמן הנכון \u0003דדלמא שמעי רבנן ומפסדי ליה\u0004 \u0005[שמא ישמעו חכמים ויפסידו לי],\u0006 ואם כן, הרי שאין מתחשבים בנימוק זה!","ומשיבים: \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום דאית ליה רווחא\u0004 \u0005[שיש לו רווח\u0006 למלוה\u0005]\u0006 \u0003דקא טריף\u0004 \u0005[שהוא טורף]\u0006 \u0003לקוחות מניסן ועד תשרי\u0004, ומשום כך \u0003מינח ניחא ליה ולא\u0004 \u0003אמר ולא מידי\u0004 \u0005[נוח לו\u0006 הדבר \u0005ואינו אומר דבר]\u0006 אף שיש חשש שמא יתפס. \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003כיון דלית ליה רווחא\u0004 \u0005[שאין לו רווח],\u0006 ש\u0003סוף סוף שטרא האידנא כתיב\u0004 \u0005[עכשיו\u0006 הוא \u0005כתוב],\u0006 באותו יום עצמו, \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 לו להרוויח בכך? וכיוון שחושש \u0003דקטריף\u0004 \u0005[ש\u0006יימצא \u0005טורף]\u0006 \u0003לקוחות\u0004 — \u0003בשטר שנמחל שיעבודו, לא שביק\u0004 \u0005[אינו מניח]\u0006 ללווה ללוות בשטר כזה, שכיון שאינו מרויח דבר, נותר בידו איפוא רק החשש שיפסלו חכמים את השטר.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען אחר מעשה בית דין,\u0004 כלומר, התחייבות המוטלת על אדם מכח תקנה קבועה (כגון לשלם כתובה לאשתו שגירש, או מזון האשה והבנות) והוא טוען שכבר פרע את החוב, אלא שאין לו עדים בדבר —"],["\u0003לא אמר כלום,\u0004 ואין משגיחים בטענתו. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר\u0005]?\u0006 — \u0003כל מעשה בית דין,\u0004 כלומר, כל דבר שהוא תקנה קבועה של בית דין, הרי זה \u0003כמאן דנקיט שטרא בידיה דמי\u0004 \u0005[כמי שהחזיק\u0006 התובע \u0005שטר בידו הוא נחשב],\u0006 ואין אדם יכול להיפטר מהתחייבות כזו בטענה בלבד, שאין לה סמך, ולומר \"כבר פרעתי\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן: ו\u0004כי \u0003לא משנתינו היא זו?\u0004 הלא דבר זה אפשר ללמדו מן המשנה ששנינו בה: אם \u0003הוציאה\u0004 אשה \u0003גט ואין עמו כתובה\u0004 משום שהכתובה אבדה — הריהי \u0003גובה כתובתה.\u0004 ובודאי הטעם הוא משום שהחובה לשלם את הכתובה היא תנאי בית דין, ואין הבעל יכול להכחישה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: אכן, ראיה יפה היא זו ואולם \u0003אי לאו דדלאי\u0004 \u0005[אם לא שהייתי מרים]\u0006 \u0003לך חספא\u0004 \u0005[חרס]\u0006 \u0003לא משכחת מרגניתא תותה\u0004 \u0005[הייתי מוצא מרגלית תחתיו],\u0006 כלומר, רק לאחר שאמרתי לך את ההלכה הזו הצלחת אתה למצוא את הדבר מרומז במשנה, ולולא זה לא היית מעלה זאת על דעתך.","כאשר סופר מעשה זה בבבל, \u0003אמר אביי: מאי מרגניתא\u0004 \u0005[מה המרגלית]?\u0006 כלומר, האם באמת יש הוכחה לדבר מן המשנה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003במקום שאין כותבין כתובה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 במשנה זו, וברור כי במקום זה ה\u0003גט\u0004 עצמו \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003כתובתה,\u0004 שהרי אין לה כתובה מיוחדת, \u0003אבל במקום שכותבין כתובה, אי נקיטא\u0004 \u0005[אם מחזיקה]\u0006 היא \u0003כתובה\u0004 — \u0003גביא\u0004 \u0005[\u0006הריהי \u0005גובה]\u0006 בה, \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003לא\u0004 — \u0003לא גביא\u0004 \u0005[אינה גובה],\u0006 ואין להוכיח איפוא מן המשנה.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר אביי\u0004 עצמו: \u0003לאו מלתא\u0004 \u0005[לא דבר,\u0006 הלכה\u0005]\u0006 של ממש \u0003היא דאמרי\u0004 \u0005[שאמרתי],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר כי \u0003במקום שאין כותבים כתובה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003אבל במקום שכותבין כתובה, אי נקיטא\u0004 \u0005[אם מחזיקה]\u0006 היא \u0003כתובה\u0004 — \u0003גביא\u0004 \u0005[\u0006הריהי \u0005גובה]\u0006 בה, \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003לא\u0004 — \u0003לא גביא\u0004 \u0005[אינה גובה],\u0006 אם כן \u0003אלמנה מן האירוסין\u0004 שאף במקום שנוהגים לכתוב כתובה אין כותבין אלא מן הנישואין, \u0003במאי גביא\u0004 \u0005[במה\u0006 היא \u0005גובה]\u0006 את כתובתה?","אם תאמר ש\u0003בעדי מיתת\u0004 ה\u0003בעל,\u0004 שמביאה עדים שבעלה מת ותובעת את כתובה מיורשיו — \u0003לטעון ולימא\u0004 \u0005[שיטען\u0006 היורש \u0005ויאמר]:\u0006 כבר \u0003פרעתיה,\u0004 שהרי אין לה הוכחה שלא קיבלה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 שכך יכול היורש לטעון, \u0003אם כן מה הועילו חכמים בתקנתן\u0004 לעשות כתובה לאלמנה מן האירוסין כשאפשר לדחותה תמיד?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי,\u0004 ושאל בדבר הנחת יסוד אחת בדברי אביי: \u0003ואלמנה מן האירוסין דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 \u0003כתובה מנא לן\u0004 \u0005[מניין לנו],\u0006 שמא אין לה כתובה?","\u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נתארמלה\u0004 (נתאלמנה) \u0003או נתגרשה, בין מן האירוסין בין מן הנישואין\u0004 — הריהי \u0003גובה את הכל,\u0004 כל מה שכתוב בכתובה, בין עיקר הכתובה הקבוע ובין התוספות שהוסיף הבעל מרצונו. ואולם משם אין להוכיח שיש דין כולל כזה, \u0003דלמא היכא\u0004 \u0005[שמא\u0006 מדובר שם \u0005במקום]\u0006 באופן ש\u0003כתב לה\u0004 במיוחד כתובה, אבל אם לא כתב לה איננה מקבלת כלום.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מאי למימרא\u0004 \u0005[מה יש לומר]\u0006 ומה חידש בכך, שאם כתב לה שטר כתובה שהיא יכולה לגבות אותו, אפשר לומר כי בא הדבר \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' אלעזר בן עזריה,\u0004 ש\u0003אמר:\u0004 שאלמנה מן האירוסין אינה גובה את מלוא הסכום הכתוב בכתובתה \u0003ש\u0004כן \u0003לא כתב לה\u0004 הבעל כתובה זו \u0003אלא על מנת לכונסה\u0004 שתהיה אשתו ממש, וכיון שלא התקיימו הנישואין בטלה גם הכתובה. ומשום כך \u0003אצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר שגובה הכל.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון המשנה הזו שכך הכוונה בה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003גובה את הכל. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003כתב לה\u0004 כתובה, \u0003היינו דקא תני\u0004 \u0005[זהו ששנינו]\u0006 \u0003גובה את הכל,\u0004 שמחדש שלא רק גובה את המגיע לה כאלמנה מתנאי בית דין, אלא גם את שאר הדברים שכתב והוסיף לה בכתובתה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר בש \u0003לא כתב לה\u0004 כתובה כלל, אם כן"],["\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"גובה את הכל\"?\u0004 הלא בסך הכל או \u0003מנה\u0004 או \u0003מאתים הוא דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 ולא יותר. ואם כן אין להוכיח מכאן לענין כתובת אלמנה.","\u0003ואלא\u0004 תוכיח שאלמנה מן האירוסין יש לה כתובה \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003רב חייא בר אמי: אשתו ארוסה\u0004 שמתה, \u0003לא אונן\u0004 \u0005[מתאבל\u0006 עליה\u0005]\u0006 \u0003ולא מטמא לה\u0004 אם היה כהן, לפי שאיננה נחשבת עדיין כאשתו גמורה, \u0003וכן היא לא אוננת\u0004 עליו \u0003ולא מטמאה לו\u0004 אף אם אינה כהנת, אם אינה רוצה בכך. \u0003מתה\u0004 היא — \u0003אינו יורשה,\u0004 \u0003מת הוא\u0004 — הרי היא \u0003גובה כתובתה.\u0004","אולם גם מכאן אין להוכיח הוכחה כולל, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן בופן ש\u0003כתב לה\u0004 במפורש כתובה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 אם \u0003כתב לה מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר\u0006 בכך\u0005]\u0006 — אכן, לא בכך החידוש אלא במה שנאמר כי \u0003מתה אינו יורשה איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005].\u0006","\u0003אלא\u0004 לא מכאן, כי אם \u0003אביי מגופה דמתניתין קא הדר ביה\u0004 \u0005[של משנתנו חזר בו],\u0006 ומשום \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 כי \u0003במקום שאין כותבין כתובה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 שה\u0003גט היינו\u0004 \u0005[זהו]\u0006 \u0003כתובתה,\u0004 אולם \u0003אטו\u0004 \u0005[וכי]\u0006 ב\u0003גט מנה\u0004 או \u0003מאתים כתיב ביה\u0004 \u0005[כתוב בו]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003כיון דתקינו רבנן למגבא לה כמאן דכתיב ביה דמי\u0004 \u0005[שתיקנו חכמים לגבות בו כמי שכתוב בו נחשב],\u0006 \u0003לטעון ולימא\u0004 \u0005[שיטען ויאמר]\u0006 \u0003פרעתי\u0004 כבר.","\u0003וכי תימא דאמרינן ליה\u0004 \u0005[ואם תאמר שאומרים אנו לו]:\u0006 \u0003אי פרעתה איבעי לך למיקרעיה\u0004 \u0005[אם\u0006 באמת \u0005היית פורע\u0006 לה \u0005היית צריך לקרוע אותו,\u0006 את הגט\u0005],\u0006 \u0003אמר לן\u0004 \u0005[\u0006יכול הוא \u0005לומר לנו]:\u0006 \u0003לא שבקתן\u0004 \u0005[הניחה לי\u0006 האשה\u0005],\u0006 שהיא \u0003אמרה: בעינא לאנסובי ביה\u0004 \u0005[רוצה אני להינשא בו],\u0006 שאם תקרע את הגט לא אוכל להינשא, שלא תהיה בידי הוכחה שאני גרושה.","\u0003וכי תימא אמרינן ליה\u0004 \u0005[ואם תאמר\u0006 ש\u0005אומרים אנו לו]:\u0006 \u0003איבעי לך למיקרעיה ומכתב אגביה\u0004 \u0005[היית צריך לקרוע אותו ולכתוב על גבו]\u0006 כמו שכותבים בבית דין בנוסח זה: \u0003גיטא דנן\u0004 \u0005[גט זה]\u0006 ש\u0003קרענוהו לא משום דגיטא פסולה\u0004 \u0005[שגט פסול]\u0006 \u0003הוא, אלא כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תגבי ביה זמנא אחריתי\u0004 \u0005[תגבה בו פעם אחרת].\u0006 ואולם אדם פרטי אינו יכול לכתוב כך, אלא בית דין בלבד, ו\u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל\u0004 מי \u0003דמגבי\u0004 \u0005[שמגבה],\u0006 משלם דמי כתובה \u0003בבי דינא מגבי\u0004 \u0005[בבית דין\u0006 הוא ש\u0005משלם]?\u0006 ואם כן יכול היה לטעון שכבר שילם הכל. ואם נאמר במשנה שהיא מקבלת כתובתה, משמע שאין יכול לטעון פרעתי, משום שתקנת בית דין הרי היא כשטר חוב כתוב.","\u0003מצא\u0004 אדם \u0003גיטי נשים ושחרורי עבדים, דייתיקי\u0004 (שטרי צוואה), שטרי \u0003מתנה, ושוברין\u0004 (קבלות על סכומים שניתנו) — \u0003הרי זה לא יחזיר. שאני אומר\u0004 על כולם: אמנם \u0003כתובין היו, ונמלך עליהן\u0004 בעליהן \u0003שלא לתנן.\u0004 וכל עוד לא הוכח שניתנו אין להחזירם למי שנתנו לו.","מעירים: \u0003טעמא\u0004 \u0005[הטעם],\u0006 דווקא שאינו מחזיר משום החשש של \u0003נמלך שלא לתנן, הא אמר\u0004 \u0005[הרי\u0006 אילו היה \u0005אומר]\u0006 החתום על השטרות האלה למוצאים \u0003\"תנו\"\u0004 — \u0003נותנין, ואפילו\u0004 אם היה הדבר \u0003לזמן מרובה\u0004 לאחר שאבדו השטרות.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במקום אחר, ששנינו: שליח \u0003המביא גט\u0004 לאשה, \u0003ואבד הימנו\u0004 הגט, אם \u0003מצאו לאלתר\u0004 \u0005[מיד]\u0006 לאחר שאבד — \u0003כשר,\u0004 ו\u0003אם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול.\u0004 משמע שגט שנמצא לאחר זמן רב אין המוצא מחזיר אותו, ומדוע כאן אומרים אנו שיחזיר ואין מחלקים בין מיד לזמן מרובה?","\u0003אמר רבה: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 בגט שאמרנו שלא יחזיר אלא אם מצא כן מיד — הרי זה \u0003במקום שהשיירות מצויות\u0004 ועוברים שם רבים, ויש לחשוש שמא איבד אדם אחר בעל שם דומה את הגט שלו. ואילו \u0003כאן\u0004 ששנינו \u0003שאינו מחזיר, הרי זה מדובר\u0004 \u0003במקום שאין השיירות מצויות,\u0004 שבכגון זה אין לחשוש שמא נמצא מחזיר שטרו של אדם אחר.","ומעירים: \u0003ואפילו במקום שהשיירות מצויות\u0004 — \u0003והוא שהוחזקו שני יוסף בן שמעון בעיר אחת\u0004 כאשר ידוע לנו שאכן נמצאים שני אנשים ששמם שווה, כגון יוסף בן שמעון, הגרים בעיר אחת, ויש לחשוש שהגט שמצא היה גיטו של האחר.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שלא תמיד חוששים לאדם בעל שם דומה, אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבה\u0004 על דברי \u0003רבה\u0004 עצמם. שמסופר: \u0003ההוא גיטא דאשתכח בי דינא\u0004 \u0005[גט אחד שנמצא בבית דינו]\u0006 של \u0003רב הונא, דהוה\u0004 \u0005[שהיה]\u0006 \u0003כתוב ביה\u0004 \u0005[בו]\u0006 שהגט נכתב \u0003בשוירי מתא דעל רכיס נהרא\u0004 \u0005[בעיר שוירי\u0006 הנמצאת \u0005על הנהר רכיס].\u0006 \u0003אמר רב הונא:\u0004"],["\u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לשני שוירי,\u0004 כלומר, שמא יש עוד מקום שנקרא שוירי ושם נמצא אדם ששמו כשם בעל גט זה, ולו שייך הגט, ולכן אין להחזיר את הגט. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה: פוק\u0004 \u0005[צא]\u0006 ו\u0003עיין בה,\u0004 בבעיה זו, \u0003דלאורתא בעי מינך\u0004 \u0005[שבערב ישאל אותך]\u0006 \u0003רב הונא\u0004 כעין בחינה, שתאמר לו מהיכן נובעת סברה זו שלו. \u0003נפק\u0004 \u0005[יצא]\u0006 מבית המדרש וחזר על לימודו, \u0003ואשכח\u0004 \u0005[ומצא]\u0006 מקור לדברים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003כל\u0004 שטר שההתחייבות שבו נובעת מ\u0003מעשה בית דין\u0004 — \u0003הרי זה יחזיר\u0004 לזה שההתחייבות כלפיו.","ולענייננו \u0003והא בי דינא\u0004 \u0005[והרי בית דינו]\u0006 של \u0003רב הונא, דכי\u0004 \u0005[שכמו]\u0006 \u0003מקום שהשיירות מצויות דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שהרי באים לבית דין זה אנשים רבים ממקומות שונים, \u0003וקא פשיט\u0004 \u0005[ופתר]\u0006 \u0003רבה\u0004 שהמוצא שטר באותו מקום \u0003יחזיר\u0004 אותו, \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003הוחזקו\u0004 ויודעים אנו שיש \u0003שני יוסף בן שמעון\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חוששים ואין מחזירים. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא.\u0004","מסופר: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רבה עובדא בההוא גיטא דאשתכח בי כיתנא\u0004 \u0005[מעשה בגט אחד שנמצא בבית הפשתן]\u0006 של \u0003פומבדיתא כשמעתיה\u0004 \u0005[כהלכתו]\u0006 והחזירו.","לגוף הענין מה בדיוק עשה: \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהיה זה מקום \u0003היכא דמזבני כיתנא\u0004 \u0005[היכן שמוכרים פשתן]\u0006 \u0003והוא שלא הוחזקו\u0004 שני יוסף בן שמעון במקום זה, \u0003אף על גב דשכיחין שיירתא\u0004 \u0005[אף על פי שמצויות\u0006 שם \u0005שיירות],\u0006 שהרי הוא מקום מקח וממכר.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003היכא דתרו כיתנא\u0004 \u0005[היכן ששורים פשתן]\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003הוחזקו,\u0004 ומה טעמו? \u0003דלא שכיחא\u0004 \u0005[שאין מצויות]\u0006 \u0003שיירות\u0004 במקום זה.","כעין זה \u0003ר' זירא רמי מתניתין אברייתא, ומשני\u0004 \u0005[היה משליך\u0006 מראה סתירה, בין \u0005משנה לברייתא, ומתרץ];\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003המביא גט ואבד הימנו,\u0004 אם \u0003מצאו לאלתר\u0004 \u0005[מיד]\u0006 — \u0003כשר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מברייתא ששנינו בה: \u0003מצא גט אשה בשוק, בזמן שהבעל מודה\u0004 שכתבו — \u0003יחזיר לאשה. אין הבעל מודה\u0004 — \u0003לא יחזיר לא לזה ולא לזה.\u0004","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003בזמן שהבעל מודה\u0004 — \u0003יחזיר לאשה, ואפילו\u0004 אם נמצא \u0003לזמן מרובה!\u0004","\u0003ומשני\u0004 \u0005[והיה מתרץ]:\u0006 \u0003כאן במקום שהשיירות מצויות\u0004 — לא יחזיר, \u0003וכאן במקום שאין השיירות מצויות\u0004 — יחזיר.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003והוא\u0004 כאשר \u0003הוחזקו\u0004 שני אנשים באותו שם שאז \u0003לא נהדר\u0004 \u0005[יחזיר]\u0006 \u0003והיינו\u0004 \u0005[וזהו\u0006 כהלכתו\u0005]\u0006 של \u0003רבה. איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שפסק \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הוחזקו\u0004 שני אנשים בשם זה \u0003לא נהדר\u0004 \u0005[יחזיר],\u0006 \u0003ופליגא\u0004 \u0005[וחלוקה\u0006 שיטתו\u0005]\u0006 על זו של \u0003רבה.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רבה לא אמר כר' זירא,\u0004 משום ש\u0003מתניתין אלימא ליה לאקשויי\u0004 \u0005[\u0006מ\u0005משנתנו נוח לו להקשות]\u0006 להוכיח את הדבר מתוך המשנה, ולא מברייתא שאינה מדוייקת כל כך. \u0003אלא ר' זירא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבה,\u0004 והגיע למסקנה זו מתוך ברייתא ולא ממשנה?","ומשיבים: ר' זירא \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003מי קא תני\u0004 \u0005[האם שנינו\u0006 במשנה במפורש\u0005]:\u0006 \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003אמר \"תנו\"\u0004 — \u0003נותנין ואפילו לזמן מרובה? דלמא הא\u0004 \u0005[שמא\u0006 יש לפרש: \u0005הרי\u0006 אם\u0005]\u0006 \u0003אמר \"תנו\"\u0004 — \u0003נותנין, ולעולם כדקיימא לן\u0004 \u0005[כמו שמוחזק בידינו]\u0006 שנותנים \u0003לאלתר\u0004 לאחר שאבד השטר ולא לאחר זמן, ואם כן אין להוכיח משם.","ושואלים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003ל\u0004דעת \u0003ר' זירא במקום שהשיירות מצויות, ואף על גב\u0004 \u0005[ואף על פי]\u0006 \u0003שלא הוחזקו שני יוסף בן שמעון, ופליגא\u0004 \u0005[ו\u0006הוא \u0005חולק]\u0006 על דברי \u0003רבה,\u0004 \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005חלוקים הם]?\u0006","ומסבירים: \u0003רבה סבר\u0004 \u0005[סבור]:\u0006 \u0003דקתני\u0004 \u0005[\u0006מה \u0005ששנה]\u0006 \u0003כל מעשה בית דין הרי זה יחזיר\u0004 וכוונתו \u0003דאשתכח\u0004 \u0005[שנמצא\u0006 השטר\u0005]\u0006 \u0003בבית דין עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ובית דין\u0004 הלא \u0003כמקום שהשיירות מצויות, והוא שהוחזקו\u0004 — \u0003לא יחזיר,\u0004 ואם \u0003לא הוחזקו\u0004 — \u0003יחזיר. ו\u0004אילו","\u0003ר' זירא אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003\"כל מעשה בית דין שנמצאו בבית דין\"?\u0004 לא כן, אלא \u0003\"כל מעשה בית דין יחזיר\" קתני\u0004 \u0005[שנה],\u0006 \u0003ולעולם דאשתכח אבראי\u0004 \u0005[שנמצא בחוץ]\u0006 במקום שאין השיירות מצויות, אבל בתוך בית דין שהוא מקום שמצויים בו רבים, לא יחזיר אלא אם כן ידוע לנו שאין כפילות בשמות.","\u0003ר' ירמיה אמר:\u0004 מתי יחזיר — \u0003כגון דקא אמרי\u0004 \u0005[שאומרים]\u0006 אותם ה\u0003עדים:\u0004 \u0003מעולם לא חתמנו אלא על גט אחד של יוסף בן שמעון,\u0004 ולכן אין מקום לחשוש, ואומרים:","\u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך מה יש לומר],\u0006 הלא ברור שאין כאן חשש! ומשיבים: \u0003מהו דתימא, ליחוש דלמא אתרמי שמא כשמא\u0004 \u0005[מהו שתאמר, נחשוש שמא הזדמן שם\u0006 המגרש והמגורשת \u0005כשם\u0006 המגרש והמגורשת בגט האחר\u0005],\u0006 \u0003ו\u0004שמות ה\u0003עדים\u0004 ששם הם בדיוק \u0003כ\u0004שמות ה\u0003עדים\u0004 כאן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לחשש רחוק כזה.","\u0003רב אשי אמר:\u0004 מתי מחזירים — \u0003כגון דקא אמר\u0004 \u0005[שאמר]\u0006 המאבד סימן מובהק, וכגון \u0003נקב יש בו בצד אות פלונית.\u0004","ומעירים: \u0003ודוקא\u0004 שאמר נקב \u0003בצד אות פלונית\u0004 שהוא סימן מובהק, \u0003אבל\u0004 אם אמר שיש בו \u0003נקב בעלמא\u0004 \u0005[סתם]\u0006 — \u0003לא\u0004 יחזיר על ידי סימן כזה.","ומסבירים: \u0003רב אשי מספקא ליה\u0004 \u0005[מסופק היה לו]\u0006 בשאלה של \u0003סימנים, אי דאורייתא\u0004 \u0005[האם\u0006 תוקפם \u0005מן התורה]\u0006 וכל המוסר סימנים הרי על פי דברי תורה עצמם יש לסמוך ולהאמין שהחפץ שלו, \u0003אי דרבנן\u0004 \u0005[או\u0006 רק כתקנת \u0005חכמים]\u0006 בלבד היא לסמוך על סימני אבידה. ולכן, במקום שיש חשש באיסור והיתר (ולא לענין ממון) כגון בגט, אין אנו סומכים אלא על סימנים מובהקים שיש בהם הוכחה גמורה.","מסופר: \u0003רבה בר בר חנה\u0004"],["\u0003אירכס ליה גיטא בי מדרשא\u0004 \u0005[אבד לו גט\u0006 שהוא היה שליח להביאו \u0005בבית המדרש]\u0006 ומצאוהו. \u0003אמר\u0004 למוצאים: \u0003אי סימנא\u0004 \u0005[אם סימן]\u0006 חשוב בעיניכם — \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי\u0004 סימן \u0003בגויה\u0004 \u0005[בו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 חשוב לכם שאכירנו \u0003ב\u0004\u0003טביעות עינא\u0004 \u0005[עין]\u0006 שהוא הוא — גם זה \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי בגויה\u0004 \u0005[בו].\u0006 \u0003אהדרוה ניהליה\u0004 \u0005[החזירו לו]\u0006 את הגט. \u0003אמר: לא ידענא אי\u0004 \u0005[אין אני יודע אם]\u0006 \u0003משום סימנא אהדרוה ניהלי\u0004 \u0005[הסימן החזירוהו לי]\u0006 \u0003וקא סברי\u0004 \u0005[וסבורים הם]\u0006 ש\u0003סימנין דאורייתא. אי\u0004 \u0005[אם]\u0006 \u0003משום טביעות עינא אהדרוה ניהלי\u0004 \u0005[עין החזירוהו לי]\u0006 ובמקרה זה לא לכל אדם מחזירים, \u0003ודוקא צורבא מדרבנן\u0004 \u0005[תלמיד חכם]\u0006 שמאמינים לדיבורו שאומר שהוא מכיר. \u0003אבל איניש דעלמא\u0004 \u0005[אדם סתם]\u0006 — \u0003לא\u0004 יחזירו לו, עד שיביא עדים או יתן סימן מובהק.","\u0003גופא\u0004 \u0005[לגופה\u0006 של הלכה\u0005]\u0006 שעסקנו בה, \u0003מצא גט אשה בשוק, בזמן שהבעל מודה\u0004 שנתן לה גט — \u0003יחזיר לאשה, אין הבעל מודה\u0004 — \u0003לא יחזיר לא לזה ולא לזה.\u0004","ונדייק: \u0003בזמן שהבעל מודה מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003יחזיר לאשה.\u0004 ושואלים: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא כתב ליתן ב\u0004חודש \u0003ניסן\u0004 וזהו התאריך שבגט, \u0003ולא נתן לה\u0004 אותו בפועל \u0003עד תשרי, ו\u0004בינתיים \u0003אזל\u0004 \u0005[הלך]\u0006 ה\u0003בעל זבין פירי\u0004 \u0005[\u0006ו\u0005מכר\u0006 את \u0005פירות\u0006 נכסי האשה\u0005]\u0006 \u0003מניסן ועד תשרי\u0004 כדין, שהרי כל עוד לא הגיע הגט לידה הריהי אשתו ופירות נכסיה שייכים לו, \u0003ו\u0004אחר כך \u0003מפקא לגיטא\u0004 \u0005[מוציאה\u0006 האשה \u0005את הגט]\u0006 ש\u0003כתב בניסן\u0004 \u0003ואתיא למטרף\u0004 \u0005[ובאה לטרוף]\u0006 מן ה\u0003לקוחות\u0004 את הפירות שקנו מן הבעל, ועושה היא זאת \u0003שלא כדין.\u0004","ומעירים: \u0003הא ניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003כיון שנתן עיניו\u0004 (החליט) \u0003לגרשה\u0004 וכתב גט, \u0003שוב אין לבעל פירות\u0004 — \u0003שפיר\u0004 \u0005[יפה]\u0006 ואין קושי, שמשעת התאריך שבגט לא היתה לבעל רשות למכור את הפירות, ואם קנו ממנו — טורפת האשה כדין. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003יש לבעל פירות עד שעת נתינה\u0004 של הגט בפועל, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003כי אתיא למטרף אמרינן\u0004 \u0005[כאשר באה\u0006 האשה \u0005לטרוף\u0006 מן הלקוחות \u0005אומרים אנו]\u0006 \u0003לה:\u0004 \u0003אייתי\u0004 \u0005[הביאי]\u0006 \u0003ראיה אימת מטא גיטא\u0004 \u0005[מתי הגיע הגט]\u0006 \u0003לידך,\u0004 וכשתוכיחי שהגט ניתן לך בתאריך הכתוב בו — נחזיר לך.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה\u0006 הדבר\u0005]\u0006 \u0003משטרי חוב? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא שטרי חוב, אם יש בהם אחריות נכסים\u0004 — \u0003לא יחזיר, ואוקימנא\u0004 \u0005[והעמדנו,\u0006 הסברנו זאת\u0005]\u0006 \u0003כשחייב מודה, ומשום\u0004 החשש \u0003שמא כתב ללוות בניסן ולא לוה עד תשרי וקא טריף\u0004 \u0005[וטורף]\u0006 מן ה\u0003לקוחות שלא כדין.\u0004","ומדוע לא נאמר אף \u0003התם נמי ליהדר\u0004 \u0005[שם גם כן שיחזיר]\u0006 לבעל השטר \u0003וכי אתי למטרף נימא ליה\u0004 \u0005[וכאשר יבוא לטרוף נאמר לו]\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה אימת מטא\u0004 \u0005[מתי הגיע]\u0006 \u0003שטר חוב לידך!\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 אין הדבר דומה, \u0003הכא גבי\u0004 \u0005[כאן אצל]\u0006 \u0003גט אשה אתי\u0004 \u0005[בא]\u0006 ה\u0003לוקח ותבעה,\u0004 שהוא מעלה בדעתו שמא נמסר הגט שלא בזמן כתיבתו, \u0003אמר\u0004 \u0005[אומר]\u0006 הלוקח: \u0003האי דהדרוה ניהלה רבנן לגיטא\u0004 \u0005[זה שהחזירו חכמים לה,\u0006 לאשה, \u0005את הגט]\u0006 הרי זה \u0003משום דלא תעגין ותיתיב\u0004 \u0005[תעגן ותשב\u0006 לבדה\u0005]\u0006 ולא תוכל להינשא, ולא הקפידו בצד הממון שבדבר. \u0003השתא דקא אתיא למטרף\u0004 \u0005[עכשיו שהיא באה לטרוף]\u0006 ממני ולקחת ממני ממון — \u0003תיזל ותיתי\u0004 \u0005[תלך ותביא]\u0006 \u0003ראיה אימת מטא גיטא\u0004 \u0005[מתי בא הגט]\u0006 \u0003לידה.\u0004","\u0003הכא גבי\u0004 \u0005[כאן אצל]\u0006 \u0003שטר חוב לא אתי\u0004 \u0005[יבוא]\u0006 ה\u0003לוקח ותבע\u0004 \u0005[לתבוע]\u0006 שלא יעלה על דעתו שיש צורך לבקש מבעל השטר ראיה, כי הוא סבור \u0003מדאהדרוה ניהליה רבנן\u0004 \u0005[מכיון שהחזירו לו חכמים]\u0006 את \u0003שטר\u0004 ה\u0003חוב,\u0004 \u0003פשיטא, למאי הלכתא אהדרוה ניהליה\u0004 \u0005[פשוט, לאיזו הלכה,\u0006 לאיזה ענין \u0005החזירו לו]\u0006 — \u0003למטרף הוא\u0004 \u0005[לטרוף בו],\u0006 \u0003שמע מינה קמו רבנן במילתא, ומקמי דידי מטא שטרא לידיה\u0004 \u0005[למד מכאן\u0006 כי \u0005עמדו חכמים על הדבר,\u0006 \u0005ו\u0006מצאו שהוא צודק \u0005לפני שהגיע השטר לידו].\u0006 ומשום כך באמת אמרו חכמים שלא יחזירו שטר זה בלא ראיה.","שנינו במשנה כי שטרות \u0003שחרורי עבדים\u0004 שנמצאו — אין מחזירים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מצא\u0004 אדם \u0003שטר שחרור בשוק, בזמן שהרב\u0004 (האדון) \u0003מודה\u0004 שנתנו לעבד — \u0003יחזיר לעבד, אין הרב מודה\u0004 שנתן — \u0003לא יחזיר לא לזה ולא לזה.\u0004","ושואלים: \u0003בזמן שהרב מודה מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003יחזיר לעבד, ואמאי\u0004 \u0005[ומדוע]\u0006 יחזיר? \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא כתב ליתן לו\u0004 שטר שחרור \u0003בניסן ולא נתן לו עד תשרי, ואזל עבדא\u0004 \u0005[והלך\u0006 אותו \u0005העבד]\u0006 \u0003וקנה נכסין מניסן ועד תשרי,\u0004 וכיון שהיה עבד הרי נכסים אלה הם של אדוניו, \u0003ואזיל הרב וזבנינהו\u0004 \u0005[והלך האדון\u0006 בעל העבד \u0005ומכרם]\u0006 לאותם נכסים \u0003ומפיק ליה לשחרור\u0004 \u0005[ומוציא\u0006 העבד \u0005את\u0006 שטר \u0005השחרור]\u0006 ש\u0003כתב בניסן\u0004 וטוען שהנכסים היו שלו ולא של האדון, \u0003וקא טריף\u0004 \u0005[ו\u0006נמצא ש\u0005הוא טורף]\u0006 מן ה\u0003לקוחות\u0004 \u0003שלא כדין,\u0004 שהרי באמת עדיין לא שוחרר אז, ובדין מכר האדון את הנכסים.","ומעירים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003זכות הוא לעבד שיוצא מתחת רבו לחירות, וכ\u0004דעת \u0003אביי\u0004 ש\u0003אמר: עדיו בחתומיו זכין ליה\u0004 \u0005[לו],\u0006 שמיד עם חתימת השטר כבר נעשו העדים כמזכים כל תוקף האמור בשטר למקבלו, אם כן במקרה כזה \u0003שפיר\u0004 \u0005[יפה],\u0006 שבזמן כתיבת השטר זכה העבד בשחרור גם לפני שנמסר לידו השטר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003חוב הוא לעבד שיוצא מתחת\u0004 יד \u0003רבו לחירות, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 הרי כל עוד לא ניתן השטר אין העבד משוחרר, וחתימת העדים על השטר אינה מועילה לנו, שאין לחייב אדם שלא בפניו. ונמצא שיש כאן אפשרות של טריפה שלא כדין!","ומשיבים: \u0003דכי אתי למטרף\u0004 \u0005[שכאשר יבוא לטרוף]\u0006 \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה אימת מטא\u0004 \u0005[מתי הגיע]\u0006 שטר ה\u0003שחרור לידך.\u0004","שנינו במשנה שאם מצא \u0003דייתיקי\u0004 (שטרי צוואה), או שטרי \u0003מתנה וכו'\u0004 לא יחזיר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזו היא דייתיקי,\u0004 שטר שכתוב בו מעין הדברים הללו: \u0003דא תהא למיקם\u0004 \u0005[זו תהא לעמוד]\u0006 \u0003ולהיות\u0004 ראיה \u0003שאם מת\u0004 האיש החותם על השטר, יהיו \u0003נכסיו לפלוני מתנה,\u0004 ובכגון זה \u0003כל\u0004 שטר כזה \u0003שכתוב בו \"מהיום ולאחר מיתה\"\u0004 יקנה.","ומדייקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003אי כתיבא\u0004 \u0005[אם כתוב]\u0006 בשטר במפורש \u0003\"מהיום ולאחר מיתה\" הוא דקני\u0004 \u0005[שקונה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 כתוב בו כן — \u0003לא קני\u0004 \u0005[אינו קונה]?!\u0006","\u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003איזו היא מתנת בריא,\u0004 כלומר, מתנה רגילה \u0003שהיא\u0004 לענין הדין \u0003כמתנת שכיב מרע\u0004 \u0005[חולה,\u0006 גוסס\u0005],\u0006 \u0003דלא קני\u0004 \u0005[שאינו קונה]\u0006 \u0003אלא לאחר מיתה, כל שכתוב בה\u0004 בשטר המתנה \u0003\"מהיום ולאחר מיתה\".\u0004","לגוף ההלכה הזו שואלים: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 שאין מחזירים שטר כזה ש\u0003לא אמר\u0004 הנותן \u0003\"תנו\". הא\u0004 \u0005[הרי]\u0006 אם \u0003אמר \"תנו\"\u0004 — \u0003נותנין.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003מצא דייתקאות\u0004 (שטרי צוואה), \u0003אפותיקאות\u0004 (שטרות של שעבוד קרקע מסויימת עבור חוב) \u0003ו\u0004שטרי \u0003מתנות, אף על פי ששניהם מודים\u0004 שנכתב השטר ונמסר — \u0003לא יחזיר לא לזה ולא לזה,\u0004 ואילו כאן אמרנו שיחזיר!","\u0003אמר ר' אבא בר ממל: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 \u0003ב\u0004שטר של מתנת \u0003בריא, והא\u0004 \u0005[וזה]\u0006 \u0003ב\u0004שטר של \u0003שכיב מרע\u0004 \u0005[גוסס].\u0006","ומסביר: \u0003מתניתין דקתני\u0004 \u0005[משנתנו ששנינו\u0006 בה\u0005]\u0006 \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003אמר \"תנו\" נותנין\u0004 מדובר \u0003ב\u0004מתנת \u0003שכיב מרע, דבר מהדר\u0004 \u0005[שבן חזרה]\u0006 \u0003הוא\u0004 שיכול לחזור בו, שכלל הוא שכל מה שכותב אדם חולה המצווה לתת דבר לאדם אחר לאחר מותו, יכול לחזור בו ולכתוב מתנתו לאחר.","\u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 \u0003דלמא כתבה מעיקרא להאי ואמליך\u0004 \u0005[שמא כתב מתחילה ל\u0006אדם \u0005זה ונמלך]\u0006 בדעתו \u0003ולא יהבה ניהליה\u0004 \u0005[נתנה לו],\u0006 \u0003והדר כתבה לאיניש אחרינא ויהביה ניהליה\u0004 \u0005[וחזר\u0006 ו\u0005כתב\u0006 שטר צוואה \u0005עבור אדם אחר ונתן\u0006 את השדה \u0005לו],\u0006 \u0003השתא קא הדר ביה מההוא דיהבה ניהליה\u0004 \u0005[עכשיו הוא שחזר בו מזה שנתן לו]\u0006 לאיש השני, ונמצא שמקפח אותו אדם שלוקח ממנו מה שכבר ניתן לו.","ואולם \u0003אי\u0004 \u0005[אם]\u0006 השטר הנמצא כעת כ\u0003מתנת בריא יהבה ליה\u0004 \u0005[נתן לו]\u0006 — \u0003לית ליה פסידא\u0004 \u0005[אין לו הפסד]\u0006 למקבל השטר באמת, שקבלו כמתנת שכיב מרע, שהרי \u0003דכי נפקא תרתי, בתרייתא זכי\u0004 \u0005[כאשר יצאו שני\u0006 השטרות לדין, זה שתאריכו \u0005האחרון יזכה],\u0006 \u0003דהא הדר ביה מקמייתא\u0004 \u0005[שהרי חזר בו מן\u0006 השטר \u0005הקודם].\u0006","\u0003אי\u0004 \u0005[אם]\u0006 \u0003במתנת שכיב מרע נמי יהבה ניהליה\u0004 \u0005[גם כן נתן אותו לו],\u0006 \u0003לית בה פסידא\u0004 \u0005[אין בכך הפסד]\u0006 \u0003דבתרייתא זכי\u0004 \u0005[שהאחרונה זוכה]\u0006 \u0003דקא הדר ביה מקמייתא\u0004 \u0005[שהוא חוזר בו מהראשונה].\u0006","אולם \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 \u0003בברייתא אף על פי ששניהם מודים לא יחזיר לא לזה ולא לזה\u0004 מדובר כאן \u0003ב\u0004מתנת \u0003בריא, דלאו בר מהדר הוא\u0004 \u0005[שאינו בר חזרה],\u0006 שאינו יכול לחזור בו ממה שנתן,","\u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003דלמא כתבה להאי מעיקרא ואמליך\u0004 \u0005[שמא כתב\u0006 שטר זה \u0005לזה תחילה ונמלך]\u0006 בדעתו \u0003ולא יהבה ליה\u0004 \u0005[נתן לו],\u0006 \u0003והדר כתבה לאיניש אחרינא ויהבה ליה\u0004 \u0005[וחזר וכתבה לאיש אחר ונתן לו]\u0006 \u0003השתא קא הדר ביה מההוא דיהבה ליה\u0004 \u0003וסבר\u0004 \u0005[עכשיו הוא\u0006 ש\u0005חזר בו מזה שנתן לו ו\u0006הוא \u0005סבור]:\u0006 \u0003מהדר לא מצינא הדרנא בי\u0004 \u0005[לחזור אינני יכול לחזור בי],\u0006 שהרי כבר נתתי — \u0003אימר להו דאנא להאי יהבתא, וניהדרו ניהליה כתבא\u0004 \u0005[אומר להם שאני\u0006 הוא ש\u0005נתתי\u0006 את השטר \u0005לזה, ויחזירו לו\u0006 את \u0005הכתב]\u0006 \u0003כי היכי דכי מפיק האי כתבא דקדים זכה ביה\u0004 \u0005[כדי שאם יוציא זה\u0006 את ה\u0005כתב שקדם זוכה בו]\u0006 \u0003הוא.\u0004","\u0003אלא אמרינן ליה אנן\u0004 \u0005[אומרים אנו לו אנחנו]:\u0006 \u0003האי כתבא לא יהבינן ליה להאי\u0004 \u0005[את הכתב הזה אין אנו נותנים ל\u0006אדם \u0005זה]\u0006 שכתבת לו. \u0003דלמא מכתב כתבת\u0004 \u0005[שמא כתבת]\u0006 ואולם \u0003מיהב\u0004 \u0005[לתת]\u0006 \u0003לא יהבת ניהליה\u0004 \u0005[נתת אותו לו]\u0006 \u0003ויהבתה לאיניש אחרינא וקא הדרת ביה\u0004 \u0005[ונתת לאיש אחר וחזרת בך],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אמנם \u0003לא יהבתה לאיניש אחרינא\u0004 \u0005[נתת לאדם אחר]\u0006 \u0003וקא בעית דתתבה להאי\u0004 \u0005[ואתה רוצה לתת אותה לזה]\u0006 \u0003כתיב ליה השתא כתבא אחרינא ויהביה ניהליה\u0004 \u0005[כתוב לו עכשיו כתב אחר ותן לו],\u0006 \u0003דאי יהבת לאיניש אחרינא\u0004 \u0005[שאם נתת\u0006 מקודם את הדבר במתנה \u0005לאיש אחר]\u0006 \u0003לית בה פסידא, דקדים זכי\u0004 \u0005[אין בו הפסד, ש\u0006הרי \u0005קדם\u0006 ו\u0005זכה\u0006 אותו אדם\u0005]\u0006 ששטרו יש בו תאריך מוקדם יותר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב זביד:\u0004 איך אפשר לפרש כך? \u0003והא אידי ואידי\u0004 \u0005[והרי זה וזה]\u0006 \u0003דייתקאות קא תני\u0004 \u0005[שנה]\u0006 ודייתקאות הם שטרי צוואה ולא שטרי מתנה! \u0003אלא אמר רב זביד,\u0004 כך נפרש: \u0003הא והא\u0004 \u0005[זו וזו]\u0006 מדובר \u0003ב\u0004מתנת \u0003שכיב מרע, ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 \u0003הא ביה\u0004 \u0005[זה\u0006 מדובר \u0005בו],\u0006 כאשר הבריא הנותן, והוא שמודה שאכן כתב את השטר שנמצא. \u0003והא בבריה\u0004 \u0005[וזה\u0006 מדובר \u0005בבנו],\u0006 שמת נותן השטר, ובנו־יורשו הוא שמאשר את אמיתות הכתב.","\u0003מתניתין דקא אמר\u0004 \u0005[משנתנו\u0006 ששנינו בה \u0005שאומר]\u0006 \u0003\"תנו\" נותנין\u0004 מדובר \u0003בדידיה\u0004 \u0005[בו,\u0006 בנותן עצמו\u0005]\u0006 \u0003דבר מהדר הוא\u0004 \u0005[שבן חזרה]\u0006 \u0003הוא,\u0004 שיכול הוא לחזור בו לאחר שהבריא, \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003אי נמי יהבה לאיניש אחרינא לית בה פסידא\u0004 \u0005[אם גם היה נותן\u0006 שטר אחר \u0005לאיש אחר אין בכך הפסד],\u0006 \u0003דקמא ובתרא\u0004 \u0005[שראשון ואחרון]\u0006 — \u0003בתרא זכי\u0004 \u0005[אחרון זוכה],\u0006 \u0003דהא הדר ביה מקמא\u0004 \u0005[שהרי חזר בו מן ראשון],\u0006 שהרי יכול לחזור בו ממתנת שכיב מרע.","\u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 \u0003בברייתא\u0004 \u0003אף על פי ששניהם מודים, לא יחזיר לא לזה ולא לזה,\u0004 מדובר \u0003בבריה\u0004 \u0005[בבנו]\u0006 של אותו אדם,","\u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כתב אבוה להאי\u0004 \u0005[אביו לזה],\u0006 \u0003ואמליך\u0004 \u0005[ונמלך]\u0006 \u0003ולא יהביה ניהליה\u0004 \u0005[נתן אותה לו]\u0006 \u0003ובתר אבוה\u0004 \u0005[ואחר אביו]\u0006 \u0003כתב איהו\u0004 \u0005[הוא],\u0006 הבן עצמו, את הדבר במתנה \u0003לאיניש אחרינא ויהבה ליה\u0004 \u0005[לאדם אחר ונתן אותה לו],\u0006 \u0003והשתא קא הדר ביה מההוא\u0004 \u0005[ועכשין חוזר הוא בעצמו מזו]\u0006 מהמתנה שהוא עצמו נתן. ואולם \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003מהדר לא מצינא הדרנא\u0004 \u0005[לחזור אין אני יכול לחזור]\u0006 \u0003בי,\u0004 שהרי בריא אני וכבר נתתי מתנה. \u0003אימר להו\u0004 \u0005[אומר להם]\u0006 ש\u0003אבא יהבה ליה להאי\u0004 \u0005[נתן לו\u0006 את השטר \u0005לזה]\u0006 \u0003ונתבו ליה כתביה\u0004 \u0005[ויתן לו\u0006 את \u0005כתבו],\u0006 \u0003וניזיל ונפיק מיניה דהוא זכי ונפלוג בהדיה\u0004 \u0005[אלך ואוציא ממנו\u0006 מן האיש \u0005שזכה ואחלוק עמו].\u0006","וכיון שיש חשש כזה \u0003הלכך אמרינן ליה אנן\u0004 \u0005[לכן אומרים אנו לו]:\u0006 \u0003האי כתבא לא יהבינן ליה להאי\u0004 \u0005[\u0006את \u0005השטר הזה אין אנו נותנים לזה\u0006 שכתוב לשמו\u0005],\u0006 \u0003דדלמא מכתב כתביה אבוה מיהב\u0004 \u0005[ששמא כתב אותו אביו ולתת]\u0006 \u0003לא יהבה ליה\u0004 \u0005[נתן לו],\u0006 \u0003ויהבתיה את לאיניש אחרינא וקא הדרת ביה\u0004 \u0005[ונותן אתה אותו לאדם אחר וחוזר אתה בך].\u0006","\u0003אלא, אי קושטא קא אמרת, דיהב ליה אבוך\u0004 \u0005[אם אמת אתה אומר ש\u0006את השטר \u0005נתן לו אביך]\u0006 \u0003זיל את השתא כתיב ליה שטרא אחרינא\u0004 \u0005[לך אתה עכשיו\u0006 \u0003ו\u0004\u0005כתוב לו שטר אחר]\u0006 של מתנה, \u0003דאי נמי\u0004 \u0005[שאם גם כן]\u0006 \u0003לא יהבה ליה אבוה\u0004 \u0005[נתן לו אביך]\u0006 את השדה \u0003וכתבתיה את לאיניש אחרינא\u0004 \u0005[ואתה כתבת\u0006 ונתת אותו \u0005לאדם אחר]\u0006 אף על פי כן \u0003לית בה פסידא\u0004 \u0005[אין לו הפסד]\u0006 לאיש שקבל את המתנה, \u0003דקמא ובתרא\u0004 \u0005[שראשון ואחרון]\u0006 — \u0003קמא זכי\u0004 \u0005[ראשון זוכה]\u0006 ויקבל בעל השטר שתאריכו קודם, ולא יהא לו בכך הפסד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מצא שובר\u0004 (שטר קבלה) של כתובה, \u0003בזמן שהאשה מודה\u0004 שאכן נפרעה כתובתה והיא שנתנה שובר זה — \u0003יחזיר\u0004 את השובר \u0003לבעל.\u0004 ואם \u0003אין האשה מודה\u0004 — \u0003לא יחזיר לא לזה ולא לזה.\u0004","ומדייקים: \u0003בזמן שהאשה מודה מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003יחזיר לבעל,\u0004 \u0003וליחוש דלמא\u0004 \u0005[ו\u0006אולם \u0005נחשוש שמא]\u0006 \u0003כתבה\u0004 האשה את השובר \u0003ליתן\u0004 לבעלה \u0003בניסן, ולא נתנה\u0004 את השובר בפועל \u0003עד תשרי, ואזלה זבנתה לכתובה\u0004 \u0005[והלכה ומכרה את כתובתה]\u0006 \u0003בטובת הנאה\u0004 — כלומר, שמכרה את כתובתה, בהתחשב בסיכון שלא תקבל כתובה ועשתה זאת בזמן \u0003מניסן עד תשרי, ו\u0004אחר כך","\u0003מפיק ליה\u0004 \u0005[מוציא הבעל אותו]\u0006 את ה\u0003שובר דכתיב\u0004 \u0005[שכתוב]\u0006 \u0003בניסן, ואתא למטרף\u0004 \u0005[ויבוא לטרוף]\u0006 מן ה\u0003לקוחות שלא כדין!\u0004","\u0003אמר רבא:\u0004"],["\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003איתא\u0004 \u0005[יש]\u0006 בסיס \u0003ל\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: המוכר שטר חוב לחבירו, וחזר ומחלו\u0004 שבעל השטר הראשון (המוכר) ויתר על החוב המגיע לו מן החייב — \u0003מחול\u0004 השטר, ואין קונה השטר יכול לגבותו עוד, אף כי הוא יכול לתבוע את המוכר לדין על שגרם לו הפסד, \u0003ואפילו יורש מוחל.\u0004 ועל פי הלכה זו, גם אם עשתה האשה קנוניה כזו, כיון שהכתובה היא שטר חוב מן הבעל לאשה, ואם רוצה האשה למחול בכל עת את שעבודה — הזכות בידה.","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003ליתיה\u0004 \u0005[אין\u0006 מקום\u0005]\u0006 \u0003ל\u0004דברי \u0003שמואל, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בששטר כתובה יוצא מתחת ידה\u0004 של האשה, שזה ברור שלא מכרה כתובתה ואין מקום לכל אותו חשש. \u0003ורבא אמר\u0004 כנגד דברי אביי: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום שטר כתובה\u0004 שבידה, הרי מכאן אין ראיה. \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא נתן לה \u0003שתי כתובות\u0004 והיא מכרה אחת מהן, ואת השניה היא מראה כעת.","\u0003ואביי אמר\u0004 בדחיית דברי רבא שני טעמים: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]:\u0006 \u0003לשתי כתובות לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שזוהי אפשרות רחוקה שאין להתחשב בה. \u0003ועוד,\u0004 שבעצם אין לחשוש אף לחשש הראשון, שכן הטוען מחמת \u0003שובר\u0004 שבידו \u0003בזמנו טריף\u0004 \u0005[טורף]\u0006 מן הלקוחות, כלומר, מן הזמן שנחתם בו ולא משעת מסירתו, ולפיכך אם תטרוף האשה — בדין תעשה. ומעירים: כי \u0003אביי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: עדיו בחתומיו זכין לו,\u0004 שמשעת חתימת השטר על ידי העדים חלו מיד ההתחייבויות הכתובות בשטר, וזכה בהם מי שנכתב השטר לזכותו.","\u0003מצא איגרות שום,\u0004 שהם שטרי בית דין ששמו את נכסי הלווה והחליטו לתת אותם למלוה לפרעון הלוואה שלא שולמה. \u0003ו\u0004כן \u0003אגרות מזון,\u0004 שהן שטרי התחייבות שהתחייב בעל לפרנס את בת אשתו מבעלה האחר, או שמצא \u0003שטרי חליצה\u0004 המעידים שאשה מסויימת קיימה מצות חליצה, או שטרי \u0003מיאונין,\u0004 שהם שטרי אישור של בית דין, שקטנה שנישואיה היו רק מדברי חכמים החליטה לבטל נישואיה, \u0003ושטרי בירורין, וכל מעשה בית דין\u0004 שאושר על ידי שטר כתוב — \u0003הרי זה יחזיר\u0004 לאלה \u0003שהשטרות נכתבו לצורכם.\u0004","\u0003מצא\u0004 שטר \u0003בחפיסה\u0004 (חבילה) \u0003או בדלוסקמא\u0004 (קופסא), או \u0003תכריך של שטרות,\u0004 כלומר, שטרות אחדים כרוכים יחד, \u0003או אגודה\u0004 (חבילה) \u0003של שטרות\u0004 — \u0003הרי זה יחזיר. וכמה\u0004 שטרות נחשבים \u0003אגודה של שטרות\u0004 — \u0003שלשה\u0004 שטרות \u0003קשורין זה בזה\u0004 קרויים אגודה. \u0003רבן שמעון בן גמליאל אומר:\u0004 יש לחלק בין אגודות ותכריכים שונים של שטרות; אם היו אלה שטרות של \u0003אחד הלוה משלשה\u0004 אנשים שונים — \u0003יחזיר ללוה,\u0004 שמסתבר שהלווה הוא שאיבדם, ששלושה שטרות אלה יחד אינם יכולים להיות אצל הלווה. ולהיפך, אם היו שטרות של \u0003שלשה הלוים מן האחד\u0004 — \u0003יחזיר למלוה.\u0004","\u0003מצא\u0004 אדם \u0003שטר בין שטרותיו,\u0004 שמישהו הפקיד בידו \u0003ואינו יודע מה טיבו,\u0004 כלומר, מי מסרו לו ואם נפרע השטר — \u0003יהא מונח עד שיבוא אליהו,\u0004 ובכח נבואתו יברר מה היה מעשה. \u0003אם יש עמהן\u0004 בין השטרות שמוצא \u0003סמפונות\u0004 (שוברים וביטולים של שטרות) \u0003יעשה מה שבסמפונות,\u0004 שבוודאי כבר ניתן הסימפון וביטל את השטר המקורי.","מתחילה מבררים את פירוש המלים במשנה. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שטרי בירורין\"?\u0004 ומסבירים: \u0003הכא תרגמו\u0004 \u0005[כאן,\u0006 בבבל, \u0005הסבירו]\u0006 שהם \u0003שטרי טענתא\u0004 \u0005[טענות],\u0006 שטרות שבהם נכתבו ונתבררו טענותיהם של שני הצדדים המתדיינים. \u0003ר' ירמיה\u0004 בארץ ישראל \u0003אמר: זה בורר לו אחד וזה בורר לו אחד,\u0004 כלומר, שהיו אלה שטרי בוררים שבהם חתם כל צד את מי בחר לו כדיין.","שנינו במשנה ש\u0003כל מעשה בית דין הרי זה יחזיר.\u0004 מסופר: \u0003ההוא גיטא דאשתכח בי דינא\u0004 \u0005[גט אחד שנמצא בבית דינו]\u0006 של \u0003רב הונא, דהוה כתיב ביה\u0004 \u0005[שהיה כתוב בו]\u0006 שנעשה \u0003\"בשוירי\u0004 \u0003מתא\u0004 \u0005[העיר]\u0006 ש\u0003על רכיס נהרא\u0004 \u0005[הנהר]\u0006 \u0003\".\u0004 \u0003אמר רב הונא:\u0004"],["\u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לשני\u0004 מקומות בשם \u0003שוירי,\u0004 ואין להחזיר, שמא יש מקום אחר בשם זה ושם מצוי עוד זוג באותם שמות ולהם שייך הגט. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה: פוק\u0004 \u0005[צא]\u0006 ו\u0003עיין\u0004 בדבר, \u0003דלאורתא בעי לה\u0004 \u0005[שבערב ישאל]\u0006 \u0003רב הונא מינך\u0004 \u0005[ממך]\u0006 מה דעתך בענין זה. \u0003נפק דק ואשכח\u0004 \u0005[יצא\u0006 מבית המדרש, חיפש ו\u0005חשב ומצא]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל מעשה בית דין הרי זה יחזיר.\u0004 משמע שאין חוששים לכפל שמות כזה, כל עוד לא נודע לנו שהוא קיים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עמרם לרבה: היכי פשיט מר איסורא מממונא\u0004 \u0005[כיצד פותר אדוני\u0006 בעיה של \u0005איסור\u0006 והיתר \u0005מ\u0006בעיות של \u0005ממון]\u0006 שהרי מה שנאמר במשנה הוא בשטרות של ממון, וכאן מדובר בגט שיש בו חשש לאיסור חמור! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תרדא\u0004 \u0005[שוטה],\u0006 הלא במפורש \u0003\"שטרי חליצה ומיאונין\" תנן\u0004 \u0005[שנינו\u0006 שם\u0005],\u0006 שהרי נתפרש במשנה בין הדברים שמחזירים גם שטרות השייכים לדיני אישות.","ומספרים: \u0003פקע ארזא דבי\u0004 \u0005[נשבר הארז,\u0006 העמוד המחזיק \u0005את בית\u0006 המדרש\u0005]\u0006 של \u0003רב\u0004 שבו היה ויכוח זה. \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003אמר: משום לתאי דידי\u0004 \u0005[מזלי,\u0006 סיבתי \u0005שלי]\u0006 \u0003פקע\u0004 \u0005[נשבר]\u0006 העמוד, שכן העלבת אותי. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003אמר: משום לתאי דידי\u0004 \u0005[מזלי,\u0006 סיבתי \u0005שלי]\u0006 \u0003פקע\u0004 \u0005[נשבר]\u0006 שאתה הוא שהעלבת אותי.","שנינו במשנה שאם \u0003מצא בחפיסה או בדלוסקמא\u0004 — הרי זה יחזיר. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חפיסה\"? אמר רבה בר בר חנה: חמת\u0004 (נאד) \u0003קטנה\u0004 שהיו מכניסים בו חפצים שונים. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דלוסקמא\"? אמר רבה בר שמואל: טליקא דסבי\u0004 \u0005[תיק של זקנים]\u0006 שבו הם מניחים את חפציהם.","עוד שנינו במשנה שאם מצא \u0003תכריך של שטרות או אגודה של שטרות\u0004 — הרי זה יחזיר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כמה הוא תכריך של שטרות?\u0004 — \u0003שלשה\u0004 שטרות \u0003כרוכין זה בזה\u0004 וגלולים יחד. \u0003וכמה היא אגודה של שטרות?\u0004 — \u0003שלשה\u0004 שטרות \u0003קשורין זה בזה.\u0004","ומעירים: \u0003שמעת מינה\u0004 \u0005[שומע,\u0006 למד \u0005אתה מכאן]\u0006 פתרון לשאלה שנשאלה במקום אחר ש\u0003קשר\u0004 עצמו הוא \u0003סימן\u0004 שהמוצא מחזיר את השטרות כאשר מתאר לו בעל השטרות מה היה טיב הקשר.","ודוחים: מכאן אין להוכיח, \u0003הא תני\u0004 \u0005[הרי שנה]\u0006 \u0003ר' חייא\u0004 שאגודה זו היא \u0003שלשה\u0004 שטרות \u0003כרוכין זה בזה\u0004 וזה הסימן.","ומקשים: \u0003אי הכי היינו\u0004 \u0005[אם כך זהו]\u0006 \u0003תכריך?\u0004 ומה ההבדל בינו ובין אגודה? ומשיבים: יש הבדל, \u0003תכריך\u0004 הכוונה היא \u0003כל חד וחד בראשה דחבריה\u0004 \u0005[כל אחד ואחד בראש חבירו],\u0006 שהם כרוכים בזה אחר זה, ואילו \u0003אגודה דרמו אהדדי\u0004 \u0005[שמונחים זה על גבי זה]\u0006 \u0003וכרוכות\u0004 כולן יחד.","ושואלים: אם כן \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מכריז\u0004 המוצא, שיוכל בעל השטרות לתת בו סימן? ומשיבים: \u0003מנין,\u0004 שמכריז שמצא שלושה שטרות והמאבד נותן סימן שכרוכים היו יחד.","ומקשים: אם עצם הכריכה היא הסימן, אם כן \u0003מאי אריא תלתא\u0004 \u0005[מה שנה דווקא שלושה]\u0006 שטרות כאגודה \u0003אפילו תרין נמי\u0004 \u0005[שניים גם כן]\u0006 יכול להכריז שמצא, והמאבד יאמר שהיו כרוכים!","\u0003אלא כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבינא\u0004 לענין אחר: \u0003טבעא מכריז,\u0004 שהמוצא מכריז \"מטבעות מצאתי\", \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"שטרי\"\u0004 \u0005[\"שטרות\u0006 מצאתי\"\u0005]\u0006 \u0003מכריז.\u0004 ועל המאבד לומר את מניינם המדוייק ושהיו כרוכים. ואם היו רק שני שטרות, ואדם נותן סימן זה ששניים הם, אין זה סימן, שהרי המכריז עצמו הכריז בלשון רבים שמשמעו שניים לפחות. משום כך, רק אם היו שלושה שטרות ויאמר המאבד שהיו שלושה, לא פחות ולא יותר — יהא זה סימן, בנוסף לכך שהיו כרוכים.","שנינו כי \u0003רבן שמעון בן גמליאל אומר\u0004 שיש לחלק בין השטרות הנמצאים יחד, אם היו שטרות של \u0003אחד הלוה משלשה יחזיר ללוה.\u0004 ומסבירים: \u0003דאי סלקא דעתך דמלוין נינהו\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר \u0005ש\u0006השטרות \u0005של המלוים הם]\u0006 \u0003מאי בעו גבי הדדי\u0004 \u0005[מה נצרכו\u0006 להיות \u0005זה עם זה]?\u0006","ושואלים: \u0003דלמא לקיומינהו אזלי\u0004 \u0005[שמא לקיים אותם הלכו]\u0006 המלוים, ואבדו מידי בית הדין? ומשיבים: \u0003דמקיימי\u0004 \u0005[ש\u0006היו אלה שטרות \u0005מקויימים].\u0006","ומקשים: \u0003דלמא מידא דספרא נפיל\u0004 \u0005[שמא מידו של הסופר ש\u0006הלך לקיימם \u0005נפלו]?\u0006 ודוחים: \u0003לא משהי איניש קיומיה בידא דספרא\u0004 \u0005[אין אדם משהה\u0006 שטר \u0005מקויים בידו של הסופר],\u0006 ולכן ברור ששלושה שטרות אלו שייכים ללווה.","כמו כן שנינו במשנה בשם רבן שמעון בן גמליאל שאם מצא שלושה שטרות של \u0003שלשה שלוו מאחד\u0004 — \u0003יחזיר למלוה.\u0004 ומסבירים: \u0003דאי סלקא דעתך דלוין נינהו מאי בעו גבי הדדי\u0004 \u0005[שאם עולה על דעתך ש\u0006השטרות הם \u0005של הלווים מה נצרכו\u0006 להיות \u0005זה עם זה]?\u0006","ושואלים: \u0003דלמא למכתבנהו אזלי\u0004 \u0005[\u0006ו\u0005שמא\u0006 הלווים \u0005לכתוב אותם,\u0006 את השטרות, \u0005הלכו]\u0006 אצל סופר אחד, וממנו נפלו ואבדו? ומשיבים: \u0003דכתיבי בתלת ידי ספרי\u0004 \u0005[שכתובים בשלושה ידי סופרים],\u0006 שמבחינים שאין זה כתב ידו של סופר אחד.","ושואלים: \u0003ודלמא לקיומינהו אזלי\u0004 \u0005[ושמא לקיים\u0006 את השטרות בבית דין \u0005הלכו]\u0006 ומשם נפלו? ומשיבים: לזה אין לחשוש, כי מתקבל על הדעת שה\u0003מלוה מקיים\u0004 את \u0003שטריה\u0004 \u0005[שטרו]\u0006 בבית דין שיוכל לגבותו, ואולם \u0003לוה לא מקיים\u0004 את \u0003שטריה\u0004 \u0005[שטרו],\u0006 שאין לו כל ענין בכך, ולכן אין לחשוש לאפשרות זו.","שנינו במשנה ש\u0003אם יש עמהן סמפונות\u0004 (שוברים וביטולים של שטרות) — \u0003יעשה מה שבסמפונות. אמר רב ירמיה בר אבא אמר רב: סמפון היוצא מתחת ידי המלוה,\u0004 שהמלוה מחזיק אותו בידו, \u0003אף על פי שכתוב בכתב ידו\u0004 של המלוה עצמו ואין לחשוש לזיוף — \u0003אינו אלא כמשחק, ופסול\u0004 שאין לסמוך עליו.","ומעירים: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר אם סימפון \u0003כתוב בכתב יד סופר, דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 \u0003ספרא אתרמי ליה\u0004 \u0005[סופר הזדמן לו]\u0006 למלוה זה \u0003וכתב\u0004 שיהיה שובר מוכן בידו לתת ללווה כשיפרע, \u0003אלא אפילו כתוב\u0004 הסימפון \u0003בכתב ידו\u0004 של המלוה גם כן הוא \u0003פסול\u0004 ואינו לשימוש. שיש לומר מפני מה כתבו המלוה — \u0003סבר דלמא מתרמי ואתי\u0004 \u0005[שמא יזדמן ויבוא]\u0006 \u0003בין השמשות\u0004 בערב שבת \u0003וקא פרע\u0004 \u0005[ויפרע]\u0006 \u0003לי, דאי\u0004 \u0005[שאם]\u0006 \u0003לא יהיבנא ליה\u0004 \u0005[אתן לו]\u0006 שובר \u0003לא יהיב\u0004 \u0005[יתן]\u0006 \u0003לי זוזי\u0004 \u0005[\u0006את \u0005הכסף],\u0006 על כן \u0003אכתוב אנא\u0004 \u0005[אני]\u0006 שובר מוכן \u0003דכי אייתי\u0004 \u0005[שכאשר יביא]\u0006 \u0003לי זוזי\u0004 \u0005[\u0006את \u0005הכסף]\u0006 \u0003אתן ליה\u0004 \u0005[לו].\u0006 מיד.","ומקשים, הלא \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם יש עמהן סמפונות יעשה מה שבסמפונות,\u0004 ולכאורה מדובר אפילו בסימפונות שביד המלוה.","ודוחים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 לענין אחר \u0003רב ספרא: שנמצא\u0004 הסימפון \u0003בין שטרות קרועין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שמצאו בין שטרות קרועין,\u0004 שמסתבר שהסימפון היה שובר לאחד השטרות שנקרעו מפני שנפרעו כבר.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו: \u0003נמצא לאחד בין שטרותיו\u0004 פתק שכתוב בו: \u0003שטרו של יוסף בן שמעון פרוע,\u0004 והיו במקום שני יוסף בן שמעון שלוו ממנו — \u0003שטרות שניהם פרועין,\u0004 שכל אחד מהם טוען שהשובר היה על שטר שלו. והרי שלמדים מכאן שמשגיחים בסימפון הנמצא ביד מלוה!","ומשיבים: \u0003כדאמר רב ספרא: שנמצא בין שטרות קרועין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שנמצא בין שטרות קרועין.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו: יורשים יתומים הבאים לגבות חוב מיתומים אחרים, הריהם נשבעים: \u0003\"שבועה שלא פקדנו אבא\u0004 בצוואתו, \u0003ושלא אמר לנו אבא\u0004 קודם לכן שנפרע חוב זה, \u0003ושלא מצאנו בין שטרותיו של אבא\u0004 כתוב \u0003ששטר זה פרוע\".\u0004 ומכאן משמע שאם נמצא הסימפון בין השטרות של האב המלוה הרי זו הוכחה לפרעון!","\u0003אמר רב ספרא:\u0004 מדובר \u0003שנמצא בין שטרות קרועין.\u0004","ומציעים עוד ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003סמפון שיש עליו עדים יתקיים בחותמיו\u0004 ואפילו נמצא בידי המלוה, משמע שהסימפון ביד מלוה יש לו תוקף, ואם מקיימים אותו עושים ככתוב בו. ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 \u0003יתקיים מחותמיו,\u0004 כיצד?"],["\u0003דשיילינן להו לסהדי\u0004 \u0005[ששואלים אנו את העדים\u0006 החתומים\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 החוב \u0003פרוע אי\u0004 \u0005[או]\u0006 \u0003לא פרוע,\u0004 ועל פיהם עושים. ושוב מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה ששנינו: \u0003סמפון שיש עליו עדים\u0004 — \u0003כשר,\u0004 ומשמע שאין חילוק בידי מי היה! ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עדים\"? עדי קיום,\u0004 שהיה הסימפון מקויים בבית דין, ואין בית דין מקיימים סימפון אלא אם כן יודעים שהשטר פרוע.","","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו בסופה]\u0006 של אותה ברייתא: \u0003ושאין עליו עדים\u0004 — \u0003פסול.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין עליו עדים\"? אילימא דליכא עלויה\u0004 \u0005[אם תאמר שאין עליו]\u0006 \u0003עדים כלל,\u0004 וכי \u0003צריכא למימר\u0004 \u0005[צריך היה לומר]\u0006 בכגון זה שהוא \u0003פסול,\u0004 הרי אין כל הוכחה לאמיתותו?! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה כפי שפירשנו שאין עליו \u0003עדי קיום.\u0004","כיון שהבאנו ברייתא זו, דנים בה ל\u0003גופא. סמפון שיש עליו עדים\u0004 — \u0003יתקיים בחותמיו. אין עליו עדים ויוצא מתחת ידי שליש,\u0004 שהוא אדם שלישי שהפקידו בידו הצדדים את הסימפון, \u0003או שיוצא לאחר חיתום שטרות,\u0004 שהסימפון כתוב בגופו של השטר לאחר החתימה — הרי זה \u0003כשר.\u0004","ומסבירים: \u0003יוצא מתחת ידי שליש כש\u0004ר — \u0003דהא הימניה\u0004 \u0005[שהרי האמין בו]\u0006 \u0003מלוה לשליש\u0004 כפי שמוכח ממסירת הסימפון לידו, ויש לקבל את טענת השליש שהחוב נפרע. \u0003יוצא לאחר חיתום שטרות נמי\u0004 \u0005[גם כן],\u0006 \u0003דאי לאו דפריע\u0004 \u0005[שאם לא ש\u0006היה החוב \u0005פרוע]\u0006 \u0003לא הוה מרע ליה לשטריה\u0004 \u0005[היה מקלקל את שטרו]\u0006 וכותב את הסימפון על גוף השטר.","","\u0003אלו מציאות שלו,\u0004 של המוצא, \u0003ואלו חייב להכריז\u0004 עליהן שמצא, כדי שיוכל בעל האבידה לבוא ולזהות את אבידתו? \u0003אלו מציאות שלו: מצא פירות מפוזרין,\u0004 או \u0003מעות\u0004 (מטבעות) \u0003מפוזרות, כריכות\u0004 (אלומות תבואה) \u0003ברשות הרבים,\u0004 או \u0003עיגולי דבילה\u0004 (תאנים מיובשות הכבושות בצורת עיגול), או \u0003ככרות\u0004 לחם \u0003של נחתום\u0004 (אופה), או \u0003מחרוזות של דגים,\u0004 או \u0003חתיכות של בשר,\u0004 או \u0003גיזי צמר הלקוחין ממדינתן\u0004 (מן הכפר) לאחר הגז ללא עיבוד נוסף, או \u0003אניצי\u0004 (גבעולי) \u0003פשתן\u0004 צרורים, או \u0003לשונות של ארגמן\u0004 (חתיכות צמר סרוק הצבוע בצבע ארגמן) — \u0003הרי אלו שלו,\u0004 אלו \u0003דברי ר' מאיר.\u0004 שכל אלה הם דברים בעלי צורה אחידה ואין בהם סימנים מיוחדים שעל פיהם יוכלו המאבדים לזהות את אבידותיהם.","","\u0003ר' יהודה אומר: כל\u0004 שמצא חפץ \u0003שיש בו שינוי\u0004 מצורתו הרגילה — \u0003חייב להכריז\u0004 עליו. \u0003כיצד? מצא עגול\u0004 דבילה \u0003ו\u0004אולם \u0003בתוכו\u0004 היה גם \u0003חרס,\u0004 או שמצא \u0003ככר ובתוכו מעות\u0004 — חייב להכריז כי יתכן שבעל האבידה הוא ששם שם את אלה, ויש לו איפוא סימן בהם. \u0003ר' שמעון בן אלעזר אומר: כל כלי אנפוריא\u0004 (כלים הבאים זה עתה מן השוק) שיש להם צורה אחידה ועדיין אין בהם סימני היכר \u0003אין חייב להכריז\u0004 עליהם.","","שנינו במשנה בין שאר הדברים שאין בהם סימן מיוחד גם ש\u0003מצא פירות מפוזרין.\u0004 ושואלים: \u0003וכמה\u0004 נחשב פיזור? \u0003אמר ר' יצחק:\u0004 אם \u0003קב\u0004 של פירות מפוזר \u0003ב\u0004שטח של \u0003ארבע אמות.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003דרך נפילה,\u0004 שהפירות מפוזרים באופן כזה שנראה שנפלו ולא הונחו שם — \u0003אפילו\u0004 היו \u0003טובא\u0004 \u0005[הרבה]\u0006 יותר מקב, כיון שאין בהם סימן ולא יוכל המאבד לזהותם \u0003נמי\u0004 \u0005[גם כן]\u0006 יהיו הם של המוצא! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003דרך הינוח,\u0004 שנראה שהונחו שם בכוונה — \u0003אפילו בציר מהכי נמי\u0004 \u0005[פחות מכאן גם כן]\u0006 \u0003לא,\u0004 שוודאי יבוא בעל הפירות ויקח אותם! \u0003אמר רב עוקבא בר חמא: במכנשתא דבי דרי עסקינן\u0004 \u0005[ב\u0006זמן \u0005כינוס\u0006 תבואה \u0005בבית הגרנות אנו עוסקים],\u0006 שנשארו גרגירי חיטה במקום שהיתה בו הגורן, וחיטים אלה נשארו ולא נלקחו. וכן הוא הסבר דברי ר' יצחק: \u0003קב\u0004 גרעיני חיטה \u0003בארבע אמות דנפיש טרחייהו\u0004 \u0005[שמרובה טירחתם]\u0006 לאסוף אותם — \u0003לא טרח איניש ולא הדר אתי ושקיל להו\u0004 \u0005[אין אדם טורח ואינו חוזר\u0006 ו\u0005בא ולוקח אותם],\u0006 אלא \u0003אפקורי מפקר להו\u0004 \u0005[מפקיר\u0006 הוא \u0005אותם]\u0006 ולכן רשאי המוצא לקחתם. \u0003בציר מהכי\u0004 \u0005[ב\u0006פיזור \u0005קטן מזה]\u0006 \u0003טרח והדר אתי ושקיל להו, ולא מפקר להו\u0004 \u0005[טורח וחוזר\u0006 ו\u0005בא ולוקח אותם, ואינו מפקיר אותם].\u0006 ביררנו איפוא את שיטת ההסבר של ר' יצחק, ואולם מתעוררות שאלות מעשיות שונות.","","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם היה \u0003חצי קב\u0004 מפוזר \u0003בשתי אמות, מהו?\u0004 וצדדי השאלה: \u0003קב בארבע אמות טעמא מאי\u0004 \u0005[מה הטעם]\u0006 מפקיר? — \u0003משום דנפיש טרחייהו\u0004 \u0005[שמרובה טירחתם\u0006 לאוספם\u0005],\u0006 ואם כן \u0003חצי קב\u0004 המפוזר \u0003בשתי אמות, כיון דלא נפיש טרחייהו\u0004 \u0005[שאין טירחתם מרובה]\u0006 ששתי אמות הן שטח קטן, \u0003לא מפקר להו\u0004 \u0005[אינו מפקיר אותם].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 נסביר באופן אחר: קב בארבע אמות מפקיר הבעלים \u0003משום דלא חשיבי\u0004 \u0005[שאינם חשובים]\u0006 לחזור עבור כמות קטנה כזו, \u0003וחצי קב בשתי אמות,\u0004 \u0003כיון\u0004 שבוודאי \u0003לא חשיבי\u0004 \u0005[אינם חשובים]\u0006 — ודאי ש\u0003מפקר להו\u0004 \u0005[מפקיר אותם].\u0006","ועל אותו בסיס אפשר לשאול שאלה אחרת: \u0003קביים\u0004 (שני קבים) המפוזרים \u0003בשמונה אמות, מהו?\u0004 וצדדי השאלה: \u0003קב בארבע אמות טעמא מאי\u0004 \u0005[מה הטעם]\u0006 מותרים למוצא? — \u0003משום דנפיש טרחייהו\u0004 \u0005[שמרובה טירחתם]\u0006 לאוספם, \u0003וכל שכן קביים בשמונה אמות, כיון דנפישא טרחייהו טפי\u0004 \u0005[שמרובה טירחתם יותר]\u0006 — \u0003מפקר להו\u0004 \u0005[מפקיר אותם],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 הטעם \u0005בקב המפוזר בארבע אמות הוא\u0006 \u0003משום דלא חשיבי\u0004 \u0005[ש\u0006הכמות \u0005אינה חשובה]\u0006 \u0003וקביים בשמונה אמות כיון דחשיבי\u0004 \u0005[ש\u0006הם \u0005חשובים]\u0006 — \u0003לא מפקר להו\u0004 \u0005[אינו מפקיר אותם].\u0006","ועוד שאלה אחרת: \u0003קב שומשמין\u0004 המפוזר \u0003בארבע אמות, מהו?\u0004 וצדדי השאלה: \u0003קב בארבע אמות טעמא מאי\u0004 \u0005[מה הטעם]?\u0006 — \u0003משום דלא חשיבי\u0004 \u0005[שאינם חשובים],\u0006 \u0003ושומשמין כיון דחשיבי\u0004 \u0005[ש\u0006הם \u0005חשובים]\u0006 ויקרים — \u0003לא מפקר להו\u0004 \u0005[אינו מפקיר אותם].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 הטעם בקב חיטים הוא \u0003משום דנפיש טרחייהו\u0004 \u0005[שמרובה טירחתם]\u0006 \u0003וכל שכן שומשמין, כיון\u0004 שהם זרעים קטנים ביותר \u0003דנפיש טרחייהו טפי\u0004 \u0005[שמרובה טירחתם יותר]\u0006 — \u0003מפקר להו\u0004 \u0005[מפקיר אותם].\u0006","ולצד אחר: \u0003קב תמרי\u0004 \u0005[תמרים]\u0006 \u0003בארבע אמות, קב רמוני\u0004 \u0005[רמונים]\u0006 \u0003בארבע אמות, מהו?\u0004 וצדדי השאלה: \u0003קב\u0004 גרעיני חיטה המפוזרים \u0003בארבע אמות טעמא מאי\u0004 \u0005[מה הטעם]?\u0006 — \u0003משום דלא חשיבי\u0004 \u0005[שאינם חשובים],\u0006 אם כן \u0003קב תמרי\u0004 \u0005[תמרים]\u0006 \u0003בארבע אמות, קב רמוני\u0004 \u0005[רמונים]\u0006 \u0003בארבע אמות נמי\u0004 \u0005[גם כן]\u0006 \u0003כיון דלא חשיבי\u0004 \u0005[שאינם חשובים]\u0006 — \u0003מפקר להו\u0004 \u0005[מפקיר אותם].\u0006","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום דנפישא טרחייהו\u0004 \u0005[שמרובה טירחתם\u0006 באיסוף\u0005],\u0006 \u0003וקב תמרי\u0004 \u0005[תמרים]\u0006 \u0003בארבע אמות, וקב רמוני\u0004 \u0005[רמונים]\u0006 \u0003בארבע אמות, כיון דלא נפיש טרחייהו\u0004 \u0005[שאין טירחתם מרובה]\u0006 — \u0003לא מפקר להו\u0004 \u0005[אינו מפקיר אותם].\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין בכל אלה? לשאלות אלה לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה:"],["\u0003יאוש שלא מדעת\u0004 כלומר, אבידה שלפי מהותה יש לשער שבעל האבידה יתייאש מן האבידה לכשיודע לו שאיבד אותה. אולם לא ידוע לנו אם כבר נודעה האבידה לבעלים בשעת המציאה, ואם כן, יש באבידה כזו יאוש בכוח, ולא ברור לנו אם נעשה כבר בפועל, שלא ברור אם הבעלים כבר ויתרו (על ידי יאוש) על בעלותם על החפץ. ומה דין מציאה כזאת? \u0003אביי אמר: לא הוי\u0004 \u0005[אין זה]\u0006 \u0003יאוש\u0004 והחפץ שייך עדיין לבעליו עד שיתייאשו. \u0003ורבא אמר: הוי\u0004 \u0005[הרי זה]\u0006 \u0003יאוש.\u0004","ומסייגים את המחלוקת מצדדים שונים; \u0003בדבר שיש בו סימן\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 \u0003דלא הוי\u0004 \u0005[שאין זה]\u0006 \u0003יאוש. ואף על גב דשמעיניה דמיאש לסוף\u0004 \u0005[ואף על פי ששמענו אותו,\u0006 את בעל האבידה, \u0005ש\u0006הוא \u0005מתייאש לבסוף]\u0006 כאשר עבר זמן והחפץ לא חזר לידו, \u0003לא הוי\u0004 \u0005[אין זה]\u0006 נחשב \u0003יאוש,\u0004 \u0003דכי אתא לידיה\u0004 \u0005[שכאשר באה לידו]\u0006 של מוצא האבידה — \u0003באיסורא הוא דאתא לידיה\u0004 \u0005[באיסור הוא שבאה לידו].\u0006 ומדוע? \u0003דלכי ידע דנפל מיניה לא מיאש\u0004 \u0005[שכאשר ידע\u0006 המאבד \u0005שנפלה ממנו\u0006 אבידה זו \u0005אינו מתייאש\u0006 ממנה\u0005],\u0006 \u0003מימר אמר: סימנא אית ליה בגויה, יהבנא סימנא ושקילנא ליה\u0004 \u0005[אמור אמר: סימן יש לי בו, אתן סימן ואקח אותו]\u0006 ולכן אינו מתייאש מן החפץ, והמוצא מציאה כזו ונוהג בה כאילו היתה שלו — הרי זה גזלן.","ומצד אחר, חפצים שנשטפו \u0003בזוטו של ים\u0004 (בגאות הים) \u0003ובשלוליתו של נהר\u0004 (בנהר העולה על גדותיו), \u0003אף על גב דאית ביה\u0004 \u0005[אף על פי שיש בו]\u0006 \u0003סימן\u0004 \u0003רחמנא שרייה\u0004 \u0005[התורה התירה אותו]\u0006 למוצא, \u0003כדבעינן למימר לקמן\u0004 \u0005[כפי שנצטרך לומר להלן]\u0006 בהמשך הדיון.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 אביי ורבא היה זה \u0003בדבר שאין בו סימן.\u0004 והמחלוקת היא לפיכך: \u0003אביי אמר: לא הוי\u0004 \u0005[אין זה]\u0006 \u0003יאוש, דהא לא ידע דנפל מיניה\u0004 \u0005[שהרי לא ידע\u0006 המאבד שהחפץ \u0005נפל ממנו]\u0006 ועדיין לא התייאש. ואילו \u0003רבא אמר: הוי\u0004 \u0005[הרי זה]\u0006 \u0003יאוש, דלכי ידע דנפל מיניה מיאש\u0004 \u0005[שכאשר ידע ש\u0006החפץ \u0005נפל ממנו מתייאש].\u0006 \u0003מימר אמר: סימנא לית לי בגויה\u0004 \u0005[אמור אמר: סימן אין לי בו],\u0006 ואם כן \u0003מהשתא הוא דמיאש\u0004 \u0005[מעכשיו הוא מתייאש]\u0006 למפרע משעת האבידה.","ומעתה מביאים ראיות ממקורות רבים לכל אחת מן השיטות וסימנם בראשי תיבות \u0003פמג\"ש ממקגט\"י ככסע\"ז.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו: \u0003\"פירות מפוזרין\"\u0004 הרי הם למוצא, \u0003הא לא ידע דנפל מיניה\u0004 \u0005[הרי לא ידע\u0006 המאבד \u0005שנפל ממנו]\u0006 ובכל זאת נאמר כי הפירות שייכים למוצא, משמע שיאוש שלא מדעת הריהו יאוש! ודוחים: \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר רב עוקבא בר חמא: הכא במכנשתא דביזרי עסקינן\u0004 \u0005[כאן ב\u0006זמן \u0005כינוס חיטה בגרנות עוסקים אנו]\u0006 ש\u0003אבידה מדעת היא\u0004 שבעל החיטים ידע שהשאירן שם, והפקירן מדעת, ואין להוכיח מכאן לעניננו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מקטע אחר במשנתנו: \u0003מעות מפוזרות\u0004 — \u0003הרי אלו שלו, אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הא לא ידע דנפל מיניה\u0004 \u0005[הרי לא ידע ש\u0006המעות \u0005נפלו ממנו]\u0006 ובכל זאת שייכים למוצא! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 אפשר לומר \u0003כ\u0004דברי \u0003ר' יצחק,\u0004 ש\u0003אמר\u0004 לענין אחר: \u0003אדם עשוי למשמש בכיסו בכל שעה ושעה.\u0004 ויש להניח שבזמן קצר מאד לאחר האבידה כבר ידע המאבד שהמעות אבדו לו. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אדם עשוי למשמש בכיסו בכל שעה ושעה.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקרה אחר, ששנינו במשנה: \u0003עיגולי דבילה וככרות של נחתום\u0004 — \u0003הרי אלו שלו. אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא לא ידע דנפל מיניה\u0004 \u0005[והרי לא ידע שנפלו ממנו]?\u0006 ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 שונה הדבר, \u0003אגב דיקירי מידע ידע בהו\u0004 \u0005[כיון ש\u0006הם \u0005כבדים יודע\u0006 הוא \u0005בהם]\u0006 שלאחר זמן קצר מרגיש אדם שמשא כבד נפל ממנו, והוא מתייאש מיד.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת: אמרנו במשנה ש\u0003לשונות של ארגמן הרי אלו שלו. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא לא ידע דנפל מיניה\u0004 \u0005[הרי אינו יודע שנפלו ממנו]?\u0006 ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003אגב דחשיבי\u0004 \u0005[כיוו ש\u0006הם \u0005חשובים\u0006 ויקרים\u0005]\u0006 \u0003משמושי ממשמש בהו\u0004 \u0005[ממשמש\u0006 הוא \u0005בהם\u0006 בכל עת\u0005]\u0006 ומגלה את אבידתו קרוב לזמן האבידה. \u0003ו\u0004כפי שאמר \u0003ר' יצחק\u0004 לגבי כסף.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא: \u0003המוצא מעות בבתי כנסיות ובבתי מדרשות, ובכל מקום שהרבים מצויין שם\u0004 — \u0003הרי אלו שלו, מפני שהבעלים מתיאשין מהן.\u0004 ויש להקשות: \u0003והא לא ידע דנפל מיניה\u0004 \u0005[והרי לא ידעו\u0006 הבעלים \u0005ש\u0006המעות \u0005נפלו מהם]?\u0006 על כך \u0003אמר ר' יצחק: אדם עשוי למשמש בכיסו בכל שעה,\u0004 ומתברר לו בזמן קצר מאוד שהמעות אבדו ממנו, ומתייאש מיד.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר: \u0003מאימתי כל אדם\u0004 (ולא עניים בלבד) \u0003מותרים בלקט?\u0004 שכל השיבולים שנשארו בשדה לאחר הקציר שייכות לעניים (כמבואר בויקרא יט, ט), וממילא אסורות לכל אדם, ומאימתי מותר לכל ללקט לעצמם את השיבולים הבודדות שנשארו בשדה? \u0003משילכו בה\u0004 בשדה \u0003הנמושות,\u0004 ואחר שאלו הלכו מותר הלקט לכל. \u0003ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 כשעסקנו בבעיה זו לגופה: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003נמושות\u0004 אלה? \u0003ואמר ר' יוחנן: סבי דאזלי אתיגרא\u0004 \u0005[זקנים ההולכים על מקל].\u0006 \u0003ריש לקיש אמר: לקוטי בתר לקוטי\u0004 \u0005[מלקטים אחר מלקטים]\u0006 שהם כבר מחזור שני של עניים. ומכל מקום לאחר שהיו שם הנמושות אין להניח שנשארו שבולים רבות, והעניים כבר התייאשו מן הלקט.","ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 שייך כבר הלקט לכל אדם? \u0003נהי דעניים דהכא מיאשי\u0004 \u0005[אם אמנם שעניים של כאן מתייאשים]\u0006 מן הלקט שבשדה, שהרי ראו שעברו הנמושות, אולם \u0003איכא\u0004 \u0005[יש]\u0006 \u0003עניים בדוכתא אחריתא דלא מיאשי\u0004 \u0005[במקום אחר שאינם מתייאשים]\u0006 שהרי לא נודע להם! משמע שיש יאוש שלא מדעת! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עניים הכא\u0004 \u0005[כאן],\u0006 \u0003הנך מעיקרא איאושי מיאש\u0004 \u0005[אותם\u0006 עניים שבמקומות אחרים \u0005מתחילה מתייאשים]\u0006 מן הלקט שבשדה, \u0003ואמרי\u0004 \u0005ואומרים]:\u0006 \u0003עניים דהתם מלקטי ליה\u0004 \u0005[של שם,\u0006 באותו מקום, \u0005מלקטים אותו]\u0006 ומראש התייאשו מן הלקט שבמקומות אחרים.","\u0003תא שמע\u0004 \u0005[בוא ושמע]:\u0006 היו \u0003קציעות\u0004 (תאנים מיובשות) מצויות \u0003ב\u0004אמצע ה\u0003דרך, ואפילו\u0004 נמצאו \u0003בצד שדה קציעות\u0004 (שדה שבו מייבשים תאנים). \u0003וכן תאנה הנוטה לדרך, ומצא תאנים תחתיה\u0004 — \u0003מותרות\u0004 תאנים אלה \u0003משום גזל,\u0004 שהלוקח אותן הוא כמוצא אבידה ולא כגזלן, \u0003ופטורות מן המעשר,\u0004 שכן הפקר פטור מן המעשר. אולם \u0003בזיתים ובחרובים\u0004 במצבים כגון זה — \u0003אסור\u0004 לו לקחת.","ומעתה, \u0003בשלמא רישא\u0004 \u0005[נניח\u0006 ל\u0005ראשה\u0006 של הברייתא\u0005]\u0006 ש\u0003לאביי לא קשיא\u0004 \u0005[אינו קשה]\u0006 שיכול לתרץ בפשטות כך: לגבי קציעות אפשר לומר \u0003אגב דחשיבי\u0004 \u0005[כיון ש\u0006הן \u0005חשובות]\u0006 — \u0003ממשמש בהו\u0004 \u0005[בודק אותן]\u0006 ואם ראה שחסרו מיד הוא מתייאש. וכן \u0003תאנה נמי\u0004 \u0005[גם כן]\u0006 \u0003מידע ידיע דנתרא\u0004 \u0005[יודע הוא ש\u0006פירותיה \u0005נושרים]\u0006 ומתייאש מהם.","\u0003אלא סיפא\u0004 \u0005[הסוף]\u0006 \u0003לרבא קשיא\u0004 \u0005[קשה],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"בזיתים ובחרובים אסור\",\u0004 משמע: יאוש שלא מדעת אינו נחשב יאוש! \u0003אמר ר' אבהו:\u0004 יש לתרץ, \u0003שאני\u0004 \u0005[שונה]\u0006 ה\u0003זית, הואיל וחזותו\u0004 (מראהו) \u0003מוכיח עליו\u0004 למי הוא שייך, כי לכל עץ זית יש צורת פרי אופיינית, \u0003ואף על גב דנתרין זיתי מידע ידיע, דוכתא דאיניש איניש הוא\u0004 \u0005[ואף על פי שנופלים הזיתים\u0006 לאדמה \u0005ידוע הוא שבמקומו של אדם\u0006 זית זה של \u0005אותו אדם הוא].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שממראה הפרי ניכר היכן הפרי שייך \u0003אפילו רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 בתאנה יהיו התאנים הנושרות שייכות לבעליהן! \u0003אמר רב פפא: תאנה עם נפילתה נמאסת\u0004 (נמעכת ומתלכלכת) ואף אם אפשר להכיר בתאנה שהיא שייכת לעץ זה, אולם בעל הבית מתייאש מן הפירות שבדרך כלל אינם ראויים עוד לאכילה.","ושוב מנסים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003הגנב שנטל מזה\u0004 מאדם אחד \u0003ונתן לזה\u0004 לאחר, \u0003וכן גזלן שנטל מזה ונתן לזה,\u0004"],["\u0003וכן\u0004 נהר ה\u0003ירדן\u0004 או נהר אחר \u0003שנטל מזה ונתן לזה,\u0004 בכל אלה \u0003מה שנטל\u0004 — \u0003נטל, ומה שנתן\u0004 — \u0003נתן,\u0004 וזה שהגיעו הדברים לידיו אינו צריך להחזירם.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גזלן וירדן\u0004 אפשר לומר \u0003דקא חזי להו ומיאש\u0004 \u0005[שהוא רואה אותם\u0006 שנטלו ממנו \u0005ומתייאש],\u0006 ולכן מי שהגיעו הדברים אליו זכה בהם, שהרי הם לאחר יאוש. \u0003אלא גנב, מי קא חזי ליה דמיאש\u0004 \u0005[האם הוא רואה אותו ש\u0006הוא \u0005מתייאש]?\u0006 הרי גנב עושה מעשיו בסתר, ושמא אין הבעלים יודעים שהחפץ נגנב, ויתכן שלא יתייאשו עד לאחר זמן, ובכל זאת אומרים אנו שהדבר מותר מיד למקבלו. \u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב פפא\u0004 שכאן לא מדובר בגנב רגיל אלא \u0003בלסטים\u0004 (גנב) \u0003מזוין\u0004 הנוטל בחוזקה ובגלוי, אבל לאחר שלקח הוא מסתתר ובורח מן הבריות ואינו ידוע לכל כגזלן אחר. ומקשים: \u0003אי הכי היינו\u0004 \u0005[אם כך הרי הוא]\u0006 \u0003גזלן\u0004 ומה ההבדל בינו ובין גזלן שנזכר תחילה? ומסבירים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003גזלן\u0004 שנה, אבל בעיקרו של דבר בשניהם היתה הנטילה בידיעת הבעלים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003שטף נהר קוריו\u0004 (קורותיו) של אדם או את \u0003אבניו, ונתנו בתוך שדה חבירו\u0004 — \u0003הרי אלו שלו,\u0004 של בעל השדה, \u0003מפני שנתיאשו הבעלים.\u0004 ונדייק מלשון הברייתא: \u0003טעמא\u0004 \u0005[הטעם, דוקא]\u0006 ש\u0003נתיישו הבעלים, הא סתמא\u0004 \u0005[הרי\u0006 אם היה הדבר \u0005סתם]\u0006 — \u0003לא,\u0004 ומשמע מכאן שאין יאוש אלא מדעת! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כשיכול\u0004 בעל החפצים \u0003להציל\u0004 ולא הציל, והרי זה כהפקר ברור.","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור את סופה\u0006 של הברייתא\u0005]:\u0006 \u0003אם היו הבעלים מרדפין אחריהם\u0004 אחר הדברים שאיבדו — \u0003חייב להחזיר.\u0004 ומעתה: \u0003אי\u0004 \u0005[אם]\u0006 מדובר פה \u0003ביכולין להציל\u0004 — \u0003מאי אריא\u0004 \u0005[מדוע דווקא]\u0006 ב\u0003מרדפין?\u0004 \u0003אפילו\u0004 כש\u0003אין מרדפין נמי\u0004 \u0005[גם כן]\u0006 לא יצאו החפצים מבעלותם שלהם, שהרי לא התייאשו מהם! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — שהיו הבעלים \u0003יכולין להציל על ידי הדחק,\u0004 במאמץ ובקושי. ולכן, אם \u0003מרדפין\u0004 הם אחר חפציהם, הרי זה מוכיח כי \u0003לא אייאוש\u0004 \u0005[התייאשו]\u0006 מהם, אם \u0003אין מרדפין\u0004 אחריהן — ודאי ש\u0003אייאושי מיאש\u0004 \u0005[התייאשו].\u0006","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מתחום שונה. \u0003כיצד אמרו\u0004 דין זה ש\u0003התורם תרומה\u0004 לכהן מן התבואה \u0003שלא מדעת\u0004 הבעלים בכל זאת \u0003תרומתו תרומה?\u0004 — \u0003הרי שירד לתוך שדה חבירו וליקט\u0004 מן הפירות לצורך בעל הבית \u0003ו\u0004אף \u0003תרם\u0004 תרומה לכהן \u0003שלא ברשות, אם\u0004 בעל הבית \u0003חושש\u0004 שהיה במעשה זה של החבר \u0003משום גזל\u0004 — \u0003אין תרומתו תרומה,\u0004 שהרי הדבר נעשה בניגוד לרצון בעל הבית, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003תרומתו תרומה.\u0004","\u0003ומנין הוא\u0004 התורם \u0003יודע אם חושש\u0004 בעל הבית \u0003משום גזל ואם לאו\u0004 \u0005[לא]?\u0006 דוגמא לכך, \u0003הרי שבא בעל הבית ומצאו\u0004 שהוא תורם מן השדה, \u0003ואמר לו: \"כלך\u0004 \u0005[לך]\u0006 \u0003אצל יפות\"\u0004 כלומר, צריך היית לבחור לשם תרומה יפות יותר. ואז, \u0003אם\u0004 אכן \u0003נמצאו יפות מהן\u0004 בשדה — הרי זו הוכחה שבעל הבית מרוצה במעשה זה, וכיון שנמצא שבעל הבית הסכים בדיעבד לאחר מעשה לתרומה זו — \u0003תרומתו תרומה, ואם לאו\u0004 \u0005[לא],\u0006 שלא נמצאו יפות מהן, משמע שכעס בעל הבית עליו ורק בלעג אמר לו \"כלך אצל יפות\", וממילא מובן שלא הסכים לתרומה מעיקרה, ולכן \u0003אין תרומתו תרומה.\u0004 ואולם אם \u0003ליקטו הבעלים והוסיפו עליהן\u0004 על פירות שתרם אותו אדם \u0003בין כך ובין כך\u0004 — בין שאמר לו ונמצאו יפות מהו, בין שלא נמצאו — \u0003תרומתו תרומה,\u0004 שהרי הוספה זו על התרומה ראיה היא שהסכימו הבעלים למעשה.","ומעתה נברר את הרעיון: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003נמצאו יפות מהן תרומתו תרומה,\u0004 אולם \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא כן? הלא \u0003בעידנא\u0004 \u0005[בזמן]\u0006 ש\u0003תרם הא\u0004 \u0005[הרי]\u0006 \u0003לא הוה ידע\u0004 \u0005[ידע]\u0006 שהבעלים יסכימו בעתיד, ואם כן, מכאן נובע כי דבר המתברר לאחר מעשה כאילו היה ברור כבר בשעת מעשה, וקשה איפוא לאביי! \u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רבא\u0004 את הברייתא הזו \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003אביי\u0004 באופן זה: שמדובר כאן באופן \u0003דשויה\u0004 \u0005[שמינה]\u0006 מתחילה את האיש הזה ל\u0003שליח,\u0004 והספק היה רק לאיזה שיעור נתכוונו הבעלים לתרום.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש את הברייתא גם ללא הקושיה על אביי, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003לא שוויה\u0004 \u0005[שאם עולה על דעתך לומר שלא מינה אותו]\u0006 \u0003שליח\u0004 כלל, \u0003מי הויא\u0004 \u0005[האם תהיה]\u0006 \u0003תרומתו תרומה? והא\u0004 \u0005[והרי]\u0006 בפסוק שממנו למדים אנו שאפשר להפריש תרומה על ידי שליח \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \"כן תרימו \u0003גם אתם\u0004 תרומת ה'...\" (במדבר יח, כח), גם בא \u0003לרבות\u0004 (להוסיף) \u0003שלוחכם.\u0004 ומכאן נלמד: \u0003מה אתם\u0004 נותנים תרומה \u0003לדעתכם\u0004 ומרצונכם, \u0003אף שלוחכם\u0004 \u0003לדעתכם.\u0004 ואם כן שליח שלא מדעת אינו יכול להפריש תרומה.","\u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דשויה\u0004 \u0005[שמינה אותו]\u0006 בעל הבית לאדם זה כ\u0003שליח\u0004 לתרומה עבורו. \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003תרום\u0004 עבורי, ואולם \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003תרום מהני\u0004 \u0005[מ\u0006פירות \u0005אלה]\u0006 או מתבואה זו דווקא. \u0003וסתמיה\u0004 \u0005[וסתם]\u0006 \u0003בעל הבית כי תרום\u0004 \u0005[כאשר\u0006 הוא \u0005תורם]\u0006 — \u0003מ\u0004התבואה ה\u0003בינונית הוא תרום\u0004 \u0005[תורם],\u0006 לא יפה מדי ולא גרועה מדי, \u0003ואזל איהו\u0004 \u0005[והלך הוא,\u0006 השליח\u0005]\u0006 \u0003ותרם מיפות. ו\u0004אז, אם \u0003בא בעל הבית ומצאו ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"כלך אצל יפות\u0004 מאלו \u0003\",\u0004 \u0003אם נמצאו יפות מהן\u0004 — \u0003תרומתו תרומה\u0004 שרואים שבעל הבית מתחילה נתכוין לתת בעין יפה, \u0003ואם לאו\u0004 \u0005[לא]\u0006 שאין יפות מהן, נמצא שבעל הבית לא הסכים בלבו, ולכן \u0003אין תרומתו תרומה.\u0004","אגב הלכה זו מסופר: \u0003אמימר ומר זוטרא ורב אשי אקלעו לבוסתנא\u0004 \u0005[הזדמנו לגן הפירות]\u0006 של \u0003מרי בר איסק, אייתי אריסיה תמרי ורימוני ושדא קמייהו\u0004 \u0005[הביא אריסו\u0006 של מרי בר איסק \u0005תמרים ורימונים והניח לפניהם].\u0006 \u0003אמימר ורב אשי אכלי\u0004 \u0005[אכלו]\u0006 מן הפירות, \u0003מר זוטרא לא אכיל\u0004 \u0005[אכל],\u0006 שחשש שמא אין הדבר לדעתו של בעל השדה, ויש בכך משום ספק גזל. \u0003אדהכי אתא\u0004 \u0005[בינתיים בא]\u0006 \u0003מרי בר איסק\u0004 בעל השדה, \u0003אשכחינהו\u0004 \u0005[מצא אותם\u0006 אוכלים\u0005],\u0006 \u0003ואמר ליה לאריסיה\u0004 \u0005[לו לאריסו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אייתית להו לרבנן מהנך שפירתא\u0004 \u0005[הבאת להם לחכמים מאותם הפירות המשובחים]?\u0006","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003אמימר ורב אשי למר זוטרא: השתא אמאי לא אכיל מר\u0004 \u0005[עכשיו מדוע אין אדוני אוכל]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003אם נמצאו יפות מהן\u0004 — \u0003תרומתו תרומה,\u0004 שדבר זה הוא הוכחה שבעל הבית הסכים למעשה השליח, ואף כאן הרי רואים שבעל הבית הסכים למה שעשה אריסו! \u0003אמר להו\u0004 \u0005[להם],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא: לא אמרו\u0004 שכאשר אמר בעל הבית \u0003\"כלך אצל יפות\"\u0004 תהא זו הוכחה שאכן התכוון למתנה בעין יפה, \u0003אלא לענין תרומה בלבד,\u0004 והטעם — \u0003משום\u0004 ש\u0003מצוה הוא ו\u0004אנו סבורים כי \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 בעשייתה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במתנה כגון זו — \u0003משום כסיפותא\u0004 \u0005[בושה]\u0006 \u0003הוא\u0004 ש\u0003אמר הכי\u0004 \u0005[כך]\u0006 שהתבייש מפני החכמים, אבל באמת לא רצה בכך.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ליאוש שלא מדעת. בתורה (ויקרא יא, לז–לח) נאמר כי פרי וזרע איננו נטמא (גם אם נגע בו דבר טמא) אלא אם כן ניתנו מים על זרעים אלה, ונתינה זו — דוקא כשהוא מרצון בעל הפירות. טל דינו לענין זה כמים, ושנינו בברייתא: אם \u0003עודהו הטל עליהן\u0004 שמצא את הפירות בעוד הטל עליהם \u0003ושמח\u0004 על הטל הזה, לפי שלחלח את הפירות ושמרם טריים, \u0003הרי זה ב\"\u0004 ו\u0003כי יתן\", ש\u0004נעשים פירות אלה \"מוכשרים לקבל טומאה\", משום שנתקיים בהם האמור בכתוב \"כי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (ויקרא יא, לח). \u0003נגבו\u0004 כלומר, התייבשו הפירות מן הסל, כאשר מצא אותם, \u0003אף על פי ששמח\u0004 על הטל שירד עליהם קודם לכן,"],["\u0003אינן ב\u0004גדר של \u0003\"כי יתן\",\u0004 ואינן מקבלות טומאה.","ומעתה נברר: \u0003טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 של הלכה זו? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דלא אמרינן\u0004 \u0005[שאין אנו אומרים]\u0006 \u0003כיון דאיגלאי מילתא דהשתא ניחא ליה\u0004 \u0005[שנתגלה הדבר שעכשיו נוח לו],\u0006 \u0003מעיקרא נמי ניחא ליה\u0004 \u0005[מתחילה גם כן נוח לו],\u0006 שהרי אין הסכמתו והנאתו מועילות לאחר מעשה לענין פירות שנרטבו ויבשו, ולכאורה כן יהא גם בענין יאוש שלא מדעת, וקשה לרבא! ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בהלכות הכשרה לטומאה, \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 בתורה לא \"כי יותן\" בכתיב מלא, אלא בכתיב חסר \u0003\"כי יתן\",\u0004 ללמדנו שאין טומאה חלה \u0003עד שיתן\u0004 האדם את המים על הפירות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 לא יחשב הדבר כהכשר לטומאה שהרי לא נתן את הטל בעצמו! ומסבירים: \u0003התם\u0004 \u0005[שם]\u0006 יש להבין את כל הנושא \u0003כ\u0004דברי \u0003רב פפא.\u0004 ש\u0003רב פפא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[כתוב]\u0006 בתורה \u0003\"כי יתן\"\u0004 ומשמעו שהאדם עצמו יתן בידים, \u0003וקרינן\u0004 \u0005[ואנו קוראים]\u0006 את הפסוק לפי הניקוד המקובל \u0003\"כי יתן\",\u0004 משמע: יותן מעצמו, ללא מעשה ידי אדם! \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מיישבים אנו את הקרי והכתיב?","— אנו יוצרים כעין פשרה, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 ש\u0003\"כי יתן\"\u0004 יהא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"כי יתן\". מה \"יתן\"\u0004 פירושו נתינה \u0003לדעת, אף \"כי יתן\" נמי\u0004 \u0005[גם כן]\u0006 \u0003לדעת\u0004 הבעלים. ומשום כך מסקנת ההלכה היא שמים שנפלו מעצמם על הזרעים מכשירים לטומאה רק אם היו הבעלים בשעת נפילת המים, והיה הדבר לרצון הבעלים. ואם כן, מכאן אין להוכיח לענייננו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל בן יהוצדק: מנין לאבידה ששטפה נהר שהיא מותרת\u0004 לכל מוצא? — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה: \u0003\"וכן תעשה לחמרו וכן תעשה לשמלתו וכן תעשה לכל אבידת אחיך אשר תאבד ממנו ומצאתה\"\u0004 (דברים כב, ג), ומכאן למדו: \u0003מי שאבודה הימנו\u0004 (ממנו) \u0003ומצויה אצל כל אדם,\u0004 ואבידה כזו נחשבת להפקר, ולכן כל המוצא זכה בה. \u0003יצאתה זו שאבודה ממנו ואינה מצויה אצל כל אדם.\u0004","ומהלכה זו נמשיך ונדייק: לענין עיקר ההלכה \u0003ואיסורא דומיא דהיתירא\u0004 \u0005[ואיסור דומה להיתר],\u0006 \u0003מה היתירא\u0004 \u0005[\u0006אבידת \u0005היתר]\u0006 כלומר, במציאה המותרת לכל, שמדין התורה מותר לקחתה, קיים דין זה ו\u0003בין דאית\u0004 \u0005[שיש]\u0006 \u0003בה סימן בין דלית\u0004 \u0005[שאין]\u0006 \u0003בה סימן\u0004 — \u0003שרא\u0004 \u0005[מותרת],\u0006 \u0003אף איסורא\u0004 \u0005[\u0006אבידה \u0005אסורה],\u0006 כלומר, אותה שאסור לכל אדם לקחתה לעצמה אין לחלק בה ו\u0003בין דאית\u0004 \u0005[שיש]\u0006 \u0003בה סימן בין דלית\u0004 \u0005[שאין]\u0006 \u0003בה סימן\u0004 — \u0003אסורה,\u0004 עד שיוכח שאכן התייאשו הבעלים. ומכאן \u0003תיובתא\u0004 \u0005[הרי זו קושיה חמורה]\u0006 לדברי \u0003רבא!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה היא]\u0006 והושבו ונדחו דבריו, ואין הלכה כמותו.","\u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003אביי ב\u0004שש הלכות אלה שסימנן הוא \u0003יע\"ל קג\"ם\u0004 (\u0003י\u0004אוש, \u0003ע\u0004ד זומם, \u0003ל\u0004חי העומד מאליו, \u0003ק\u0004דושין שלא נמסרו לביאה, \u0003ג\u0004לוי דעת בגט, \u0003מ\u0004ומר להכעיס).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: וכי מאחר דאיתותב\u0004 \u0005[שהושבו ונדחו]\u0006 דברי \u0003רבא,\u0004 ויאוש שלא מדעת — אסור, אם כן \u0003הני תמרי דזיקא היכי אכלינן להו\u0004 \u0005[אותם תמרים ש\u0006משירה \u0005הרוח\u0006 מן הדקל \u0005איך אוכלים אנו אותם]\u0006 מיד, ואין חוששים שמא בעל התמרים לא התייאש מהם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיון\u0004 שהכל יודעים \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שקצים ורמשים דקא אכלי להו\u0004 \u0005[שאוכלים אותם],\u0006 \u0003מעיקרא יאושי מיאש מנייהו\u0004 \u0005[מתחילה מתייאש מהם]\u0006 בעל התמרים, ולכן כל המוצא זוכה.","ושואלים: ואם היה זה דקל של \u0003יתמי דלאו\u0004 \u0005[יתומים שלא]\u0006 \u0003בני מחילה נינהו\u0004 \u0005[הם],\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 הדין? שהרי יתומים קטנים שאין בהם דעת אינם יכולים למחול על המגיע להם, ולכן אין לומר שהתייאשו מתחילה, וכיצד יכולים אנו לאכול מן הפירות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003באגא בארעא דיתמי לא מחזקינן\u0004 \u0005[בקעה,\u0006 מישור שלם, \u0005אין אנו מניחים]\u0006 שהוא בחזקת אדמת יתומים, ואין צורך לחשוש לכך.","שאל אותו עוד: ואם היה השדה \u0003מוחזק ועומד\u0004 שהוא של יתומים, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? וכן \u0003כרכתא\u0004 \u0005[גדרות]\u0006 אם היו מסביב לדקלים שאין השקצים והרמשים יכולים להכנס בהם, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: אכן, במקרים כאלה \u0003אסירן\u0004 \u0005[אסורים]\u0006 התמרים שנשרו.","שנינו במשנה שאם מצא \u0003כריכות\u0004 (עומרים, אלומות) \u0003ברשות הרבים\u0004 — \u0003הרי אלו שלו. אמר רבה: ואפילו בדבר שיש בו סימן,\u0004 שגם אם היו העומרים קשורים באופן מיוחד, או בדבר שיש בו סימן הרי אלו של המוצא. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003רבה\u0004 כי \u0003סימן העשוי לידרס\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן,\u0004 כלומר, המאבד יודע כי סימן זה ידרס ברגלים ויישחת, ולכן איננו סומך עליו ומתייאש מן האבידה. \u0003רבא אמר: לא שנו אלא בדבר שאין בו סימן, אבל בדבר שיש בו סימן\u0004 — \u0003חייב להכריז.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 \u0003רבא\u0004 \u0003סימן העשוי לידרס\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן.\u0004","ומעירים: \u0003ואיכא דמתני להא שמעתא באנפי נפשה\u0004 \u0005[ויש ששונים הלכה זו בפני עצמה],\u0006 לא כמחלוקת בפירוש המשנה אלא כמחלוקת לעצמה: \u0003סימן העשוי לידרס, רבה אמר: לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ורבא אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו]\u0005:\u0006 שאם מצא \u0003כריכות ברשות הרבים\u0004 — \u0003הרי אלו שלו,\u0004 מצא אותו \u0003ברשות היחיד\u0004 — \u0003נוטל ומכריז.\u0004 ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דלית בהו\u0004 \u0005[אם בכריכות שאין בהן]\u0006 \u0003סימן,\u0004 אם כן \u0003ברשות היחיד מאי\u0004 \u0005[על מה]\u0006 הוא \u0003מכריז?\u0004 הלא המאבד לא יוכל לתת בהם סימן! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דאית בהו\u0004 \u0005[שיש בהן]\u0006 \u0003סימן, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003ברשות הרבים\u0004 — \u0003הרי אלו שלו. אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003סימן העשוי לידרס לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רבא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא: לעולם\u0004 תפרש \u0003דלית בהו\u0004 \u0005[שאין בהן]\u0006 \u0003סימן, ודקא אמרת\u0004 \u0005[ושאמרת]\u0006 \u0003ברשות היחיד מאי\u0004 \u0005[מה]\u0006 \u0003מכריז?\u0004 אין זה קושי כי \u0003מכריז מקום,\u0004 שמכריז שמצא אבידה במקום מסויים, אבל אינו אומר מה מצא, ואם הכריכות אכן הונחו שם מדעת, יאמר המאבד: כריכות היו לי באותו מקום. ומעירים: \u0003ורבה אמר\u0004 בכלל: \u0003מקום לא הוי\u0004 \u0005[איננו]\u0006 \u0003סימן.\u0004 שאם אמר אדם שבמקום מסויים איבד דבר מה אין זה סימן מספיק להשיב לו את החפץ. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שבנושא זה עצמן נחלקו אותם אמוראים. \u0003מקום, רבה אמר: לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ורבא אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן.\u0004 ונמצא ששיטות רבה ורבא בשתי המחלוקות קשורות זו בזו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: מצא \u0003כריכות ברשות הרבים\u0004 — \u0003הרי אלו שלו, ברשות היחיד\u0004 — \u0003נוטל ומכריז. והאלומות,\u0004 שהן עומרים גדולים, \u0003בין ברשות הרבים בין ברשות היחיד\u0004 — \u0003נוטל ומכריז.\u0004 ושואלים: \u0003רבה היכי מתרץ לה\u0004 \u0005[איך\u0006 הוא \u0005מיישב אותה]\u0006 את הברייתא הזו לשיטתו, \u0003ורבא היכי מתרץ לה\u0004 \u0005[איך\u0006 הוא \u0005מיישב אותה]?\u0006 ומסבירים: \u0003רבה מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שמדובר \u0003ב\u0004כריכות ואלומות שיש בהן \u0003סימן, ורבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שהסימן הוא \u0003במקום\u0004 המציאה עצמו.","ומפרטים: \u0003רבה מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003בסימן,\u0004 וכך הוא מפרש: \u0003כריכות ברשות הרבים\u0004 — \u0003הרי אלו שלו, משום\u0004"],["\u0003דמדרסא\u0004 \u0005[שנדרסת],\u0006 ולכן גם אם היה בה סימן הרי הוא נופל, ואילו \u0003ברשות היחיד נוטל ומכריז\u0004 כיון \u0003דלא מדרסא\u0004 \u0005[שאינה נדרסת],\u0006 שאין הרבים מצויים שם ולכן אפשר להכריז עליה לפי הסימן. \u0003והאלומות, בין ברשות היחיד בין ברשות הרבים\u0004 — \u0003נוטל ומכריז, כיון דגביהן\u0004 \u0005[שהן גבוהות]\u0006 \u0003לא מדרסא\u0004 \u0005[אינה נדרסת],\u0006 והסימן נשאר במקומו.","\u0003ורבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003במקום: כריכות ברשות הרבים הרי אלו שלו\u0004 — \u0003דמינשתפא\u0004 \u0005[שהכריכה מתגלגלת]\u0006 על ידי העוברים והשבים, ולכן אין טעם להכריז אף על המקום, שהרי נתגלגלו ממקומן. \u0003ברשות היחיד חייב להכריז\u0004 — \u0003דלא מינשתפא\u0004 \u0005[שאינה מתגלגלת],\u0006 \u0003והאלומות, בין ברשות הרבים בין ברשות היחיד נוטל ומכריז\u0004 — \u0003כיון דיקירי לא מינשתפא\u0004 \u0005[כיון שהן כבדות אינן מתגלגלות].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיות לדבר, ששנינו במשנתנו: \u0003ככרות של נחתום\u0004 — \u0003הרי אלו שלו.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו כיכרות \u0003של בעל הבית\u0004 שאנשים עושים לעצמם, שלא כמעשה חרושת — \u0003חייב להכריז. של בעל הבית מאי טעמא\u0004 \u0005[מה טעם]\u0006 צריך להכריז? \u0003כיון דאית בהו\u0004 \u0005[שיש בהם]\u0006 \u0003סימן, דמידע ידיע רפתא דאיניש איניש הוא\u0004 \u0005[שידוע שלחמו של אדם\u0006 של אותו \u0005אדם הוא],\u0006 שכל אחד מעצב את הלחם בצורה שונה במקצת. אבל \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 הדין אם היה זה ב\u0003רשות הרבים,\u0004 \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 ב\u0003רשות היחיד\u0004 — ש\u0003נוטל ומכריז, אלמא\u0004 \u0005[מכאן כי]\u0006 \u0003סימן העשוי לידרס הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן,\u0004 ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ל\u0003רבה!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רבה: התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 — \u0003משום\u0004 ש\u0003אין מעבירין על האוכלין,\u0004 שהלכה היא שלא יעברו אנשים וידרסו דבר מאכל, אלא מגביהים אותו משום כבוד המאכלים. ושואלים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003גוים\u0004 שאינם חוששים לכך, והם עשויים לדרוס! ומשיבים: \u0003גוים חיישי\u0004 \u0005[חוששים]\u0006 \u0003לכשפים,\u0004 שהיו מאמינים שהונחו המאכלים שם לצורך כישוף, ולכן נזהרים מלדרוך עליהם. ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003בהמה וכלבים\u0004 הדורסים את הכיכרות! ומשיבים: מדובר כאן \u0003באתרא דלא שכיחי\u0004 \u0005[במקום שאין מצויים]\u0006 \u0003בהמה וכלבים.\u0004","ומנסים להציע: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי מחלוקת רבה ורבא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 קדומה היא בנושא זה עצמו, שכן שנינו במשנתנו: \u0003ר' יהודה אומר: כל דבר שיש בו שינוי\u0004 — \u0003חייב להכריז, כיצד? מצא עיגול\u0004 דבילה \u0003ובתוכו חרס, ככר\u0004 לחם \u0003ובתוכו מעות.\u0004 ונדייק: \u0003מכלל\u0004 הדברים נלמד שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 שגם אם מצא דבר כזה \u0003הרי אלו שלו.\u0004","וכדי להבהיר את הקשר לענייננו מסבירים: \u0003סברוה\u0004 \u0005[סברו,\u0006 הניחו\u0005]\u0006 החכמים בבית המדרש הנחות יסודיות אלה: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימן הבא מאיליו,\u0004 כלומר, סימן שעלול להיות בחפץ לאו דווקא מפני שנתנוהו שם, אלא אף עלול ליפול שם במקרה, בכל זאת \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן.\u0004 וכן סברו: מותר להיות \u0003מעבירין על האוכלין\u0004 בלא להרים אותם. ומעתה \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נבין כי התנאים במשנה \u0003בסימן העשוי לידרס קא מיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן!\u0004","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: אי סלקא דעתך דקא סבר תנא קמא\u0004 \u0005[אם עולה על דעתך שסובר התנא הראשון]\u0006 כי \u0003סימן העשוי לידרס לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ומעבירין על האוכלין,\u0004 אם כן על \u0003ככרות של בעל הבית\u0004 שנמצאו \u0003ברשות הרבים אמאי\u0004 \u0005[מדוע]\u0006 \u0003מכריז?\u0004 הלא נדרסות הכיכרות ובטל הסימן שבהן! ולכן ברור שההנחה היסודית לא היתה נכונה.","\u0003אלא,\u0004 יש להסביר באופן אחר, \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: דכולי עלמא סברי\u0004 \u0005[הכל סבורים]\u0006 כי \u0003סימן העשוי לידרס\u0004 — \u0003הוי\u0004 \u0005[הריהו נחשב]\u0006 \u0003סימן,\u0004 אף כי אפשר לומר כי \u0003מעבירין על האוכלין. ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004בעיה של \u0003סימן הבא מאיליו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003סימן הבא מאליו לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן,\u0004 כיון שיתכן שנפל בחפץ במקרה, ואף בעליו של החפץ אינו יודע של כך. \u0003ו\u0004אילו \u0003ר' יהודה סבר: הוי\u0004 \u0005[הריהו נחשב]\u0006 \u0003סימן. ו\u0004אילו","\u0003רבה אמר\u0004 יכול היה \u0005לומר\u0006 \u0003לך\u0004 ולהסביר את המחלוקת כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימן העשוי לידרס\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן\u0004 אם \u0003אין מעבירין על האוכלין. והכא\u0004 \u0005[וכאן]\u0006 \u0003בסימן הבא מאיליו קא מיפלגי\u0004 \u0005[חלוקים הם];\u0006 ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ור' יהודה סבר: הוי\u0004 \u0005[הריהו נחשב]\u0006 \u0003סימן.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 וגורסים סוגיה זו בנוסח שונה: \u0003סברוה\u0004 \u0005[סברו]\u0006 החכמים מתחילה \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימן הבא מאליו\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן, וסימן העשוי לידרס\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן.\u0004 על כן הסיקו: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003ב\u0004שאלה האם \u0003מעבירין על האוכלין קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דמר\u0004 \u0003סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר \u0005סבור]:\u0006 \u0003מעבירין\u0004 על האוכלים, ולכן נדרס הסימן. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה \u0005סבור]:\u0006 \u0003אין מעבירין\u0004 על האוכלים וכיון שנשאר הסימן — יש מקום להכריז!","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: אי סלקא דעתך סבר תנא קמא\u0004 \u0005[אם עולה על דעתך\u0006 לומר ש\u0005סבור התנא הראשון]\u0006 כי \u0003סימן העשוי לידרס לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ומעבירין על האוכלין\u0004 — אם כן \u0003ככרות של בעל הבית ברשות הרבים אמאי\u0004 \u0005[מדוע]\u0006 \u0003מכריז?\u0004 שהרי לפי הסבר זה ודאי עשוי סימן זה להידרס, ואין עוד סימן היכר, ואין איפוא מקום להכרזה!","\u0003אלא\u0004 \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 יש להבין לפי הנחה יסודית שונה, \u0003דכולי עלמא סברי\u0004 \u0005[שהכל סבורים]\u0006 כי \u0003סימן העשוי לידרס\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן, ומעבירין על האוכלין. והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004ענין \u0003סימן הבא מאיליו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003סימן הבא מאליו\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ור' יהודה סבר: הוי\u0004 \u0005[הריהו נחשב]\u0006 \u0003סימן.\u0004 כך הסביר רב זביד על פי שיטתו של רבא.","\u0003ורבה אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ולהסביר את המחלוקת כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימן העשוי לידרס\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן,\u0004 כשיטתו, \u0003ואין מעבירין על האוכלין. והכא\u0004 \u0005[וכאן]\u0006 \u0003בסימן הבא מאיליו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003סימן הבא מאיליו\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן, ור' יהודה סבר: הוי\u0004 \u0005[הריהו נחשב]\u0006 \u0003סימן.\u0004","כיון שהזכרנו את מה ש\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 מביאים עוד דברים שאמר בשם רבו לסיכום הדברים הלכה למעשה: \u0003כללא דאבידתא\u0004 \u0005[כלל בדיני אבידה]\u0006 \u0003כיון\u0004 ש\u0003אמר\u0004 המאבד \u0003\"ווי לה\u0004 (אוי) \u0003לחסרון כיס\",\u0004 כלומר, חבל על האבידה, המשמעות המעשית של דבר זה להלכה הוא כי \u0003מיאש ליה מינה\u0004 \u0005[התייאש ממנה,\u0006 מן האבידה\u0005].\u0006","\u0003ו\u0004עוד \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003כריכות\u0004 שמצא \u0003ברשות הרבים\u0004 — \u0003הרי אלו שלו. ברשות היחיד, אי\u0004 \u0005[אם]\u0006 מצא אותם \u0003דרך נפילה,\u0004 שלפי האופן בו מונחות נראה שנפלו מן המאבד — \u0003הרי אלו שלו, אי\u0004 \u0005[אם]\u0006 ב\u0003דרך הנחה\u0004 שנראה שלא נפלו אלא הונחו במקום בכוונה על ידי בעליהן — \u0003נוטל ומכריז. וזה וזה\u0004 אמרו \u0003בדבר שאין בו סימן, אבל בדבר שיש בו סימן\u0004 — \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003ברשות הרבים, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003ברשות היחיד, בין\u0004 שהיה זה ב\u0003דרך נפילה ובין דרך הנחה\u0004 — \u0003חייב להכריז,\u0004 שכיון שהמאבד יודע שיש לו סימן בכריכות אינו מתייאש מהן."],["שנינו במשנה שהמוצא \u0003מחרוזות של דגים\u0004 הרי אלו שלו. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003להוי\u0004 \u0005[שיהא]\u0006 ה\u0003קשר\u0004 עצמו בו נקשרו הדגים \u0003סימן!\u0004 ומשיבים: מדובר \u0003בקטרא דציידא, דכולי עלמא הכי מקטרי\u0004 \u0005[בקשר ציידים, שהכל קושרים כך]\u0006 את דגיהם, ואין איפוא סימן בקשר עצמו. ושואלים: \u0003ולהוי\u0004 \u0005[ושיהיה]\u0006 \u0003מנין\u0004 (מספר) הדגים במחרוזת \u0003סימן!\u0004 ומשיבים: \u0003במנינא דשוין\u0004 \u0005[במנין השווה],\u0006 כלומר, שיש באותו מקום מנין מסויים לדגים במחרוזות, ולכן אין מנין זה מהווה סימן.","מסופר, \u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב ששת:\u0004 האם \u0003מנין,\u0004 כלומר, דברים שאין בהם כשלעצמם סימן אבל היו אחדים מהם יחד, \u0003הוי\u0004 \u0005[הריהם]\u0006 \u0003סימן או לא הוי\u0004 \u0005[אינם נחשבים]\u0006 \u0003סימן? אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 כלומר, יש ברייתא ידועה שממנה ניתן ללמוד פתרון לשאלה זו, ששנינו: \u0003מצא כלי כסף וכלי נחושת, גסטרון\u0004 (חתיכות) של \u0003אבר\u0004 (עופרת), \u0003וכל כלי מתכות\u0004 — \u0003הרי זה לא יחזיר\u0004 לבעלים \u0003עד שיתן\u0004 בעל החפץ \u0003אות\u0004 (סימן) שהיה בו, \u0003או עד שיכוין משקלותיו\u0004 שיאמר בדיוק מה משקל כל כלי. ומכאן מסיק רב ששת: \u0003ומדמשקל הוי\u0004 \u0005[ומכיון שמשקל הריהו]\u0006 \u0003סימן\u0004 — \u0003מדה ומנין נמי הוי\u0004 \u0005[גם כן הריהם]\u0006 \u0003סימן,\u0004 אף שאין סימן בגוף החפץ.","שנינו במשנה שאם נמצאו \u0003חתיכות של בשר\u0004 הרי הן למוצא. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003להוי משקלא\u0004 \u0005[שיהא המשקל]\u0006 \u0003סימן!\u0004 ומשיבים: \u0003במשקלא דשוין\u0004 \u0005[במשקל השווה]\u0006 שבמשקל זה נוהגים הכל לחתוך את הבשר. ושואלים: \u0003ותהוי\u0004 \u0005[ושתהיה]\u0006 \u0003חתיכה גופה\u0004 \u0005[עצמה]\u0006 \u0003סימן,\u0004 שהרי יכול הוא לומר \u0003או דדפקא או דאטמא\u0004 \u0005[אם היא מן הצוואר או מן הירך]!\u0006 \u0003מי לא תניא\u0004 \u0005[האם לא שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצא חתיכות דגים\u0004 או \u0003דג נשוך\u0004 (שזהו סימנו) — \u0003חייב להכריז.\u0004 מצא \u0003חביות של יין,\u0004 או \u0003של שמן\u0004 או \u0003של תבואה\u0004 או \u0003של גרוגרות\u0004 (תאנים מיובשות) או \u0003של זיתים\u0004 — \u0003הרי אלו שלו.\u0004 משמע שחתיכות דגים נחשבות כדבר שיש בו סימן, כיון שיכול להגיד מאיזה חלק הדג הם.","ודוחים: \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא המדברת בחתיכות דגים \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003בדאיכא סימנא בפסקא\u0004 \u0005[כשיש סימן בחיתוך]\u0006 עצמו, שהיו נתחי הדגים חתוכים בצורה מיוחדת, \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003רבה בר רב הונא מחתיך ליה אתלתא קרנתא\u0004 \u0005[היה חותך אותם,\u0006 את חתיכות הבשר \u0005כמשולשים].\u0006 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שבמקרה כזה מדובר בברייתא \u0003דקתני דומיא\u0004 \u0005[ששנה הלכה זו בדומה]\u0006 ל\u0003דג נשוך,\u0004 שסימן מובהק הוא, על כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאף החתיכות מיוחדות היו בחיתוכן.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: אם מצא \u0003חביות של יין ושל שמן ושל תבואה ושל גרוגרות ושל זיתים\u0004 — \u0003הרי אלו שלו.\u0004 ושואלים: \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מצא \u0003כדי יין\u0004 או \u0003כדי שמן\u0004 — \u0003חייב להכריז! אמר ר' זירא אמר רב: מתניתין\u0004 \u0005[משנתנו]\u0006 המחייבת להכריז היא \u0003ברשום\u0004 כלומר, בחבית שהמגופה מחוברת בה, לפי שכל אדם עושה זאת בצורה שונה, ויש איפוא סימן מיוחד בחבית. על הסבר זה מקשים: \u0003מכלל\u0004 \u0005[מכאן]\u0006 שב\u0003ברייתא\u0004 מדובר \u0003ב\u0004חבית \u0003פתוח,\u0004 אולם \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בפתוח\u0004 — הלא \u0003אבידה מדעת היא,\u0004 שחבית יין פתוחה ודאי תחמיץ, ואם כן בדבר כגון זה אין צורך לומר שאין זו נחשבת לאבידה, שהדבר ברור מעצמו. \u0003אמר רב הושעיא:\u0004 מדובר בברייתא \u0003במציף,\u0004 כלומר, שהחבית היתה אמנם מכוסה במגופה, אבל אינה חתומה עוד בטיט.","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 במשנה ובברייתא מדובר \u0003ברשום, ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003כאן\u0004 — במשנה שאמרה שיש להחזיר, הרי זה מדובר \u0003קודם שנפתחו האוצרות,\u0004 כלומר, לפני התקופה שפותחים הכל את מחסני היין שלהם למכרם לרבים, והסימן במגופה מוכיח שהחבית היא של האיש שעשה את הסימן. ו\u0003כאן\u0004 שמותרת החבית למוצא — מדובר \u0003לאחר שנפתחו האוצרות,\u0004 ויתכן שבעל היין הראשון כבר מכר את כדו לאנשים אחרים, והחבית עוברת מיד ליד, ולכן אין עוד משמעות בסימן הרישום. וכעין זה מסופר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב יעקב בר אבא אשכח חביתא דחמרא\u0004 \u0005[מצא חבית יין]\u0006 \u0003לאחר שנפתחו האוצרות, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003אביי\u0004 לשאול מה לעשות בה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקול לנפשך\u0004 \u0005[לך קח\u0006 אותה \u0005לעצמך],\u0006 שאין אתה צריך להכריז על כך.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב ביבי מרב נחמן:\u0004 האם ציון ה\u0003מקום\u0004 בו היה מונח החפץ בשעת המציאה \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן, או לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן? אמר ליה\u0004 \u0005[לו]\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 שהרי שנינו בברייתא: \u0003מצא חביות של יין ושל שמן ושל תבואה ושל גרוגרות ושל זיתים\u0004 — \u0003הרי אלו שלו. ו\u0004מעתה \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 ש\u0003מקום הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן, לכרוז\u0004 \u0005[שיכריז]\u0006 שב\u0003מקום\u0004 מסויים מצא אבידה, והמאבד יאמר מה איבד! \u0003אמר רב זביד\u0004 מכאן אין להוכיח לענייננו, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 כשמצא את אלה \u0003ברקתא דנהרא\u0004 \u0005[בשפת הנהר]\u0006 במקום ששימש לעגינת הספינות המביאות ונוטלות דברים מישוב זה, וכיון שיש שם תמיד הרבה סחורות, הרי אין זה יכול לשמש סימן.","וכן \u0003אמר רב מרי: מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003רקתא דנהרא לא הוי\u0004 \u0005[שפת הנהר אינו נחשב]\u0006 \u0003סימן?\u0004 — \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]\u0006 לטוען: \u0003כי היכי דאתרמי לדידך אתרמי נמי לחברך\u0004 \u0005[כמו שהזדמן לך לאבד נזדמן גם כן לחברך],\u0006 ואם לא נתת סימן באבידה עצמה אין זה סימן שאבדת שם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב מרי\u0004 בנוסח שונה מאד: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003מקום לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן?\u0004 — \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]\u0006 לנותן הסימן הזה: \u0003כי היכי דאתרמי לדידך האי\u0004 \u0005[כפי שנזדמן לך אותו]\u0006 \u0003מקום\u0004 להניח בו, \u0003אתרמי נמי לחברך האי\u0004 \u0005[נזדמן גם לחברך אותו]\u0006 \u0003מקום.\u0004","מסופר: \u0003ההוא גברא דאשכח כופרא בי מעצרתא\u0004 \u0005[אדם אחד שמצא גוש זפת ליד הגת].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקול לנפשך\u0004 \u0005[לד קח לעצמך],\u0006 שהרי אין כל סימן באבידה. \u0003חזייה דהוה קא מחסם\u0004 \u0005[ראהו\u0006 רב את האיש \u0005שהוא מהסס]\u0006 שמא אין לו זכות גמורה בדבר, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל פלוג ליה\u0004 \u0005[לך תן חלק]\u0006 \u0003לחייא ברי מיניה\u0004 \u0005[בני מזה]\u0006 כדי שתרגיש שאני בטוח בהלכה זו, עד שאני מוכן להנות אף את בני ממנה. ושואלים: \u0003לימא קא סבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003רב מקום לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003סימן? אמר ר' אבא:\u0004 לא מטעם זה התיר, אלא \u0003משום יאוש בעלים נגעו בה,\u0004 שטעמו של רב היה משום שהיה בטוח שהיה כבר יאוש בעלים, \u0003דחזא דקדחי ביה חלפי\u0004 \u0005[שראה שכבר צמחו בו עשבים],\u0006 והבין שגוש הזפת היה מונח זמן כה רב שוודאי התייאשו ממנה הבעלים.","שנינו במשנה: \u0003ר' שמעון בן אלעזר אומר\u0004 כל כלי אנפוריא אינו חייב להכריז. ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003אנפוריא? אמר רב יהודה אמר שמואל: כלים חדשים\u0004 שיש להניח \u0003שלא שבעתן העין,\u0004 שעינו של הקונה עדיין לא הספיקה להתבונן בהם כראוי. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי אית בהו\u0004 \u0005[יש בהם]\u0006 \u0003סימן\u0004 ניכר — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא שבעתן העין מאי הוי\u0004 \u0005[מה יהא]\u0006 על ידי כך? הרי יש בהם סימן, ומן הסתם הבחינו בכך הבעלים! \u0003אי דלית בהו\u0004 \u0005[שאין בהם]\u0006 \u0003סימן\u0004 מיוחד בכלל, שהם דומים לכל הכלים היוצאים מבית החרושת — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003שבעתן העין מאי הוי\u0004 \u0005[מה יהא]\u0006 על ידי כך? הלא גם אז אין המאבד יכול לתת בהם סימן!","ומשיבים: \u0003לעולם\u0004 מדובר בכלים \u0003דלית בהו\u0004 \u0005[שאין בהם]\u0006 \u0003סימן,\u0004 וההבדל אם חדשים הם או ישנים יש לו משמעות להלכה — כי \u0003נפקא מינה\u0004 \u0005[יוצא מכאן]\u0006 הבדל הלכה למעשה \u0003לאהדורי\u0004 \u0005[להחזיר]\u0006 כלים כאלה \u0003לצורבא מרבנן\u0004 \u0005[לתלמיד חכם]\u0006 \u0003בטביעות עינא\u0004 \u0005[העין].\u0006 כי אף כלים שאין בהם סימן זיהוי בולט, פעמים רבות ניכרים הם לבעליהם על ידי צירוף תכונות קטנות שקשה להגדירן, ואם בא תלמיד חכם שאנו מאמינים לדבריו גם בלא הוכחה חיצונית, הרי אז אם היו אלה כלים ישנים שכבר \u0003שבעתן העין\u0004 — \u0003קים ליה בגוייהו\u0004 \u0005[מוחזק לו בהם]\u0006 ומכיר אותם בוודאות \u0003ומהדרינן ליה\u0004 \u0005[ומחזירים אנו לו]\u0006 על סמך דיבורו. אבל אם היו חדשים מאד \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא שבעתן העין\u0004 — \u0003לא קים ליה בגוייהו\u0004 \u0005[אינו יכול להיות בטוח בהם],\u0006 \u0003ו\u0004ממילא \u0003לא מהדרינן ליה\u0004 \u0005[אין אנו מחזירים לו]\u0006 כי בכלל יש לשער שתלמיד חכם לא יאמר כל שקר ודבר מרמה. ש\u0003אמר רב יהודה אמר שמואל: בהני תלת מילי עבידי רבנן דמשנו במלייהו\u0004 \u0005[בשלושה דברים אלה\u0006 בלבד \u0005עשויים חכמים לשנות בדבריהם]\u0006 ולא יאמרו אמת. ואלו הם: \u0003במסכת,\u0004 אם שואלים אותו אם למד מסכת מסויימת רשאי לומר משום ענווה שלא למד, אף שבאמת למדה, \u0003ובפוריא\u0004 \u0005[במטה],\u0006 אם שואלים אותו אם שכב על מיטה מסויימת, שמותר לו לומר שלא שכב, שמא יימצא בה דבר מגונה ויגרום בושה לעצמו ללא צורך."],["\u0003ובאושפיזא\u0004 \u0005[ובמלון]\u0006 שרשאי לספר שלא קיבלוהו בפנים יפות כל כך במלון, כדי שלא יבואו הכל להיטפל לאותו אדם ולהתאכסן בביתו. ושאלו: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 הלכה למעשה, ממה שלמדנו שבדברים אלה משנים תלמידי חכמים? \u0003אמר מר זוטרא: לאהדורי ליה אבידתא בטביעות עינא\u0004 \u0005[לענין להחזיר לו אבידה בטביעות העין].\u0006 \u0003אי ידעינן ביה\u0004 \u0005[אם יודעים אנו בו]\u0006 שהוא \u0003לא משני\u0004 \u0005[משנה]\u0006 \u0003אלא בהני תלת\u0004 \u0005[בשלושה אלה]\u0006 — \u0003מהדרינן ליה\u0004 \u0005[מחזירים אנו לו]\u0006 את אבידתו, \u0003ואי משני במילי אחריני\u0004 \u0005[ואם משנה\u0006 גם \u0005בדברים אחרים]\u0006 — \u0003לא מהדרינן ליה\u0004 \u0005[אין אנו מחזירים לו],\u0006 שחוששים שמא שיקר.","בהמשך לדבר זה על הדרישות הגבוהות להתנהגות מוסרית של תלמיד חכם מסופר: \u0003מר זוטרא חסידא\u0004 \u0005[החסיד]\u0006 \u0003אגניב ליה כסא דכספא מאושפיזא\u0004 \u0005[נגנב לו כוס של כסף מבעל בית המלון שלו]\u0006 ולא ידעו מי גנבו. \u0003חזיא לההוא בר בי רב דמשי ידיה ונגיב בגלימא דחבריה\u0004 \u0005[ראה תלמיד אחד שרוחץ את ידיו ומנגב אותן בגלימה של חבירו].\u0006 \u0003אמר\u0004 מר זוטרא: \u0003היינו האי\u0004 \u0005[זהו זה]\u0006 האיש \u0003ש\u0004\u0003לא איכפת ליה אממונא דחבריה\u0004 \u0005[לו מממון חבירו],\u0006 \u0003כפתיה ואודי\u0004 \u0005[כפתו אותו והודה]\u0006 האיש שהוא שגנב את הכוס.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מודה ר' שמעון בן אלעזר בכלים חדשים ש\u0004כבר \u0003שבעתן העין ש\u0004עליהם \u0003חייב להכריז. ואלו הן כלים חדשים שלא שבעתן העין שאינו חייב להכריז, כגון בדי\u0004 (צרורות) של \u0003מחטים, ו\u0004צרורות של \u0003צינוריות\u0004 (מסגרות) \u0003ומחרוזות של קרדומות. כל אלו שאמרו, אימתי\u0004 הם \u0003מותרים? בזמן שמצאן אחד אחד, אבל\u0004 אם \u0003מצאן שנים שנים\u0004 — \u0003חייב להכריז,\u0004 כיון שיש כבר סימן במספר החפצים שאבדו.","ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003בדי?\u0004 ומשיבים: \u0003שוכי\u0004 \u0005[כעין ענפים]\u0006 \u0003ואמאי קרו ליה \u0005[ומדוע קוראים להם]\u0006 \"בדי\"? — דבר דתלו ביה מידי\u0004 \u0005[שתולים בו דברים]\u0006 \u0003\"בד\" קרו ליה\u0004 \u0005[קוראים אותו].\u0006 \u0003כי ההוא דתנן התם\u0004 \u0005[וכמו זו ששנינו במשנה]\u0006 בהלכות לולב: \u0003עלה אחד בבד אחד\u0004 כלומר, בענף אחד.","באותה ברייתא שהבאנו שנינו עוד: \u0003וכן היה ר' שמעון בן אלעזר אומר: המציל מן הארי,\u0004 או \u0003מן הדוב,\u0004 או \u0003מן הנמר,\u0004 או \u0003מן הברדלס,\u0004 או \u0003מן זוטו\u0004 (גאותו) \u0003של ים,\u0004 או \u0003משלוליתו\u0004 (שטפונו) \u0003של נהר,\u0004 וכן \u0003המוצא בסרטיא\u0004 (דרך המלך) או ב\u0003פלטיא\u0004 (כיכר ציבורית) \u0003גדולה,\u0004 או \u0003בכל מקום\u0004 אחר \u0003שהרבים מצויים שם,\u0004 כל אלו — \u0003הרי אלו שלו, מפני שהבעלים מתיאשין מהן.\u0004","בענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם ללומדים]\u0006 שאלה זו: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' שמעון בן אלעזר\u0004 דין זה במוצא במקום שהרבים מצויים שם, האם מדובר דווקא כשהיה זה \u0003ב\u0004מקום שיש שם \u0003רוב גוים, אבל\u0004 אם היה \u0003ב\u0004מקום ששם \u0003רוב ישראל\u0004 — \u0003לא,\u0004 אינו מתייאש, שכן סומך המאבד שיהודים יחזירו לו את האבידה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו ברוב ישראל נמי\u0004 \u0005[גם כן]\u0006 \u0003אמר,\u0004 שכיון שיש שם רבים כבר נתייאש המאבד?","ו\u0003אם תמצא לומר\u0004 כלומר, אם תחליט כי \u0003אפילו ברוב ישראל נמי\u0004 \u0005[גם כן]\u0006 \u0003אמר,\u0004 האם \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו],\u0006 \u0003או לא פליגי\u0004 \u0005[חלוקים\u0006 עליו\u0005]?\u0006","\u0003ואם תמצא לומר פליגי\u0004 \u0005[\u0006ש\u0005חלוקים],\u0006 האם לומר כי \u0003ברוב ישראל ודאי פליגי\u0004 \u0005[הם חולקים],\u0006 אולם עדיין יש לשאול האם גם \u0003ברוב גוים פליגי או לא פליגי\u0004 \u0005[חולקים או אינם חולקים]?\u0006","\u0003ואם תמצא לומר פליגי\u0004 \u0005[חולקים]\u0006 \u0003אפילו ברוב גוים,\u0004 האם \u0003הלכה כמותו או אין הלכה כמותו?\u0004","\u0003אם תמצא לומר\u0004 ש\u0003הלכה כמותו,\u0004 האם זה \u0003דוקא ברוב גוים או אפילו ברוב ישראל?\u0004 והרי כאן שאלות רבות המתבססות זו על זו.","כדי לברר אותן מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003המוצא מעות בבתי כנסיות,\u0004 או \u0003בבתי מדרשות,\u0004 או \u0003בכל מקום שהרבים מצויים שם\u0004 — \u0003הרי אלו שלו, מפני שהבעלים מתיאשין מהן.\u0004 ומעתה נברר: \u0003מאן שמעת ליה דאזיל בתר רובא\u0004 \u0005[מי שמעת אותו שהולך אחר הרוב],\u0006 שסבור שמשגיחים בענין זה של רבים מצויים, הרי \u0003ר' שמעון בן אלעזר\u0004 הוא, ואם כן \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 כי \u0003אפילו ברוב ישראל נמי\u0004 \u0005[גם כן]\u0006 אמר, שהרי מדובר כאן בבתי כנסיות ובתי מדרשות שהם מקומות שרק יהודים מצויים בהם.","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003ב\u0004שמצא כספים \u0003מפוזרין\u0004 שאין בהם סימן, ותוהים על כך: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003במפוזרין מאי אריא\u0004 \u0005[מה שייך, מדוע דווקא]\u0006 אמר ב\u0003מקום שהרבים מצויים שם? אפילו\u0004 במקום ש\u0003אין הרבים מצויין שם\u0004 הרי אלו שלו, שהרי אמרנו שלדעת הכל מעות מפוזרות של המוצא הן!","\u0003אלא\u0004 יש לחזור מתירוץ זה, ו\u0003לעולם\u0004 יש לומר שמדובר \u0003ב\u0004כספים \u0003צרורין, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 — \u0003בבתי כנסיות של גוים,\u0004 שהמונח \"בית כנסת\" כולל גם מקומות כינוס של גוים, ותוהים: \u0003בתי מדרשות מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא ודאי כאן מדובר בדבר מיוחד לישראל! ומשיבים: אפשר לומר \u0003בתי מדרשות דידן\u0004 \u0005[שלנו]\u0006 \u0003דיתבי בהו\u0004 \u0005[שיושבים בהם]\u0006 \u0003גוים,\u0004 כגון שיושבים שם שומרים או שמשים גוים. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 להסביר כך, יכול אתה לפרש גם כן \u0003בתי כנסיות נמי דידן\u0004 \u0005[גם כן שלנו],\u0006 \u0003דיתבי בהו\u0004 \u0005[שיושבים בהם]\u0006 \u0003גוים,\u0004 ועל כל פנים, אין לפתור מכאן את בעייתנו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה: עיר שגוים ויהודים מצויים בה, \u0003מצא בה אבידה, אם רוב ישראל\u0004 שם — \u0003חייב להכריז, אם רוב גוים\u0004 — \u0003אינו חייב להכריז.\u0004 ונדקדק בזה: \u0003מאן שמעת ליה דאמר אזלינן בתר רובא\u0004 \u0005[מי שמעת אותו שאומר,\u0006 שהוא סבור \u0005שהולכים אחר ריבוי\u0006 האנשים\u0005]?\u0006 — \u0003ר' שמעון בן אלעזר\u0004 הוא, ואם כן, \u0003שמעת מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' שמעון בן אלעזר\u0004 הלכה זו הרי היא \u0003ברוב גוים, אבל ברוב ישראל\u0004 — \u0003לא!\u0004","את ההוכחה הזו דוחים: אפשר לומר כי \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — \u0003רבנן היא\u0004 \u0005[\u0006כשיטת \u0005חכמים היא]\u0006 החולקים על ר' שמעון. ואומרים: אם כן מכל מקום \u0003תפשוט מינה\u0004 \u0005[תפתור מכאן]\u0006 בעיה אחרת שלנו, שהרי מוכח מכאן \u0003דמודו ליה רבנן\u0004 \u0005[שמודים לו חכמים]\u0006 \u0003לר' שמעון בן אלעזר ברוב גוים!\u0004","ודוחים: \u0003אלא\u0004 יש לתרץ אחרת: \u0003לעולם\u0004 אותה משנה כשיטת \u0003ר' שמעון בן אלעזר היא, ו\u0004בדרך כלל \u0003אפילו ברוב ישראל נמי\u0004 \u0005[גם כן]\u0006 סבור הוא שהאבידה של המוצא, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003ב\u0004מקרה מיוחד שהיה הכסף \u0003טמון\u0004 באחד המקומות שם. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בטמון מאי עבידתיה גביה\u0004 \u0005[מה מעשהו אצלו],\u0006 כלומר, מה לו לאדם לקחת דבר שברור שאחד הניחו שם מדעתו שכיון שהניחו שם — יבוא בעליו ויקחהו! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא כלי באשפה,\u0004 מקום שהכל משליכים בו גרוטאות שונות, אם היה הכלי \u0003מכוסה\u0004 — \u0003לא יגע בו\u0004 שוודאי הטמינו שם אדם בכוונה, ואם היה הכלי \u0003מגולה\u0004 — \u0003נוטל ומכריז.\u0004","ומתרצים: יש לומר כאן \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב פפא\u0004 שם, שמדובר \u0003באשפה שאינה עשויה לפנות,\u0004 כלומר, היה זה גל גרוטאות שלא היה מיועד להיפנות משם כלל, \u0003ונמלך עליה\u0004 בעל המקום \u0003לפנותה\u0004 ונמצאו בה כלים, שאז ראוי למוצא לקחת אותם ולהכריז עליהם, שאם לא יעשה כן — יזרק הכל. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יכול אתה לפרש שמדובר \u0003באשפה שאינה עשויה לפנות, ונמלך עליה לפנותה\u0004 ומצא בה אבידה מונחת שם. ואז הולכים אחר רוב האנשים שבעיר, אם רובם יהודים — מכריז, ואם לאו — אינו חייב להכריז. ואין מכאן כל ראיה לענייננו."],["\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 המשנה הזו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, ואולם \u0003מי קתני\u0004 \u0005[האם שנה\u0006 שם\u0005]\u0006 המעות \u0003\"הן שלו\"?\u0004 הלא רק \u0003\"אינו חייב להכריז\" קתני\u0004 \u0005[שנה].\u0006 והכוונה היא: \u0003ויניח\u0004 המעות בידו ולא ישתמש בהן, \u0003וייתי\u0004 \u0005[ויבוא]\u0006 אדם מ\u0003ישראל ויהיב ביה סימנא ושקיל\u0004 \u0005[ויתן בה סימן ויקח].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ש\u0003אמר רב אסי: מצא חבית יין בעיר שרובה גוים,\u0004 חבית זו \u0003מותרת משום מציאה\u0004 שיש לשער שגוים איבדוה, \u0003ואסורה בהנאה,\u0004 שיין גוים אסור בהנאה. \u0003בא ישראל ונתן בה סימן\u0004 שהיא שלו — \u0003מותרת בשתיה,\u0004 שהרי הוכח שיין זה של ישראל היה, ואולם החבית שייכת \u0003למוצאה,\u0004 שכיון שאבדה במקום כזה מן הסתם כבר התייאשו הבעלים.","\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא קביעה זו? \u0003כ\u0004דעת \u0003ר' שמעון בן אלעזר.\u0004 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' שמעון בן אלעזר\u0004 — \u0003ברוב גוים\u0004 אמר, \u0003אבל ברוב ישראל\u0004 — \u0003לא.\u0004 ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003ר' שמעון בן אלעזר אפילו ברוב ישראל נמי קאמר\u0004 \u0005[גם כן אמר]\u0006 שהאבידה למוצא, \u0003ו\u0004אולם \u0003רב אסי סבר לה כוותיה בחדא\u0004 \u0005[סבור כשיטתו בדבר אחד]\u0006 ברוב גוים, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחד]\u0006 ברוב ישראל. ואין להוכיח מכאן לעצם שיטתו של ר' שמעון בן אלעזר.","על הלכה זו שאמר רב אשי שואלים: \u0003וכי מאחר דאסירא\u0004 \u0005[שאסורה]\u0006 \u0003בהנאה\u0004 מה שאמר \u0003מותרת משום מציאה,\u0004 \u0003למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה אמר]?\u0006 שהרי כיון שאסור לו ליהנות ממנה, מה היתר יש לו עוד בה? \u0003אמר רב אשי:\u0004 הכוונה היא \u0003לקנקנה,\u0004 שאמנם היין אסור, אבל בקנקן יכול להשתמש.","מסופר: \u0003ההוא גברא דאשכח\u0004 \u0005[אדם אחד שמצא]\u0006 \u0003ארבעה זוזי דציירי בסדינא ושדו\u0004 \u0005[ארבעה זוזים שהיו צרורים בסדין ומוטלים]\u0006 \u0003בנהר בירן, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יהודה\u0004 ושאל מה לעשות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אכריז\u0004 \u0005[לך והכרז].\u0006 ושואלים: \u0003והא\u0004 \u0005[הרי]\u0006 זה מקרה ברור של \u0003זוטו של ים\u0004 \u0005[גאות הים]\u0006 \u0003הוא\u0004 או שלולית הנהר, ומדוע לא יהיה הדבר שייך למוצא? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נהר בירן, כיון דמתקיל לא מיאש\u0004 \u0005[שיש בו מכשולים וסכרים\u0006 שונים \u0005אין\u0006 המאבד \u0005מתייאש],\u0006 שהוא יודע שהחפץ שאיבד שם יתקל באחד המכשולים, וסופו להימצא. ושואלים: \u0003והא רובא\u0004 \u0005[והרי הרוב]\u0006 \u0003גוים נינהו\u0004 \u0005[הם],\u0006 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אין הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר אפילו ברוב גוים!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נהר בירן,\u0004 ש\u0003ישראל סכרו ליה\u0004 \u0005[סוכרים אותו]\u0006 \u0003וישראל כרו ליה\u0004 \u0005[כורים אותו]\u0006 להעמיק את אפיקו. ולכן \u0003כיון\u0004 ש\u0003ישראל סכרו ליה\u0004 \u0005[סוכרים אותו]\u0006 — \u0003אימור\u0004 שמאדם \u0003מישראל נפל\u0004 הכסף, \u0003וכיון\u0004 ש\u0003ישראל כרו ליה\u0004 \u0005[כורים אותו]\u0006 — \u0003לא מיאש\u0004 \u0005[אין\u0006 המאבד \u0005מתייאש],\u0006 שכן הוא סבור שהכסף ימצא על ידי יהודים.","מספרים: \u0003רב יהודה הוה שקיל ואזיל בתריה\u0004 \u0005[היה מהלך אחר]\u0006 \u0003מר שמואל בשוקא דבי דיסא\u0004 \u0005[בשוק שמוכרים בו דיסא],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לשמואל: \u0003מצא כאן ארנקי מהו\u0004 דינו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי אלו שלו.\u0004 שאל אותו: ואם \u0003בא ישראל ונתן בה סימן מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חייב להחזיר.\u0004 תהה רב יהודה: \u0003תרתי\u0004 \u0005[שתים]?!\u0006 כלומר אלו שני דברים סותרים. שאם אמרת הרי אלו שלו משמע שאינו צריך להחזיר! \u0003אמר ליה\u0004 \u0005[לו]!\u0006 אני מתכוון לאדם שעושה זאת \u0003לפנים משורת הדין.\u0004 כלומר: אכן החפץ, מצד הדין, שייך למוצא ואינו צריך להכריז עליו, אבל אם מתברר לו שהארנק שייך לאדם מסויים ראוי בכל זאת שיחזירנו. \u0003כי הא דאבוה\u0004 \u0005[כמו\u0006 מעשה \u0005זה שאביו]\u0006 של \u0003שמואל אשכח הנך חמרי במדברא ואהדרינהו למרייהו לבתר תריסר ירחי שתא\u0004 \u0005[מצא חמורים במדבר והחזירם לבעליהם לאחר שנים עשר חודשי שנה],\u0006 כשוודאי כבר התייאשו הבעלים, ועשה זאת \u0003לפנים משורת הדין.\u0004","וכיוצא בו מסופר: \u0003רבא הוה שקיל ואזיל בתריה\u0004 \u0005[היה מהלך אחרי]\u0006 \u0003רב נחמן בשוקא דגלדאי\u0004 \u0005[בשוק מוכרי העורות],\u0006 \u0003ואמרי ליה בשוקא דרבנן\u0004 \u0005[ויש אומרים\u0006 שהיה זה \u0005בשוק החכמים],\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 שאל אותו: \u0003מצא כאן ארנקי מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי אלו שלו.\u0004 שאל: ואילו \u0003בא ישראל ונתן בה סימן מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי אלו שלו\u0004 של המוצא. אמר לו רבא: \u0003והלא עומד\u0004 המאבד \u0003וצווח,\u0004 שהרי ברור שהארנק הוא שלו! אמר לו רב נחמן: \u0003נעשה כצווח על ביתו שנפל ועל ספינתו שטבעה בים,\u0004 כלומר, מצד הדין איבד בעל הארנק את זכותו, ואין לו אלא להצטער על כך, כפי שקורה בכל אסון אחר.","מסופר: \u0003ההוא דיו דשקיל בשרא בשוקא ושדיה בצנייתא דבי\u0004 \u0005[דיה אחת חטפה בשר בשוק וזרקה אותו בין הדקלים של בית]\u0006 \u0003בר מריון. אתא לקמיה\u0004 \u0005[בא\u0006 המוצא \u0005לפני]\u0006 \u0003אביי\u0004 לשאול מה לעשות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקול לנפשך\u0004 \u0005[לך קח לעצמך].\u0006 ומקשים: \u0003והא רובא\u0004 \u0005[והרי רוב]\u0006 \u0003ישראל נינהו\u0004 \u0005[הם]\u0006 שם בשוק הבשר הכשר, \u0003שמעת מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר אפילו ברוב ישראל!\u0004 ודוחים: \u0003שאני דיו\u0004 \u0005[שונה\u0006 חטיפת \u0005הדיה]\u0006 ש\u0003כזוטו של ים דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 שדבר כזה נעשה ממילא הפקר. ומקשים מצד אחר: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב: בשר שנתעלם מן העין,\u0004 שבמשך זמן מסויים נעלם והיה בלא השגחה — \u0003אסור,\u0004 שמא נתחלף בבשר אחר שאין אנו יודעים מה מקורו, והוא טריפה. ומשיבים: כאן מדובר \u0003בעומד ורואהו,\u0004 שראו למן השעה שחטפה הדיה את הבשר, עד לרגע שנפל לה בין הדקלים.","מסופר: \u0003ר' חנינא מצא גדי שחוט בין טבריא\u0004 (טבריה) \u0003לציפורי והתירוהו לו. אמר ר' אמי: התירוהו לו משום מציאה, כ\u0004דעת \u0003ר' שמעון בן אלעזר,\u0004 והתירוהו לו \u0003משום שחיטה\u0004 שאינו צריך לחשוש לכשרות הבשר, \u0003כ\u0004דעתו של \u0003ר' חנניא בנו של ר' יוסי הגלילי. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרי שאבדו לו גדייו ותרנגוליו, הלך ומצאן שחוטין, ר' יהודה אוסר\u0004 שמא לא נשחטו כדין, \u0003ו\u0004אילו \u0003ר' חנניא בנו של ר' יוסי הגלילי מתיר,\u0004 שאם שחוטים הם, מן הסתם נשחטו כהלכה.","\u0003אמר רבי: נראין דברי ר' יהודה כשמצאן באשפה\u0004 שאז יש לחשוש שהשחיטה נפסלה, ולכן זרקם שם. \u0003ודברי ר' חנניא בנו של ר' יוסי הגלילי כשמצאן בבית.\u0004 ומעתה נדייק לענייננו: \u0003מ\u0004כיון ש\u0003התירוהו\u0004 \u0003לו משום\u0004 שחיטה, משמע \u0003רובא\u0004 \u0005[\u0006ש\u0005רוב]\u0006 המצויים שם \u0003ישראל נינהו\u0004 \u0005[הם],\u0006 \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 ש\u0003הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר אפילו ברוב ישראל!\u0004 ודוחים, \u0003אמר רבא:\u0004 מדובר שם שה\u0003רוב גוים,\u0004 אולם \u0003רוב טבחי\u0004 \u0005[הטבחים,\u0006 השוחטים\u0005]\u0006 הם \u0003ישראל.\u0004","מסופר: \u0003ר' אמי אשכח\u0004 \u0005[מצא]\u0006 \u0003פרגיות שחוטות בין טבריא לציפורי, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אסי, ואמרי לה לקמיה\u0004 \u0005[ויש אומרים\u0006 שבא \u0005לפני]\u0006 \u0003ר' יוחנן, ואמרי לה בי מדרשא\u0004 \u0005[ויש אומרים בבית המדרש].\u0006 \u0003ו\u0004\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקול לנפשך\u0004 \u0005[לך קח לעצמך].\u0006 וכיוצא בו מסופר: \u0003ר' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003אשכח קיבורא דאזלי ביה אזלויי\u0004 \u0005[מצא פקעת חוטים שעושים ממנה רשתות],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן, ואמרי לה בבי מדרשא\u0004 \u0005[ויש אומרים בבית המדרש],\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שקול לנפשך\u0004 \u0005[לך קח לעצמך],\u0006 כיון שנמצאה האבידה במקום שרבים מצויים שם.","\u0003ואלו\u0004 המציאות ש\u0003חייב להכריז: מצא פירות בכלי, או כלי כמות שהוא,\u0004 שיש כרגיל סימנים בכלי, \u0003מעות ב\u0004תוך \u0003כיס\u0004 כסף, \u0003או כיס כמות שהוא, צבורי פירות, צבורי מעות\u0004"],["\u0003שלשה מטבעות\u0004 מונחים \u0003זה על גב זה, כריכות\u0004 (אלומות תבואה) \u0003ברשות היחיד, וככרות\u0004 לחם \u0003של בעל הבית,\u0004 שכל אדם עושה לעצמו ויש להם יחוד בצורתם, \u0003וגיזי צמר הלקוחין מבית האומן,\u0004 שכל אומן מעבד אותם בצורה שונה במקצת, \u0003כדי יין וכדי שמן\u0004 — \u0003הרי\u0004 על כל \u0003אלו חייב להכריז.\u0004","ומדייקים בלשון המשנה: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003מצא פירות\u0004 המונחים \u0003ב\u0004תוך \u0003כלי ומעות\u0004 המונחים \u0003ב\u0004תוך \u0003כיס. הא\u0004 \u0005[הרי]\u0006 אילו מצא \u0003כלי ולפניו פירות,\u0004 או \u0003כיס ולפניו מעות\u0004 — \u0003הרי אלו שלו.\u0004 לפי זה \u0003תנינא להא\u0004 \u0005[שנינו\u0006 במשנה \u0005דבר זה],\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 במפורש בברייתא: \u0003מצא כלי ולפניו פירות, כיס ולפניו מעות\u0004 — \u0003הרי אלו שלו.\u0004 מצא \u0003מקצתן\u0004 של הפירות \u0003בכלי, ומקצתן על גבי קרקע,\u0004 או \u0003מקצתן\u0004 של המעות \u0003בכיס ומקצתן על גבי קרקע\u0004 — \u0003חייב להכריז,\u0004 שהרי אז ברור שמשם נפלו.","\u0003ורמינהו\u0004 \u0005[ומשליכים, מראים סתירה]\u0006 מברייתא אחרת: \u0003מצא דבר שאין בו סימן\u0004 שהיה \u0003בצד דבר שיש בו סימן\u0004 — \u0003חייב להכריז.\u0004 ואם \u0003בא בעל\u0004 החפץ שיש בו \u0003סימן ונטל את שלו\u0004 ולא תבע את הדבר האחר שאין בו סימן — \u0003זכה הלה,\u0004 המוצא, \u0003בדבר שאין בו סימן.\u0004 ומדוע לא נאמר כן אף בכלי ובפירות שלפניו!","\u0003אמר רב זביד: לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 מדובר \u0003בכובא וכיתנא\u0004 \u0005[בכלי ובפשתן]\u0006 שבתוכו, שאם נפל — משם נפל, שהרי סיבי הפשתן מחוברין יחד ואם חלקם מחוץ לכלי וחלקם בתוכו — ודאי ממנו נפלו. \u0003הא בצנא ופירי\u0004 \u0005[כאן בכלי ופירות],\u0006 שאם לא נשתייר מאומה מן הפירות בכלי, מן הסתם לא ממנו נפלו, שהרי אינם מחוברים אחד לאחר ואם מן הכלי נפלו הרי היה על חלקם להישאר בתוכו, וכיון שכולם מחוץ לו, מן הסתם לא נפלו כלל ממנו (תוס').","\u0003רב פפא אמר : הא והא בצנא ופירי\u0004 \u0005[זה וזה\u0006 מדובר \u0005בכלי ופירות]\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003הא דאשתייר\u0004 \u0005[זו שנשאר]\u0006 \u0003בה מידי\u0004 \u0005[דבר],\u0006 \u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 ש\u0003לא אשתייר\u0004 \u0005[נשאר]\u0006 \u0003בה מידי\u0004 \u0005[דבר],\u0006 שנראה שאין קשר בין הכלי והפירות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדובר באופן ש\u0003לא אשתייר\u0004 \u0005[נשאר]\u0006 \u0003בה מידי\u0004 \u0005[דבר],\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 כי \u0003הא דמהדרי אפיה\u0004 \u0005[זה שמופנים פני]\u0006 הכלי \u0003לגבי פירי\u0004 \u0005[הפירות],\u0006 ואז מסתבר שממנו נפלו, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא דמהדרי אפיה\u0004 \u0005[פונים פני]\u0006 הכלי \u0003לגבי פירי\u0004 \u0005[הפירות].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא דמהדרי אפיה\u0004 \u0005[פונים פני]\u0006 הכלי \u0003לגבי פירי\u0004 \u0005[הפירות],\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003הא דאית\u0004 \u0005[זה שיש]\u0006 \u0003לה\u0004 לכלי \u0003אוגנין\u0004 (שפה לפיו) \u0003לצנא\u0004 \u0005[של הכלי],\u0006 שאז קשה לשער שיכלו כל הפירות ולא ישתייר בתוכו מאומה, \u0003הא דלית\u0004 \u0005[זה שאין]\u0006 \u0003לה\u0004 לכלי \u0003אוגנין לצנא\u0004 \u0005[לכלי],\u0006 שבמקרה כזה אפשר לשער שכל הפירות נפלו ולא נשארו מהם כלל בפנים.","שנינו במשנה שאם מצא \u0003צבורי פירות\u0004 או \u0003צבורי מעות\u0004 — חייב להכריז. ומעירים: \u0003שמעת מינה\u0004 \u0005[למד אתה מכאן]\u0006 כי \u0003מנין הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן,\u0004 שהרי ודאי הסימן שנותן הריהו: כמה ציבורי פירות היו שם. ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן כגירסה: \u0003\"צבור פירות\",\u0004 שלא המנין הוא סימן אלא המקום. ואומרים: אם כן, על כל פנים \u0003שמעת מינה\u0004 \u0005[למד אתה מכאן]\u0006 כי \u0003מקום הוי\u0004 \u0005[הריהו]\u0006 \u0003סימן,\u0004 ותיפתר על ידי כך בעיה אחרת! ודוחים: מכאן אין להוכיח, \u0003תני\u0004 \u0005[שנה]\u0006 כמו שאנו שונים: \u0003\"צבורי פירות\".\u0004 שאין הגירסה ברורה, ואין להוכיח ממנה בוודאות.","שנינו במשנה: מצא \u0003שלשה מטבעות\u0004 המונחים \u0003זה על גב זה\u0004 מכריז. \u0003אמר ר'\u0004 \u0003יצחק\u0004 מן העיר \u0003מגדלאה\u0004 \u0005[מגדל]\u0006 \u0003והוא שעשויין\u0004 המטבעות \u0003כמגדלין\u0004 כלומר, מונחים זה על זה באופן מסודר. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003מצא מעות מפוזרות\u0004 — \u0003הרי אלו שלו, עשויין כמגדלים\u0004 — \u0003חייב להכריז. ואלו הן עשויין כמגדלים\u0004 — \u0003שלשה מטבעין זה על גב זה.\u0004","ומעירים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה,\u0006 הברייתא, \u0005קשה]\u0006 \u0003אמרת\u0004 מצד אחד כי אם \u0003מצא מעות מפוזרות הרי אלו שלו,\u0004 ומכאן אפשר להסיק: \u0003הא משלחפי שלחופי\u0004 \u0005[הרי אם היו מונחות קצת זו על גבי זו]\u0006 \u0003חייב להכריז,\u0004 שהרי אינן מפוזרות לגמרי. \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של הברייתא: אם מצא את המטבעות כשהן \u0003עשויין כמגדלין חייב להכריז,\u0004 ונדייק: רק אם היו כמגדלים, \u0003הא משלחפי שלחופי\u0004 \u0005[הרי\u0006 אם \u0005היו מונחים במקצת זה על גב זה]\u0006 \u0003הרי אלו שלו!\u0004 ומשיבים: יש להבין כי ה\u0003תנא\u0004 בברייתא \u0003כל שאין עשויין כמגדלין\u0004 — \u0003מפוזרות קרי להו\u0004 \u0005[קורא\u0006 הוא \u0005אותן].\u0006","\u0003אמר ר'\u0004 \u0003חנינא: לא שנו אלא\u0004 שהיו המטבעות \u0003של שלשה מלכים,\u0004 כלומר, מטבעות שאינם מאותו סוג, \u0003אבל של מלך אחד\u0004 שהיו כולן שוות — \u0003אינו חייב להכריז.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003עשויין כמגדלין\u0004 — \u0003אפילו של מלך אחד נמי\u0004 \u0005[גם כן],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003אין עשויין כמגדלים\u0004 — \u0003אפילו של שלשה מלכים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא!\u0004","\u0003אלא\u0004 יש לתקן את הגירסה ולומר כי \u0003אי אתמר, הכי אתמר\u0004 \u0005[אם נאמר, כך נאמר]:\u0006 \u0003לא שנו אלא\u0004 אם שלושת המטבעות היו \u0003של מלך אחד כעין שלשה מלכים, אבל\u0004 אם היו \u0003של מלך אחד\u0004 סתם — \u0003אינו חייב להכריז. והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]\u0006 ענין ש\u0003עשויין כמגדלים?\u0004 \u0003רויחא תתאה ומציעא עילויה וזוטא עילויה מציעא\u0004 \u0005[הרחב\u0006 שבהם — \u0005תחתון, והאמצעי\u0006 — \u0005עליו, והקטן\u0006 — \u0005על האמצעי].\u0006 \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 ודאי \u0003אנוחי אנחינהו\u0004 \u0005[הניח אותם]\u0006 בעליהן שם, ולכן אינם אבידה. \u0003אבל\u0004 אם היו המטבעות \u0003של מלך אחד, דכולהו כי הדדי נינהו\u0004 \u0005[שכולם הם זה כמו זה]\u0006 \u0003אף על גב דמנחי אהדדי\u0004 \u0005[אף על פי שהם מונחים יחד]\u0006 — \u0003הרי אלו שלו, אימר אתרמויי אתרמי ובהדי הדדי נפול\u0004 \u0005[אמור שמא הזדמן הדבר וכולם כאחד נפלו]\u0006 והסתדרו זה אחר זה, ואין בכך סימן.","\u0003ורבי יוחנן אמר: אפילו של מלך אחד נמי\u0004 \u0005[גם כן]\u0006 \u0003מכריז. מאי\u0004 \u0005[מה]\u0006 \u0003מכריז?\u0004 — מכריז \u0003מנין,\u0004 כלומר, מכריז שמצא מטבעות, והמאבד אומר כמה היה. ושואלים: אם כך \u0003מאי איריא תלתא\u0004 \u0005[מה שייך, מדוע דווקא, שלושה]\u0006 מטבעות? \u0003אפילו תרי נמי\u0004 \u0005[שתים גם כן].\u0006 \u0003אמר רבינא: טבעא\u0004 \u0005[מטבעות]\u0006 \u0003מכריז,\u0004 כלומר, המוצא מכריז: מצאתי מטבעות, וכיון שאומר בלשון רבים מובן שמצא לפחות שניים, ולכן האומר שאבד שתים אינו נותן על ידי כך כל סימן. ומשום כך, רק אם יש שלושה יש בכך סימן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 מצא את המטבעות מונחים \u0003כשיר\u0004 \u0005[כצמיד]\u0006 בעיגול, \u0003מהו? כשורה\u0004 ישרה, \u0003מהו? כחצובה\u0004 \u0005[כמשולש],\u0006 \u0003מהו? כסולם\u0004 שהיו מונחים קצת זה על גבי זה בקו ישר אחד, \u0003מהו?\u0004","ומעירים: \u0003פשוט מהא חדא\u0004 \u0005[פתור מאלה אחת]\u0006 לפחות, שכן \u0003אמר רב נחמן אמר רבה בר אבוה\u0004 לגבי מטבעות הנמצאים יחד: \u0003כל שאילו מכניס לה קיסם ביניהם ונוטלם בבת אחת\u0004 הרי זו הוכחה שלא באקראי נפלו הרי הוא \u0003חייב להכריז.\u0004 ולפי זה מטבעות הנמצאים כשורה או כסולם חייבים להכריז.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004"],["\u0003כאבני בית קוליס\u0004 (כאבנים שמניחים לעבודה זרה של מרקוליס), \u0003מהו?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מן הברייתא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצא מעות מפוזרות\u0004 — \u0003הרי אלו שלו,\u0004 היו מונחים \u0003כאבני בית קוליס\u0004 — \u0003חייב להכריז. ואלו הן אבני בית קוליס: אחת מכאן ואחת מכאן ואחת על גביהן.\u0004","ובדיני מציאת מטבעות בכלל \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוצא סלע\u0004 (מטבע) \u0003בשוק, ומצאו חבירו ואמר\u0004 לו: \u0003שלי היא\u0004 מטבע זו, וסימנך כי \u0003חדשה היא,\u0004 או ש\u0003נירונית היא\u0004 (של נירון קיסר) או \u0003של מלך פלוני היא\u0004 — \u0003לא אמר כלום\u0004 ואינו חייב להחזיר לו. \u0003ולא עוד, אלא אפילו\u0004 היה \u0003שמו\u0004 של המאבד \u0003כתוב עליה\u0004 — \u0003לא אמר כלום,\u0004 ומדוע? — \u0003לפי שאין סימן למטבע. דאמר\u0004 \u0005[שאומר]\u0006 המוצא: \u0003דלמא אפוקי אפקא ומאיניש אחרינא נפל\u0004 \u0005[שמא הוציאה\u0006 המאבד \u0005לקנות בה\u0006 \u0005ומאדם אחר נפלה]\u0006 ולכן, מטבע כיון שעשויה לעבור מאדם לאדם, אין משמעות לסימן שנותן בה.","\u0003מצא אחר הגפה\u0004 (גדר עץ) \u0003או אחר הגדר\u0004 של אבן \u0003גוזלות מקושרים, או\u0004 מצא אותם \u0003בשבילין שבשדות\u0004 — \u0003הרי זה לא יגע בהן,\u0004 שודאי הניחם אדם שם. \u0003מצא כלי באשפה\u0004 שהוא מקום שבו זורקים גרוטאות שונות, \u0003אם\u0004 היה הכלי \u0003מכוסה\u0004 — \u0003לא יגע בו\u0004 שבודאי הטמינו אדם שם, \u0003אם מגולה\u0004 — \u0003נוטל ומכריז.\u0004","לגבי המוצא גוזלות מקושרים שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אומרים שלא יטלם? — \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003הני, אינש אצנעינהו\u0004 \u0005[\u0006את \u0005אלה, אדם\u0006 מסויים \u0005הצניע],\u0006 \u0003ואי שקיל להו\u0004 \u0005[ואם יקח אותם]\u0006 — \u0003לית להו למרייהו סימנא בגווייהו\u0004 \u0005[אין להם לבעליהם סימן בהם],\u0006 \u0003הלכך לשבקינהו\u0004 \u0005[על כן יניחם]\u0006 \u0003עד דאתי מרייהו ושקיל להו\u0004 \u0005[שיבוא בעליהם ויקח אותם].\u0006","\u0003ו\u0004שואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 ה\u0003קשר\u0004 שקשורים בהם \u0003סימנא\u0004 \u0005[סימן]!\u0006 \u0003אמר ר'\u0004 \u0003אבא בר זבדא אמר רב:\u0004 מדובר כאן \u0003ב\u0004אופן שהם \u0003מקושרין בכנפיהן, דכולי עלמא הכי מקטרי להו\u0004 \u0005[שהכל כך קושרין אותם]\u0006 ולכן אין הקשר סימן.","ושואלים: \u0003ולהוי\u0004 \u0005[ושיהא]\u0006 ה\u0003מקום\u0004 שבו הונחו \u0003סימן! אמר רב עוקבא בר חמא:\u0004 פה מדובר \u0003ב\u0004גוזלות ה\u0003מדדין\u0004 \u0005[קופצין]\u0006 ממקום למקום, ושמא דלגו מן המקום שהניחם שם. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003במדדין\u0004 שמא \u0003מעלמא אתו\u0004 \u0005[מן החוץ באו]\u0006 \u0003ומותרים,\u0004 שהרי יתכן שאינם אותם גוזלים שהונחו שם, אלא ממקום אחר הגיעו, וכבר התייאש מהם בעליהם!","ומשיבים: אכן \u0003איכא למימר מעלמא אתו\u0004 \u0005[יש מקום לומר שמהחוץ באו]\u0006 \u0003ואיכא למימר אינש אצנעינהו\u0004 \u0005[ויש\u0006 מקום \u0005לומר\u0006 ש\u0005אדם הצניעם\u0006 שם\u0005],\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003ספק הינוח,\u0004 שיש ספק אם הונחו שם אם לאו, \u0003ואמר ר'\u0004 \u0003אבא בר זבדא אמר רב: כל ספק הינוח,\u0004 שאין זה ברור שהוא אבידה, ושמא הונח שם מדעת — \u0003לכתחילה לא יטול\u0004 אותו, \u0003ואם נטל לא יחזיר,\u0004 שהרי אין בו סימן.","שנינו במשנה שאם \u0003מצא כלי באשפה,\u0004 אם הוא \u0003מכוסה\u0004 — \u0003לא יגע בו,\u0004 ואם הוא \u0003מגולה\u0004 — \u0003נוטל ומכריז. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו בברייתא: \u0003מצא כלי טמון באשפה\u0004 — \u0003נוטל ומכריז.\u0004 וטעמו של דבר \u0003שכן דרך אשפה לפנות,\u0004 ובודאי לא הטמין אדם כלי במקום שעלול להיות להיעלם משם, אלא ודאי אבד שם.","\u0003אמר רב זביד: לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאינו נוטל הוא \u0003בכובי וכסי\u0004 \u0005[בקנקנים וכוסות],\u0006 שגדולים הם, ולא ייתכן שנפלו שם בטעות, \u0003הא בסכיני והמניק\u0004 \u0005[זה בסכינים ומזלגות],\u0006 שיתכן שבמקרה, אגב דברים אחרים, נפלו גם הם. \u0003בכובי וכסי\u0004 — \u0003לא יגע,\u0004 \u0003בסכיני והמניק\u0004 שיש ספק שמא אבדו שם במקרה — \u0003נוטל ומכריז.\u0004","\u0003רב פפא אמר: הא והא\u0004 \u0005[זה וזה]\u0006 \u0003בכובי וכסי\u0004 \u0005[בקנקנים וכוסות],\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003כאן\u0004 בברייתא מדובר \u0003באשפה העשויה לפנות\u0004 שנוטל ומכריז, \u0003כאן\u0004 במשנה מדובר \u0003באשפה שאינה עשויה לפנות.\u0004","ותוהים: \u0003אשפה העשויה לפנות\u0004 אפילו אם טמן בה הרי \u0003אבידה מדעת היא,\u0004 שהרי יודע שעשויה לפנות וכאילו מפקיר מה שהניח שם! \u0003אלא\u0004 מדובר כאן \u0003באשפה שאינה עשויה לפנות, ונמלך עליה\u0004 בעל האשפה \u0003לפנותה.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב פפא\u0004 — \u0003היינו דקתני\u0004 \u0005[זה ששנינו]\u0006 בברייתא; \u0003שכן דרך אשפה לפנות,\u0004 שבכך הדבר תלוי, \u0003אלא ל\u0004דעת \u0003רב זביד, מאי\u0004 \u0005[מה]\u0006 פירוש \u0003שכן דרך אשפה לפנות,\u0004 הרי דבר זה אינו שייך לדעתו לטעם ההלכה? ומסבירים: כך יש להבין לשיטתו, \u0003שכן דרך אשפה לפנות לה כלים קטנים,\u0004 כלומר, מצוי הוא שיפלו בטעות לאשפה כלים קטנים ובעליהם איפוא מתייאשים מהם.","\u0003מצא\u0004 דבר \u0003בגל\u0004 אבנים או \u0003בכותל ישן\u0004 — \u0003הרי אלו שלו\u0004 של המוצא. \u0003מצא\u0004 אבידה \u0003בכותל חדש,\u0004 אם היה זה \u0003מחציו\u0004 של הכותל \u0003ולחוץ\u0004 כלפי רשות הרבים — הרי הם \u0003שלו\u0004 של המוצא, \u0003מחציו ולפנים\u0004 — \u0003של בעל הבית\u0004 הגר שם. \u0003אם היה\u0004 זה בית ש\u0003משכירו\u0004 בעל הבית \u0003לאחרים\u0004 ודייריו מתחלפים — \u0003אפילו\u0004 מצא דבר \u0003בתוך הבית\u0004 הריק \u0003הרי אלו שלו,\u0004 של המוצא, כיון שבעליו אינם ידועים ודאי אם כן שמי שהם שלו נתייאשו.","לגבי כותל ישן \u0003תנא\u0004 \u0005[שנה]\u0006 החכם כהסבר: \u0003מפני שיכול לומר לו\u0004 לבעל הגל או הכותל: \u0003של אמוריים הן,\u0004 כלומר, מימים קדומים האבידה, עוד מימי האמוריים (כנענים) שהיו כאן לפני כיבוש הארץ בידי ישראל. ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003אמורים מצנעי\u0004 \u0005[\u0006הם ש\u0005מטמינים]\u0006 דברים, ו\u0003ישראל לא מצנעי\u0004 \u0005[אינם מצניעים]?\u0006 ואם כן, הלא יתכן שבעל הבית הוא שהניח את החפצים בכותל ישן! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה המיוחד"]]};
